import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import * as dataService from '../services/dataService';
import { 
    Client, Property, Invoice, Staff, Lead, Promotion, 
    CompanySettings, ActivityLog, Role, AmendmentRequest 
} from '../types';
import { ROLES, AMENDMENT_REQUESTS as MOCK_AMENDMENT_REQUESTS } from '../data/mockData';

interface DataContextType {
    clients: Client[];
    properties: Property[];
    invoices: Invoice[];
    staff: Staff[];
    leads: Lead[];
    promotions: Promotion[];
    companySettings: CompanySettings;
    activityLogs: ActivityLog[];
    roles: Role[];
    amendments: AmendmentRequest[];

    // Actions
    saveClient: (client: Client) => Promise<Client>;
    deleteClient: (id: number) => Promise<void>;
    saveProperty: (property: Property) => Promise<void>;
    saveInvoice: (invoice: Invoice) => Promise<void>;
    saveLead: (lead: Lead) => Promise<void>;
    deleteLead: (id: number) => Promise<void>;
    savePromotion: (promotion: Promotion) => Promise<void>;
    deletePromotion: (id: number) => Promise<void>;
    updateStaff: (id: number, details: Partial<Staff>) => void;
    setStaff: React.Dispatch<React.SetStateAction<Staff[]>>;
    setRoles: React.Dispatch<React.SetStateAction<Role[]>>;
    setCompanySettings: React.Dispatch<React.SetStateAction<CompanySettings>>;
    addActivityLog: (type: ActivityLog['type'], description: string, userId?: number) => void;
    setAmendmentList: React.Dispatch<React.SetStateAction<AmendmentRequest[]>>;
    setInvoiceList: React.Dispatch<React.SetStateAction<Invoice[]>>;
    setClientList: React.Dispatch<React.SetStateAction<Client[]>>;
    setLeadList: React.Dispatch<React.SetStateAction<Lead[]>>;
    setPromotionList: React.Dispatch<React.SetStateAction<Promotion[]>>;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const appData = dataService.loadAppData();

    const [staffList, setStaffList] = useState<Staff[]>(appData.staff);
    const [clientList, setClientList] = useState<Client[]>(appData.clients);
    const [propertyList, setPropertyList] = useState<Property[]>(appData.properties);
    const [invoiceList, setInvoiceList] = useState<Invoice[]>(appData.invoices);
    const [roleList, setRoleList] = useState<Role[]>(ROLES);
    const [companySettings, setCompanySettings] = useState<CompanySettings>(appData.settings);
    const [activityLogs, setActivityLogs] = useState<ActivityLog[]>(appData.logs);
    const [leadList, setLeadList] = useState<Lead[]>(appData.leads);
    const [promotionList, setPromotionList] = useState<Promotion[]>(appData.promotions);
    const [amendmentList, setAmendmentList] = useState<AmendmentRequest[]>(MOCK_AMENDMENT_REQUESTS);

    // Persistence Effect
    useEffect(() => {
        dataService.saveAllData({
            clients: clientList,
            properties: propertyList,
            staff: staffList,
            invoices: invoiceList,
            leads: leadList,
            promotions: promotionList,
            settings: companySettings,
            logs: activityLogs
        });
    }, [clientList, propertyList, staffList, invoiceList, leadList, promotionList, companySettings, activityLogs]);

    const addActivityLog = useCallback((type: ActivityLog['type'], description: string, userId?: number) => {
        const newLog: ActivityLog = {
            id: Date.now(),
            userId: userId || 0, // Should be passed from AuthContext or call site
            type,
            description,
            timestamp: new Date().toISOString(),
        };
        setActivityLogs(prev => [newLog, ...prev]);
    }, []);

    // --- Actions ---

    const saveClient = async (client: Client) => {
        let updatedList: Client[];
        const exists = clientList.some(c => c.id === client.id);
        if (exists) {
            updatedList = clientList.map(c => c.id === client.id ? client : c);
        } else {
            updatedList = [client, ...clientList];
        }
        setClientList(updatedList);
        return client;
    };

    const deleteClient = async (clientId: number) => {
        setClientList(prev => prev.filter(c => c.id !== clientId));
    };

    const saveProperty = async (property: Property) => {
        let updatedList: Property[];
        const exists = propertyList.some(p => p.id === property.id);
        if (exists) {
            updatedList = propertyList.map(p => p.id === property.id ? property : p);
        } else {
            updatedList = [property, ...propertyList];
        }
        setPropertyList(updatedList);
    };

    const saveInvoice = async (invoice: Invoice) => {
        let updatedList: Invoice[];
        const exists = invoiceList.some(i => i.id === invoice.id);
        if (exists) {
            updatedList = invoiceList.map(i => i.id === invoice.id ? invoice : i);
        } else {
            updatedList = [invoice, ...invoiceList];
        }
        setInvoiceList(updatedList);
    };

    const saveLead = async (lead: Lead) => {
        let updatedList: Lead[];
        const exists = leadList.some(l => l.id === lead.id);
        if (exists) {
            updatedList = leadList.map(l => l.id === lead.id ? lead : l);
        } else {
            updatedList = [lead, ...leadList];
        }
        setLeadList(updatedList);
    };

    const deleteLead = async (leadId: number) => {
        setLeadList(prev => prev.filter(l => l.id !== leadId));
    };

    const savePromotion = async (promotion: Promotion) => {
        let updatedList: Promotion[];
        const exists = promotionList.some(p => p.id === promotion.id);
        if (exists) {
            updatedList = promotionList.map(p => p.id === promotion.id ? promotion : p);
        } else {
            updatedList = [promotion, ...promotionList];
        }
        setPromotionList(updatedList);
    };

    const deletePromotion = async (promotionId: number) => {
        setPromotionList(prev => prev.filter(p => p.id !== promotionId));
    };

    const updateStaff = (staffId: number, details: Partial<Staff>) => {
        setStaffList(prev => prev.map(s => s.id === staffId ? { ...s, ...details } : s));
    };

    return (
        <DataContext.Provider value={{
            clients: clientList,
            properties: propertyList,
            invoices: invoiceList,
            staff: staffList,
            leads: leadList,
            promotions: promotionList,
            companySettings,
            activityLogs,
            roles: roleList,
            amendments: amendmentList,
            saveClient,
            deleteClient,
            saveProperty,
            saveInvoice,
            saveLead,
            deleteLead,
            savePromotion,
            deletePromotion,
            updateStaff,
            setStaff: setStaffList,
            setRoles: setRoleList,
            setCompanySettings,
            addActivityLog,
            setAmendmentList,
            setInvoiceList,
            setClientList,
            setLeadList,
            setPromotionList
        }}>
            {children}
        </DataContext.Provider>
    );
};

export const useData = () => {
    const context = useContext(DataContext);
    if (context === undefined) {
        throw new Error('useData must be used within a DataProvider');
    }
    return context;
};

import React, { createContext, useContext, useState } from 'react';
import { Staff } from '../types';
import { useData } from './DataContext';

interface AuthContextType {
    currentStaff: Staff | null;
    login: (email: string, password: string) => { success: boolean; message: string };
    logout: () => void;
    isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { staff, addActivityLog } = useData();
    const [currentStaff, setCurrentStaff] = useState<Staff | null>(null);

    const login = (email: string, password: string) => {
        const user = staff.find(u => u.email === email && u.password === password);
        if (user) {
            setCurrentStaff(user);
            addActivityLog('Login', `User ${user.fullName} logged in.`, user.id);
            return { success: true, message: 'Login successful' };
        }
        return { success: false, message: 'Invalid credentials' };
    };

    const logout = () => {
        if (currentStaff) {
            addActivityLog('Logout', `User ${currentStaff.fullName} logged out.`, currentStaff.id);
        }
        setCurrentStaff(null);
    };

    return (
        <AuthContext.Provider value={{
            currentStaff,
            login,
            logout,
            isAuthenticated: !!currentStaff
        }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

import React, { useState } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import LeadsManagementPage from './pages/LeadsManagementPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import PlaceholderPage from './pages/PlaceholderPage';

import { DataProvider, useData } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ROLES, GENERATED_REPORTS } from './data/mockData';
import { Client } from './types';

const AppContent: React.FC = () => {
    const { 
        clients, properties, invoices, staff, leads, promotions, 
        companySettings, activityLogs, roles, amendments,
        saveClient, deleteClient, saveProperty, saveInvoice, 
        saveLead, deleteLead, savePromotion, deletePromotion,
        updateStaff, setStaff, setRoles, setCompanySettings,
        addActivityLog, setAmendmentList, setClientList
    } = useData();

    const { currentStaff, login, logout, isAuthenticated } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    // Helper for context-aware logger
    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        setActivePage(page);
        setPageContext(context);
    };

    if (!isAuthenticated || !currentStaff) {
        return <LoginPage onLogin={login} companySettings={companySettings} />;
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard':
                return <Dashboard />;
            case 'Clients':
                return <ClientsPage 
                    clients={clients} 
                    onSaveClient={saveClient}
                    onDeleteClient={deleteClient}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]}
                    onClientSelect={(client) => handleSetPage('Client Details', client)} 
                    setActivePage={handleSetPage}
                    setClientForInvoice={setClientForInvoice}
                    invoices={invoices}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Client Details':
                return <ClientDetailPage 
                    client={pageContext} 
                    properties={properties}
                    onBack={() => handleSetPage('Clients')}
                    currentStaff={currentStaff}
                    roles={roles}
                    setActivePage={handleSetPage}
                />;
            case 'Account Management':
                 return <AccountManagementPage 
                    clients={clients}
                    onSaveClient={saveClient}
                    onClientSelect={(client) => handleSetPage('Client Details', client)}
                    invoices={invoices}
                    onSaveInvoice={saveInvoice}
                    clientForInvoice={clientForInvoice}
                    setClientForInvoice={setClientForInvoice}
                    receiptPattern={null} 
                    setReceiptPattern={() => {}}
                    setReceiptAlerts={() => {}}
                    currentStaff={currentStaff}
                 />;
            case 'Settings':
                return <SettingsPage 
                    currentStaff={currentStaff} 
                    staff={staff}
                    setStaff={setStaff}
                    roles={roles}
                    setRoles={setRoles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    companySettings={companySettings}
                    setCompanySettings={setCompanySettings}
                    onUpdateStaff={updateStaff}
                />;
            case 'CEO Hub':
                 return <CEOHub
                    setActivePage={handleSetPage}
                    properties={properties}
                    clients={clients}
                    invoices={invoices}
                    staff={staff}
                    setStaff={setStaff}
                    roles={roles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    addActivityLog={handleAddActivityLog}
                />;
             case 'Properties':
                return <PropertiesPage properties={properties} currentStaff={currentStaff} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
             case 'New Land Acquisition':
                return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
             case 'Promotions':
                return <PromotionsPage 
                    promotions={promotions} 
                    onSavePromotion={savePromotion}
                    onDeletePromotion={deletePromotion}
                    properties={properties} 
                    showForm={true} 
                    onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} 
                />;
            case 'Administration':
                return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Lead Management & Follow-Up':
                return <LeadsManagementPage 
                    leads={leads} 
                    onSaveLead={saveLead}
                    onDeleteLead={deleteLead}
                    clients={clients} 
                    onSaveClient={saveClient}
                    staffList={staff} 
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }]} 
                    currentStaff={currentStaff} 
                    addActivityLog={handleAddActivityLog} 
                />;
            case 'Human Resources':
                return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} setStaff={setStaff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts':
                return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot':
                return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation':
                return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Amendment Form':
                return <AmendmentFormPage client={pageContext} onBack={() => handleSetPage('Client Details', pageContext)} onSave={(data) => { setAmendmentList(prev => [data, ...prev]); alert('Amendment saved!'); handleSetPage('Client Details', pageContext);}} currentStaff={currentStaff} />;
            case 'Analytics & Reports':
                return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports':
                return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity':
                return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Mailing':
            case 'Leave':
            case 'Knowledge Base':
            case 'Event':
            case 'Announcement':
            case 'Support':
                return <PlaceholderPage title={activePage} onBack={() => handleSetPage('Dashboard')} />;
            default:
                return <div>Page not found</div>;
        }
    };

    const staffPermissions = ROLES.find(r => r.id === currentStaff.roleId)?.name === 'CEO' 
        ? { Dashboard: { view: true }, Clients: { view: true }, 'Account Management': { view: true }, Promotions: { view: true }, Team: { view: true }, 'Leads Management': { view: true }, Administration: { view: true }, 'CEO Hub': { view: true }, Settings: { view: true } }
        : { Dashboard: { view: true }, Clients: { view: true }, 'Account Management': { view: true }, Team: { view: true }, 'Leads Management': { view: true }, Settings: { view: true } };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff} 
            onLogout={logout}
            staffPermissions={staffPermissions as any}
            companySettings={companySettings}
        >
            {renderPage()}
        </Layout>
    );
};

const App: React.FC = () => {
    return (
        <DataProvider>
            <AuthProvider>
                <AppContent />
            </AuthProvider>
        </DataProvider>
    );
};

export default App;

import React, { useMemo } from 'react';
import StatCard from '../components/StatCard';
import ChartPlaceholder from '../components/ChartPlaceholder';
import { BanknotesIcon, CheckCircleIcon, ClockIcon, DocumentDuplicateIcon, ExclamationTriangleIcon, UserGroupIcon } from '../components/icons/DummyIcons';
import { useData } from '../context/DataContext';

const Dashboard: React.FC = () => {
    const { clients, properties, invoices } = useData();

    const statsData = useMemo(() => {
        const totalClients = clients.length;
        const activeProcesses = clients.filter(c => c.stage !== 'COMP').length;
        const completedDeals = clients.filter(c => c.stage === 'COMP').length;
        const totalRevenue = clients.reduce((acc, client) => acc + client.payment.paid, 0);
        const pendingPayments = invoices.filter(i => i.status === 'Pending' || i.status === 'Overdue').length;
        const availablePlots = properties.reduce((acc, prop) => {
            const totalPlots = prop.inventory.reduce((sum, inv) => sum + inv.count, 0);
            const plotsSold = prop.inventory.reduce((sum, inv) => sum + inv.sold, 0);
            return acc + (totalPlots - plotsSold);
        }, 0);

        return { totalClients, activeProcesses, completedDeals, totalRevenue, pendingPayments, availablePlots };
    }, [clients, properties, invoices]);

    const formatCurrency = (amount: number) => `GHC${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

    const stats = [
        { title: "Total Clients", value: statsData.totalClients.toString(), change: "+0%", changeType: "increase" as const, icon: <UserGroupIcon className="w-8 h-8 text-blue-500" /> },
        { title: "Active Processes", value: statsData.activeProcesses.toString(), change: "+0%", changeType: "increase" as const, icon: <ClockIcon className="w-8 h-8 text-orange-500" /> },
        { title: "Completed Deals", value: statsData.completedDeals.toString(), change: "+0%", changeType: "increase" as const, icon: <CheckCircleIcon className="w-8 h-8 text-green-500" /> },
        { title: "Total Revenue", value: formatCurrency(statsData.totalRevenue), change: "+0%", changeType: "increase" as const, icon: <BanknotesIcon className="w-8 h-8 text-teal-500" /> },
        { title: "Pending Payments", value: statsData.pendingPayments.toString(), change: "-0%", changeType: "decrease" as const, icon: <ExclamationTriangleIcon className="w-8 h-8 text-red-500" /> },
        { title: "Available Plots", value: statsData.availablePlots.toString(), change: "+0%", changeType: "increase" as const, icon: <DocumentDuplicateIcon className="w-8 h-8 text-purple-500" /> },
    ];

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800">Dashboard</h1>
                    <p className="text-gray-500 mt-1">Real-time business analytics and insights</p>
                </div>
                <button className="bg-gray-800 text-white font-semibold py-2 px-4 rounded-lg hover:bg-gray-700 transition-colors">
                    Export Report
                </button>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-6">
                {stats.map(stat => (
                    <StatCard key={stat.title} {...stat} />
                ))}
            </div>

            {/* Charts Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                 <ChartPlaceholder title="Revenue Trend" change="+0%" />
                 <ChartPlaceholder title="Client Growth" change="+0%" />
                 <ChartPlaceholder title="Process Status Distribution" />
            </div>
        </div>
    );
};

export default Dashboard;

import React from 'react';

const Footer: React.FC = () => {
  return (
    <footer className="w-full p-6 text-center text-sm bg-gray-900 text-gray-400 border-t border-gray-800">
      <p>&copy; {new Date().getFullYear()} FAIM. All rights reserved.</p>
      <p className="mt-1 text-gray-500">Your trusted partner in finding the perfect home.</p>
    </footer>
