import { initializeApp } from "firebase/app";
import { getAuth } from "firebase/auth";

const firebaseConfig = {
  apiKey: "AIzaSyBae68-qqWHrK6mCiytpTDvqrTRAXcInhI",
  authDomain: "legacy-erp.firebaseapp.com",
  projectId: "legacy-erp",
  storageBucket: "legacy-erp.firebasestorage.app",
  messagingSenderId: "91000083788",
