// Initialize Firebase
const app = initializeApp(firebaseConfig);
export const auth = getAuth(app);

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Staff } from '../types';
import { useData } from './DataContext';
import { auth } from '../services/firebase';
import { signInWithEmailAndPassword, signOut, onAuthStateChanged } from 'firebase/auth';

interface AuthContextType {
    currentStaff: Staff | null;
    login: (email: string, password: string) => Promise<{ success: boolean; message: string }>;
    logout: () => Promise<void>;
    isAuthenticated: boolean;
    loading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { staff, addActivityLog } = useData();
    const [currentStaff, setCurrentStaff] = useState<Staff | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, (firebaseUser) => {
            if (firebaseUser && firebaseUser.email) {
                // Match Firebase user with local Staff record
                const matchedStaff = staff.find(s => s.email.toLowerCase() === firebaseUser.email!.toLowerCase());
                if (matchedStaff) {
                    setCurrentStaff(matchedStaff);
                } else {
                    console.warn("User logged in via Firebase but no matching staff record found.");
                    setCurrentStaff(null);
                }
            } else {
                setCurrentStaff(null);
            }
            setLoading(false);
        });

        return () => unsubscribe();
    }, [staff]);

    const login = async (email: string, password: string) => {
        try {
            const userCredential = await signInWithEmailAndPassword(auth, email, password);
            const user = userCredential.user;

            const matchedStaff = staff.find(s => s.email.toLowerCase() === email.toLowerCase());

            if (matchedStaff) {
                // setCurrentStaff is handled by onAuthStateChanged, but we can set it here for immediate feedback if needed.
                // However, waiting for onAuthStateChanged is safer.
                addActivityLog('Login', `User ${matchedStaff.fullName} logged in via Firebase.`, matchedStaff.id);
                return { success: true, message: 'Login successful' };
            } else {
                // If auth succeeds but user is not in staff list, sign them out immediately
                await signOut(auth);
                return { success: false, message: 'Access denied. User not found in staff records.' };
            }
        } catch (error: any) {
            console.error("Firebase login error:", error);
            let message = 'Invalid credentials';
            if (error.code === 'auth/user-not-found') message = 'User not found';
            if (error.code === 'auth/wrong-password') message = 'Invalid password';
            if (error.code === 'auth/too-many-requests') message = 'Too many failed attempts. Try again later.';
            return { success: false, message };
        }
    };

    const logout = async () => {
        if (currentStaff) {
            addActivityLog('Logout', `User ${currentStaff.fullName} logged out.`, currentStaff.id);
        }
        await signOut(auth);
        setCurrentStaff(null);
    };

    return (
        <AuthContext.Provider value={{
            currentStaff,
            login,
            logout,
            isAuthenticated: !!currentStaff,
            loading
        }}>
            {!loading && children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

import React, { useState } from 'react';
import { FaimLogoIcon, LoaderIcon } from '../components/icons/DummyIcons';
import { CompanySettings } from '../types';

interface LoginPageProps {
    onLogin: (email: string, password: string) => Promise<{ success: boolean, message: string }>;
    companySettings: CompanySettings;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin, companySettings }) => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);
        try {
            const result = await onLogin(email, password);
            if (!result.success) {
                setError(result.message);
            }
        } catch (err) {
            setError('An unexpected error occurred.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-100 p-4">
            <div className="w-full max-w-md p-8 space-y-8 bg-white rounded-xl shadow-2xl">
