import React, { useState, useMemo, useCallback, ChangeEvent, FormEvent, useEffect } from 'react';
import { 
    ChevronDownIcon, 
    DocumentPlusIcon, 
    MagnifyingGlassIcon, 
    UploadIcon, 
    ChevronLeftIcon, 
    ChevronRightIcon, 
    DocumentTextIcon, 
    CheckCircleIcon, 
    ExclamationTriangleIcon 
} from '../components/icons/DummyIcons';
import { XIcon } from '../components/icons/XIcon';
import ClientListItem from '../components/ClientListItem';
import { Client, Milestone, Property, Invoice, ActivityLog } from '../types';
import ClientForm, { FormData } from '../components/ClientForm';
import CSVImportWizard from '../components/CSVImportWizard';


interface ClientsPageProps {
    onClientSelect: (client: Client) => void;
    clients: Client[];
    onSaveClient: (client: Client) => Promise<Client>;
    onDeleteClient: (clientId: number) => Promise<void>;
    properties: Property[];
    milestones: Milestone[];
    setActivePage: (page: string) => void;
    setClientForInvoice: (client: Client) => void;
    invoices: Invoice[];
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const isClientDataComplete = (formData: FormData, existingClient?: Client | null): boolean => {
    const requiredFields: (keyof FormData)[] = [ 'surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
    for (const field of requiredFields) {
        if (!formData[field] || String(formData[field]).trim() === '') return false;
    }
    if (!formData.filledFormPdf && !existingClient?.filledFormPdf) return false;
    return true;
};

const ClientsPage: React.FC<ClientsPageProps> = ({ onClientSelect, clients, onSaveClient, onDeleteClient, properties, milestones, setActivePage, setClientForInvoice, invoices, addActivityLog }) => {
    const [isClientFormOpen, setClientFormOpen] = useState(false);
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [deletedClientInfo, setDeletedClientInfo] = useState<{ name: string; timeoutId: ReturnType<typeof setTimeout> } | null>(null);


    useEffect(() => {
        return () => {
            if (deletedClientInfo) {
                clearTimeout(deletedClientInfo.timeoutId);
            }
        };
    }, [deletedClientInfo]);


    const handleDeleteClient = useCallback(async (clientId: number) => {
        const clientToDelete = clients.find(c => c.id === clientId);
        if (clientToDelete) {
             await onDeleteClient(clientId);
        }
    }, [clients, onDeleteClient]);


    const filteredClients = useMemo(() => {
        if (!searchTerm.trim()) {
            return clients;
        }
        const lowercasedFilter = searchTerm.toLowerCase();
        return clients.filter(client =>
            (client.name && client.name.toLowerCase().includes(lowercasedFilter)) ||
            (client.email && client.email.toLowerCase().includes(lowercasedFilter)) ||
            (client.phone && client.phone.includes(searchTerm)) ||
            (client.plot && client.plot.toLowerCase().includes(lowercasedFilter))
        );
    }, [clients, searchTerm]);

    const createClientObject = (formData: FormData, existingClient?: Client | null): Client => {
        const newId = existingClient ? existingClient.id : (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);

        const fullName = `${formData.surname} ${formData.otherNames}`;
        const nameParts = fullName.split(' ');
        const initials = (nameParts[0]?.[0] || '' + nameParts[nameParts.length - 1]?.[0] || '').toUpperCase();

        const selectedProperty = properties.find(p => p.location === formData.location);
        let propertyPrice = selectedProperty ? selectedProperty.price : 200000;

        const plotCount = formData.plotNumber.split(',').map(p => p.trim()).filter(Boolean).length || 1;
        let baseTotal = propertyPrice * plotCount;

        let promoDetails: string | undefined = undefined;
        if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
            baseTotal *= (1 - selectedProperty.discount.percentage / 100);
            promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
        }

        const isComplete = isClientDataComplete(formData, existingClient);

        const baseClient = existingClient || {
            id: newId,
            status: 'Active Client',
            stage: milestones[0]?.acronym || 'N/A',
            payment: {
                total: baseTotal,
                paid: 0,
                balance: baseTotal,
                dueDate: 'N/A',
                planType: 'N/A',
                promoDetails: promoDetails,
                paymentHistory: [],
                installments: [],
            },
            interactions: [],
            documentation: { status: 'Pending' },
             officeUse: {
                commission: { type: 'Percentage', amount: 0, status: 'Pending' }
            }
        };

        return {
            ...baseClient,
            id: newId,
            name: fullName,
            surname: formData.surname,
            otherNames: formData.otherNames,
            initials: initials,
            regDate: formData.paymentDate,
            email: formData.email,
            phone: formData.telephone,
            dateOfBirth: formData.dateOfBirth,
            gender: formData.gender as Client['gender'],
            location: formData.location,
            plot: formData.plotNumber,
            photo: formData.photo,
            propertyType: formData.propertyType,
            plannedDevelopmentYear: formData.plannedDevelopmentYear,
            professionalDetails: {
                placeOfWork: formData.placeOfWork,
                profession: formData.profession,
                position: formData.position,
            },
            witness: {
                name: formData.witnessName,
                address: formData.witnessAddress,
                phone: formData.witnessPhone,
            },
            nextOfKin: {
                name: formData.kinName,
                phone: formData.kinPhone,
                relationship: formData.kinRelationship,
                email: formData.kinEmail,
                address: formData.kinAddress,
            },
            indenture: {
                name: formData.indentureName,
                address: formData.indentureAddress,
            },
            officeUse: {
                ...baseClient.officeUse,
                salesRep: formData.salesRep,
                salesManager: formData.salesManager,
                accountsHead: formData.accountsHead,
                clerk: formData.clerk,
            },
            isComplete: isComplete,
            filledFormPdf: formData.filledFormPdf,
        };
    };

    const handleSaveClient = async (formData: FormData) => {
        const newClient = createClientObject(formData);
        await onSaveClient(newClient);
        setClientFormOpen(false);
        addActivityLog('Create', `Created new client: ${newClient.name}.`);
         if (!newClient.isComplete) {
            alert('Client record saved with incomplete information. Please complete all required fields to validate record.');
        }
    };

    const handleUpdateClient = async (formData: FormData) => {
        if (!editingClient) return;
        const updatedClient = createClientObject(formData, editingClient);
        const savedClient = await onSaveClient(updatedClient);
        setEditingClient(null);
        alert('Client information updated successfully.');
        addActivityLog('Update', `Updated client details for ${savedClient.name}.`);
        setClientForInvoice(savedClient);
        setActivePage('Account Management');
    };

    const handleEditClient = (client: Client) => {
        setEditingClient(client);
        setClientFormOpen(true);
    };

    const handleSaveAndPay = async (formData: FormData) => {
        const newClient = createClientObject(formData);
        const savedClient = await onSaveClient(newClient);
        setClientForInvoice(savedClient);
        setActivePage('Account Management');
        setClientFormOpen(false);
        addActivityLog('Create', `Created new client with payment info: ${newClient.name}.`);
         if (!newClient.isComplete) {
            alert('Client record saved with incomplete information. Please complete all required fields to validate record.');
        }
    };

    const handleImportClients = (importedData: any[]) => {
      const highestId = clients.length > 0 ? Math.max(...clients.map(c => c.id)) : 0;

      const newClients: Client[] = importedData.map((data, index) => {
          const fullName = `${data.surname || ''} ${data.otherNames || ''}`.trim();
          const nameParts = fullName.split(' ');
          const initials = (nameParts[0]?.[0] || '' + (nameParts.length > 1 ? nameParts[nameParts.length - 1]?.[0] : '') || '').toUpperCase();
          const selectedProperty = properties.find(p => p.location.toLowerCase() === (data.location || '').toLowerCase());
          let propertyPrice = selectedProperty ? selectedProperty.price : 200000;
          const plotCount = (data.plotNumber || '').split(',').map(p => p.trim()).filter(Boolean).length || 1;
          let baseTotal = propertyPrice * plotCount;

          let promoDetails: string | undefined = undefined;
          if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
              baseTotal *= (1 - selectedProperty.discount.percentage / 100);
              promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
          }

          const requiredCsvFields = [ 'surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
          const isRecordComplete = requiredCsvFields.every(field => data[field] && data[field].trim() !== '');

          return {
              id: highestId + 1 + index,
              name: fullName,
              surname: data.surname || '',
              otherNames: data.otherNames || '',
              initials: initials,
              regDate: data.paymentDate || new Date().toISOString().split('T')[0],
              email: data.email || '',
              phone: data.telephone || '',
              dateOfBirth: data.dateOfBirth || '',
              gender: (data.gender as Client['gender']) || undefined,
              location: data.location || '',
              plot: data.plotNumber || '',
              photo: undefined,
              propertyType: (data.propertyType as Client['propertyType']) || undefined,
              plannedDevelopmentYear: data.plannedDevelopmentYear || undefined,
              professionalDetails: {
                  placeOfWork: data.placeOfWork || '',
                  profession: data.profession || '',
                  position: data.position || '',
              },
              status: 'Active Client',
              stage: milestones[0]?.acronym || 'N/A',
              payment: {
                  total: baseTotal,
                  paid: 0,
                  balance: baseTotal,
                  dueDate: 'N/A',
                  planType: 'N/A',
                  paymentHistory: [],
                  installments: [],
                  promoDetails: promoDetails,
              },
              interactions: [],
              witness: { name: data.witnessName || '', address: data.witnessAddress || '', phone: data.witnessPhone || '' },
              nextOfKin: { 
                  name: data.kinName || '', 
                  phone: data.kinPhone || '', 
                  relationship: data.kinRelationship || '',
                  email: data.kinEmail || '',
                  address: data.kinAddress || '',
                },
              indenture: { name: data.indentureName || '', address: data.indentureAddress || '' },
              officeUse: { 
                  salesRep: data.salesRep || 'Imported', 
                  salesManager: data.salesManager || 'N/A', 
                  accountsHead: data.accountsHead || 'N/A', 
                  clerk: data.clerk || 'N/A', 
                  commission: { type: 'Percentage', amount: 0, status: 'Pending' } 
                },
              documentation: { status: 'Pending' },
              isComplete: isRecordComplete, // Based on CSV fields only
              filledFormPdf: null, // PDF cannot be imported
          };
      });

      Promise.all(newClients.map(c => onSaveClient(c))).then(() => {
          addActivityLog('Import', `Imported ${newClients.length} new clients from a CSV file.`);
      });
    };

    const handleCloseForm = () => {
        setClientFormOpen(false);
        setEditingClient(null);
    }

    const requiredCsvHeaders = [ 'surname', 'otherNames', 'dateOfBirth', 'currentAddress', 'telephone', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinName', 'kinAddress', 'kinPhone', 'kinRelationship', 'kinEmail', 'witnessName', 'witnessAddress', 'witnessPhone', 'paymentDate', 'paymentMethod', 'location', 'plotNumber', 'propertyType', 'plannedDevelopmentYear', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
    const sampleHeaders = requiredCsvHeaders.join(',');
    const sampleData = `"Doe","John","1990-01-15","123 Main St, Accra","0241234567","john.doe@example.com","Male","Tech Corp","Engineer","Senior","Doe,Jane","123 Main St, Accra","0247654321","Spouse","jane.doe@example.com","Smith,Adam","456 Oak Ave, Accra","0559876543","2024-08-01","Bank Transfer","East Legon Hills","ELH-205","Residential","2025","John K. Doe","P.O. Box 123, Accra","Sales Rep A","Manager B","Accountant C","Clerk D"`;


    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Clients ({filteredClients.length})</h1>
                </div>
                 <div className="flex items-center gap-4">
                    <button 
                        onClick={() => setImportWizardOpen(true)}
                        className="bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 font-semibold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors flex items-center gap-2"
                    >
                        <UploadIcon className="w-5 h-5" />
                        Import
                    </button>
                    <button 
                        onClick={() => { setEditingClient(null); setClientFormOpen(true); }}
                        className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2"
                    >
                        <DocumentPlusIcon className="w-5 h-5" />
                        Add New Client
                    </button>
                 </div>
            </div>

            {/* Filter and Search Bar */}
            <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                    <div className="relative md:col-span-1">
                        <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 dark:text-gray-500" />
                        <input
                            type="text"
                            placeholder="Search clients..."
                            className="bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-lg pl-10 pr-4 py-2 w-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <div className="relative md:col-span-1">
                         <select className="appearance-none w-full bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-700 text-gray-900 dark:text-white py-2 px-4 pr-8 rounded-lg leading-tight focus:outline-none focus:bg-white dark:focus:bg-gray-800 focus:border-blue-500">
                            <option>All Status</option>
                            <option>Active Client</option>
                            <option>Refunded</option>
                            <option>Reallocated</option>
                        </select>
                        <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700 dark:text-gray-300">
                           <ChevronDownIcon className="w-4 h-4" />
                        </div>
                    </div>
                     <div className="relative md:col-span-1">
                         <select className="appearance-none w-full bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-700 text-gray-900 dark:text-white py-2 px-4 pr-8 rounded-lg leading-tight focus:outline-none focus:bg-white dark:focus:bg-gray-800 focus:border-blue-500">
                            <option>All Locations</option>
                            {properties.map(p => <option key={p.id}>{p.location}</option>)}
                        </select>
                        <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700 dark:text-gray-300">
                           <ChevronDownIcon className="w-4 h-4" />
                        </div>
                    </div>
                </div>
            </div>

            {/* Client List Header */}
             <div className="hidden md:grid grid-cols-12 gap-4 px-4 py-2 text-left text-sm font-semibold text-gray-500 dark:text-gray-400">
                <div className="col-span-4">Client</div>
                <div className="col-span-2">Contact</div>
                <div className="col-span-2">Location & Plot</div>
                <div className="col-span-1 text-center">Status</div>
                <div className="col-span-2">Payment Info</div>
                <div className="col-span-1">Actions</div>
            </div>

            {/* Client List */}
            <div className="space-y-4">
                {filteredClients.map(client => (
                    <ClientListItem key={client.id} client={client} onViewDetails={onClientSelect} onEdit={handleEditClient} onDelete={handleDeleteClient} milestones={milestones} />
                ))}
            </div>

            {deletedClientInfo && (
                <div className="fixed bottom-5 right-5 bg-gray-800 text-white p-4 rounded-lg shadow-lg flex items-center gap-4 z-50 animate-fade-in">
                    <span>Client "{deletedClientInfo.name}" deleted.</span>
                </div>
            )}

            <ClientForm
                isOpen={isClientFormOpen}
                onClose={handleCloseForm}
                onSave={editingClient ? handleUpdateClient : handleSaveClient}
                onSaveAndPay={handleSaveAndPay}
                properties={properties}
                editingClient={editingClient}
            />

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={handleImportClients}
                requiredHeaders={requiredCsvHeaders.filter(h => !['dateOfBirth', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinAddress', 'kinEmail', 'propertyType', 'plannedDevelopmentYear', 'paymentMethod'].includes(h))}
                sampleHeaders={sampleHeaders}
                sampleData={sampleData}
                wizardTitle="Import Clients from CSV"
            />
            <style>
                {`
                    @keyframes fade-in {
                        from { opacity: 0; transform: translateY(10px); }
                        to { opacity: 1; transform: translateY(0); }
                    }
                    .animate-fade-in {
                        animation: fade-in 0.3s ease-out forwards;
                    }
                `}
            </style>
        </div>
    );
};

export default ClientsPage;

import React, { useState, ChangeEvent, FormEvent, useEffect, useCallback, useMemo } from 'react';
import { Client, Property } from '../types';
import { XIcon } from './icons/XIcon';
import { UserGroupIcon, BuildingLibraryIcon, BriefcaseIcon, CheckCircleIcon } from './icons/DummyIcons';

export type FormData = {
    // Personal
    surname: string;
    otherNames: string;
    dateOfBirth: string;
    currentAddress: string;
    telephone: string;
    email: string;
    gender: string;
    photo: string; // base64 string
    // Professional
    placeOfWork: string;
    profession: string;
    position: string;
    // Next of Kin
    kinName: string;
    kinAddress: string;
    kinPhone: string;
    kinRelationship: string;
    kinEmail: string;
    // Witness
    witnessName: string;
    witnessAddress: string;
    witnessPhone: string;
    // Property
    paymentDate: string;
// FIX: Added 'Cheque' to the payment method types to align with the data model.
    paymentMethod: 'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other';
    location: string;
    propertyType: 'Residential' | 'Commercial';
    plotNumber: string;
    plannedDevelopmentYear: string;
    filledFormPdf: string | null; // base64 string
    // Indenture
    indentureName: string;
    indentureAddress: string;
    // Office Use
    salesRep: string;
    salesManager: string;
    accountsHead: string;
    clerk: string;
};

interface ClientFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (formData: FormData) => void;
  onSaveAndPay: (formData: FormData) => void;
  properties: Property[];
  editingClient?: Client | null;
}

const getFieldClass = (error?: string): string => {
    const baseClass = "mt-1 block w-full px-3 py-2 bg-white dark:bg-gray-900 border rounded-md shadow-sm placeholder-gray-400 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm text-gray-900 dark:text-white";
    return error ? `${baseClass} border-red-500 dark:border-red-600` : `${baseClass} border-gray-300 dark:border-gray-600`;
};

const SmartInputField: React.FC<{ id: keyof FormData; label: string; value: string | number; onChange: (e: ChangeEvent<HTMLInputElement>) => void; onBlur: (e: React.FocusEvent<HTMLInputElement>) => void; error?: string; type?: string; required?: boolean; list?: string; isTouched?: boolean; }> = ({ id, label, value, onChange, onBlur, error, type = 'text', required = false, list, isTouched }) => (
    <div className="sm:col-span-1 relative">
        <label htmlFor={id} className="block text-sm font-medium text-gray-700 dark:text-gray-300">{label}{required && <span className="text-red-500">*</span>}</label>
        <input type={type} name={id} id={id} value={value} onChange={onChange} onBlur={onBlur} required={required} list={list} className={getFieldClass(error)} title={error || ''} />
        {isTouched && !error && required && (
            <CheckCircleIcon className="absolute right-3 top-[37px] w-5 h-5 text-green-500 pointer-events-none" />
        )}
        {error && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{error}</p>}
    </div>
);

const SmartSelectField: React.FC<{ id: keyof FormData; label: string; value: string; onChange: (e: ChangeEvent<HTMLSelectElement>) => void; onBlur: (e: React.FocusEvent<HTMLSelectElement>) => void; children: React.ReactNode; error?: string; required?: boolean; isTouched?: boolean; }> = ({ id, label, value, onChange, onBlur, children, error, required = false, isTouched }) => (
     <div className="sm:col-span-1 relative">
        <label htmlFor={id} className="block text-sm font-medium text-gray-700 dark:text-gray-300">{label}{required && <span className="text-red-500">*</span>}</label>
        <select id={id} name={id} value={value} onChange={onChange} onBlur={onBlur} required={required} className={getFieldClass(error)} title={error || ''}>
            {children}
        </select>
        {isTouched && !error && required && (
            <CheckCircleIcon className="absolute right-8 top-[37px] w-5 h-5 text-green-500 pointer-events-none" />
        )}
        {error && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{error}</p>}
    </div>
);


const FormSection: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
    <div className="mt-6 pt-6 border-t border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-medium leading-6 text-gray-900 dark:text-white">{title}</h3>
        <div className="mt-4 grid grid-cols-1 gap-y-6 gap-x-4 sm:grid-cols-2">
            {children}
        </div>
    </div>
);

const initialFormData: FormData = {
    surname: '',
    otherNames: '',
    dateOfBirth: '',
    currentAddress: '',
    telephone: '',
    email: '',
    gender: 'Other',
    photo: '',
    placeOfWork: '',
    profession: '',
    position: '',
    kinName: '',
    kinAddress: '',
    kinPhone: '',
    kinRelationship: '',
    kinEmail: '',
    witnessName: '',
    witnessAddress: '',
    witnessPhone: '',
    paymentDate: new Date().toISOString().split('T')[0],
    paymentMethod: 'Bank Transfer',
    location: '',
    propertyType: 'Residential',
    plotNumber: '',
    plannedDevelopmentYear: new Date().getFullYear().toString(),
    filledFormPdf: null,
    indentureName: '',
    indentureAddress: '',
    salesRep: '',
    salesManager: '',
    accountsHead: '',
    clerk: '',
};

const ClientForm: React.FC<ClientFormProps> = ({ isOpen, onClose, onSave, onSaveAndPay, properties, editingClient }) => {
    const [step, setStep] = useState(1);
    const [formData, setFormData] = useState<FormData>(initialFormData);
    const [photoPreview, setPhotoPreview] = useState<string | null>(null);
    const [pdfFile, setPdfFile] = useState<File | null>(null);
    const [touched, setTouched] = useState<Partial<Record<keyof FormData, boolean>>>({});

     useEffect(() => {
        if (isOpen && editingClient) {
            setFormData({
                surname: editingClient.surname,
                otherNames: editingClient.otherNames,
                dateOfBirth: '', // Assuming not stored, can be added to type
                currentAddress: editingClient.location, // Best guess
                telephone: editingClient.phone,
                email: editingClient.email,
                gender: 'Other', // Assuming not stored
                photo: editingClient.photo || '',
                placeOfWork: '', // Assuming not stored
                profession: '', // Assuming not stored
                position: '', // Assuming not stored
                kinName: editingClient.nextOfKin.name,
                kinAddress: '', // Assuming not stored
                kinPhone: editingClient.nextOfKin.phone,
                kinRelationship: editingClient.nextOfKin.relationship,
                kinEmail: editingClient.nextOfKin.email || '',
                witnessName: editingClient.witness.name,
                witnessAddress: editingClient.witness.address,
                witnessPhone: editingClient.witness.phone,
                paymentDate: editingClient.regDate,
                paymentMethod: editingClient.payment.paymentHistory[0]?.method || 'Bank Transfer',
                location: editingClient.location,
                propertyType: 'Residential', // Assuming not stored
                plotNumber: editingClient.plot,
                plannedDevelopmentYear: new Date().getFullYear().toString(),
                filledFormPdf: editingClient.filledFormPdf,
                indentureName: editingClient.indenture.name,
                indentureAddress: editingClient.indenture.address,
                salesRep: editingClient.officeUse.salesRep,
                salesManager: editingClient.officeUse.salesManager,
                accountsHead: editingClient.officeUse.accountsHead,
                clerk: editingClient.officeUse.clerk,
            });
            setPhotoPreview(editingClient.photo || null);
            setTouched({});
        } else if (isOpen) {
            resetForm();
        }
    }, [isOpen, editingClient]);

    const validate = useCallback((): Partial<Record<keyof FormData, string>> => {
        const errors: Partial<Record<keyof FormData, string>> = {};
        const requiredFields: (keyof FormData)[] = ['surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk', 'paymentDate'];

        requiredFields.forEach(field => {
            if (!formData[field]) errors[field] = 'This field cannot be left blank.';
        });

        const textFields: (keyof FormData)[] = ['surname', 'otherNames', 'kinName', 'witnessName', 'salesRep', 'salesManager', 'accountsHead', 'clerk'];
        textFields.forEach(field => {
            const value = formData[field];
            if (value) {
                if (!/^[A-Za-z\s'-]+$/.test(value)) errors[field] = 'Only letters, spaces, hyphens, and apostrophes are allowed.';
                if (/(.)\1{3,}/.test(value)) errors[field] = 'Please provide a valid, readable entry.';
                if (value.length < 2) errors[field] = 'Entry must be at least 2 characters.';
            }
        });

        const addressFields: (keyof FormData)[] = ['currentAddress', 'witnessAddress', 'indentureAddress', 'location'];
        addressFields.forEach(field => {
            const value = formData[field];
            if(value && (!/[a-zA-Z]/.test(value) || !/\s/.test(value))){
                errors[field] = 'Address must contain letters and at least one space.';
            }
        });

        if (formData.email && !/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(formData.email)) {
            errors.email = 'Please enter a valid email address format.';
        }

        const phoneFields: (keyof FormData)[] = ['telephone', 'kinPhone', 'witnessPhone'];
        phoneFields.forEach(field => {
            if (formData[field] && !/^\d{9,10}$/.test(formData[field])) {
                errors[field] = 'Please enter a valid 9 or 10-digit phone number.';
            }
        });

        if (formData.plotNumber && !/^[A-Z]{2,}-\d+/.test(formData.plotNumber)) {
            errors.plotNumber = 'Plot number must follow a format like ELH-101.';
        }

        if (!formData.filledFormPdf && !editingClient?.filledFormPdf) errors.filledFormPdf = 'PDF form upload is required.';
        return errors;
    }, [formData, editingClient]);

    const errors = useMemo(() => validate(), [validate]);
    const isFormValid = Object.keys(errors).length === 0;

    const handleBlur = (e: React.FocusEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name } = e.target as { name: keyof FormData };
        setTouched(prev => ({ ...prev, [name]: true }));
    };

    const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handlePhotoChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const allowedTypes = ['image/jpeg', 'image/png', 'image/jpg'];
            if (allowedTypes.includes(file.type)) {
                const reader = new FileReader();
                reader.onloadend = () => {
                    const base64String = reader.result as string;
                    setFormData(prev => ({ ...prev, photo: base64String }));
                    setPhotoPreview(base64String);
                };
                reader.readAsDataURL(file);
            } else {
                 alert('Invalid file type. Please upload a .jpg, .jpeg, or .png file.');
                 e.target.value = '';
            }
        }
    };

    const handlePdfChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            if (file.type === 'application/pdf') {
                setPdfFile(file);
                const reader = new FileReader();
                reader.onloadend = () => {
                    const base64String = reader.result as string;
                    setFormData(prev => ({ ...prev, filledFormPdf: base64String }));
                };
                reader.readAsDataURL(file);
                 setTouched(prev => ({ ...prev, filledFormPdf: true }));
            } else {
                alert('Please upload a PDF file.');
                e.target.value = '';
            }
        }
    };

    const step1Fields: (keyof FormData)[] = ['surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress'];
    const step2Fields: (keyof FormData)[] = ['location', 'plotNumber', 'paymentDate', 'filledFormPdf', 'indentureName', 'indentureAddress'];

    const handleNext = () => {
        const currentStepFields = step === 1 ? step1Fields : step2Fields;
        let isStepValid = true;
        const fieldsToTouch: Partial<Record<keyof FormData, boolean>> = {};

        currentStepFields.forEach(field => {
            fieldsToTouch[field] = true;
            if (errors[field]) {
                isStepValid = false;
            }
        });

        if (!isStepValid) {
            setTouched(prev => ({ ...prev, ...fieldsToTouch }));
            alert('Please complete all required fields correctly before continuing.');
            return;
        }
        setStep(prev => Math.min(prev + 1, 3));
    };
    const handleBack = () => setStep(prev => Math.max(prev - 1, 1));

    const handleSubmit = (e: FormEvent) => {
        e.preventDefault();
        if (!isFormValid) {
            const allFields = Object.keys(initialFormData) as (keyof FormData)[];
            const allTouched = allFields.reduce((acc, key) => ({...acc, [key]: true}), {});
            setTouched(allTouched);
            alert("Some fields contain invalid or incomplete data. Please correct them before saving.");
            return;
        }
        onSave(formData);
        resetForm();
    };

    const handleSubmitAndPay = (e: FormEvent) => {
        e.preventDefault();
         if (!isFormValid) {
            const allFields = Object.keys(initialFormData) as (keyof FormData)[];
            const allTouched = allFields.reduce((acc, key) => ({...acc, [key]: true}), {});
            setTouched(allTouched);
            alert("Some fields contain invalid or incomplete data. Please correct them before saving.");
            return;
        }
        onSaveAndPay(formData);
        resetForm();
    };

    const resetForm = () => {
        setFormData(initialFormData);
        setPhotoPreview(null);
        setPdfFile(null);
        setStep(1);
        setTouched({});
    };

    if (!isOpen) return null;

    const steps = [
        { name: 'Client Information', icon: <UserGroupIcon className="w-5 h-5" /> },
        { name: 'Acquisition Details', icon: <BuildingLibraryIcon className="w-5 h-5" /> },
        { name: 'Office Details', icon: <BriefcaseIcon className="w-5 h-5" /> },
    ];

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" aria-modal="true" role="dialog">
            <div className="bg-gray-50 dark:bg-gray-900 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white">{editingClient ? 'Edit Client Details' : 'New Client Registration'}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                        <XIcon className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 border-b border-gray-200 dark:border-gray-700">
