                        className="bg-green-500 h-4 rounded-full" 
                        style={{ width: `${paidPercentage}%` }}
                        role="progressbar"
                        aria-valuenow={paidPercentage}
                        aria-valuemin={0}
                        aria-valuemax={100}
                    ></div>
                </div>

                <div className="flex justify-between items-center">
                    <span className="text-gray-500 dark:text-gray-400">Paid</span>
