                      </div>
                       <div className="md:col-span-3">
                          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Upload Banner Image</label>
                          <div className="mt-1 flex items-center gap-4">
                             {bannerPreview && <img src={bannerPreview} alt="Banner" className="h-12 w-24 object-cover rounded-md" />}
                             <label htmlFor="banner-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm leading-4 font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600 flex items-center gap-2">
                                <UploadIcon className="w-5 h-5"/>
                                <span>{bannerPreview ? 'Change Image' : 'Upload Image'}</span>
                                <input id="banner-upload" name="bannerImage" type="file" className="sr-only" onChange={handleFileChange} accept="image/*" />
                             </label>
                          </div>
                      </div>
                      <div className="md:col-span-3 flex justify-end gap-3 mt-4">
                          <button type="button" onClick={handleReset} className="bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-semibold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors">Cancel</button>
                          <button type="submit" className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors">{editingId ? 'Update Promotion' : 'Save Promotion'}</button>
                      </div>
                  </form>
                  <style>{`
                    .input-class { 
                        padding: 0.5rem 0.75rem; 
                        background-color: white; 
                        border: 1px solid #D1D5DB; 
                        border-radius: 0.375rem; 
                        box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05); 
                    } 
                    .dark .input-class {
                        background-color: #0f172a;
                        border-color: #374151;
                        color: white;
                    }
                    .input-class:focus { 
                        outline: none; 
                        --tw-ring-color: #3B82F6; 
                        border-color: #3B82F6; 
                    }
                  `}</style>
              </div>
            )}

            {/* Promo List */}
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 overflow-x-auto transition-colors duration-200">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-50 dark:bg-gray-900 text-xs text-gray-700 dark:text-gray-300 uppercase">
                        <tr>
                            <th className="px-6 py-3">Title</th>
                            <th className="px-6 py-3">Type</th>
                            <th className="px-6 py-3">Duration</th>
                            <th className="px-6 py-3">Applicable To</th>
                            <th className="px-6 py-3 text-center">Status</th>
                            <th className="px-6 py-3 text-center">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                        {promotions.map(promo => (
                            <tr key={promo.id} className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700/50">
                                <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{promo.title}</td>
                                <td className="px-6 py-4 text-gray-600 dark:text-gray-300">{promo.promoType}</td>
                                <td className="px-6 py-4 text-gray-600 dark:text-gray-300">{promo.startDate} to {promo.endDate}</td>
                                <td className="px-6 py-4 text-gray-600 dark:text-gray-300">{promo.applicablePropertyId === 'all' ? 'All Properties' : properties.find(p=>p.id === promo.applicablePropertyId)?.location}</td>
                                <td className="px-6 py-4 text-center">
                                    <button onClick={() => handleStatusToggle(promo)} className={`px-2 py-1 text-xs font-semibold rounded-full ${promo.status === 'Active' ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300' : 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300'}`}>
                                        {promo.status}
                                    </button>
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <div className="flex items-center justify-center gap-2">
                                        <button onClick={() => handleEdit(promo)} className="text-gray-500 hover:text-blue-600 dark:text-gray-400 dark:hover:text-blue-400 p-1"><PencilIcon className="w-5 h-5"/></button>
                                        <button onClick={() => handleDelete(promo.id)} className="text-gray-500 hover:text-red-600 dark:text-gray-400 dark:hover:text-red-400 p-1"><TrashIcon className="w-5 h-5"/></button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {promotions.length === 0 && <div className="text-center py-10 text-gray-500 dark:text-gray-400">No promotions found.</div>}
            </div>
        </div>
    );
};

export default PromotionsPage;

