                                                    <tbody className="divide-y divide-gray-100 dark:divide-gray-600">
                                                        {selectedClient.payment.installments.map(inst => (<tr key={inst.id}><td className="px-6 py-3 font-medium text-gray-900 dark:text-gray-100">{inst.id}</td><td className="px-6 py-3 text-gray-600 dark:text-gray-300">{inst.dueDate}</td><td className="px-6 py-3 text-right text-gray-600 dark:text-gray-300">{formatCurrency(inst.amountDue)}</td><td className="px-6 py-3 text-right text-green-600 dark:text-green-400">{formatCurrency(inst.amountPaid)}</td><td className="px-6 py-3 text-right font-semibold text-gray-800 dark:text-white">{formatCurrency(inst.balance)}</td><td className="px-6 py-3 text-center">{getStatusBadge(inst.status)}</td></tr>))}
                                                    </tbody>
                                                </table>
                                            </div>
                                        </Card>
                                    )}
                                    <Card title="Transaction History" className="p-0">
                                        <div className="overflow-x-auto max-h-72">
                                            <table className="w-full text-sm text-left text-gray-500 dark:text-gray-400">
                                                <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700 sticky top-0"><tr><th className="px-6 py-3">Date</th><th className="px-6 py-3">Amount</th><th className="px-6 py-3">Method</th><th className="px-6 py-3">Receipt #</th><th className="px-6 py-3">Reference</th><th className="px-6 py-3 text-center">Status</th></tr></thead>
                                                <tbody className="divide-y divide-gray-100 dark:divide-gray-600">
                                                    {selectedClient.payment.paymentHistory.map(p => (<tr key={p.id}><td className="px-6 py-3 text-gray-600 dark:text-gray-300">{p.date}</td><td className="px-6 py-3 font-semibold text-gray-800 dark:text-white">{formatCurrency(p.amount)}</td><td className="px-6 py-3 text-gray-600 dark:text-gray-300">{p.method}</td><td className="px-6 py-3 font-mono text-indigo-600 dark:text-indigo-400">{p.receiptNumber}</td><td className="px-6 py-3 text-gray-500 dark:text-gray-400">{p.reference}</td><td className="px-6 py-3 text-center">{getStatusBadge(p.status)}</td></tr>))}
                                                    {selectedClient.payment.paymentHistory.length === 0 && (<tr><td colSpan={6} className="text-center p-6 text-gray-500 dark:text-gray-400">No payment history found.</td></tr>)}
                                                </tbody>
                                            </table>
                                        </div>
                                    </Card>
                                </div>
                            )}

                            {activeTab === 'commission' && (
                                <Card title="Sales & Commission Details">
                                    <dl>
                                        <InfoRow label="Sales Rep" value={selectedClient.officeUse.salesRep} />
                                        <InfoRow label="Commission Type" value={selectedClient.officeUse.commission.type} />
                                        <InfoRow label="Amount" value={formatCurrency(selectedClient.officeUse.commission.amount)} />
                                        <InfoRow label="Status" value={getStatusBadge(selectedClient.officeUse.commission.status)} />
                                        {selectedClient.officeUse.commission.paymentDate && <InfoRow label="Paid Date" value={selectedClient.officeUse.commission.paymentDate} />}
                                    </dl>
                                    <div className="mt-6">
                                        <Button disabled={selectedClient.officeUse.commission.status === 'Paid'} variant="success">
                                            Mark as Paid
                                        </Button>
                                    </div>
                                </Card>
                            )}
                        </div>
                        )}
                    </div>
                </div>

                {/* Footer */}
                <div className="flex justify-end items-center p-4 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-xl flex-shrink-0 gap-3">
                    <Button variant="secondary" onClick={onClose}>Cancel</Button>
                    <Button onClick={handleFormSubmit} disabled={!selectedClient}>Save Record</Button>
                </div>
            </Card>
             {selectedClient && <RecordPaymentModal isOpen={isPaymentModalOpen} onClose={() => setPaymentModalOpen(false)} onSave={handleSavePayment} client={selectedClient}/>}
        </div>
    );
};

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ invoices, clients, onSaveClient, onSaveInvoice, clientForInvoice, setClientForInvoice, receiptPattern, setReceiptPattern, setReceiptAlerts, currentStaff }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  useEffect(() => {
    if (clientForInvoice) {
        setEditingInvoice(null);
        setIsModalOpen(true);
    }
  }, [clientForInvoice]);

  const handleCreateInvoice = () => {
    setEditingInvoice(null);
    setClientForInvoice(null);
    setIsModalOpen(true);
  };

  const handleEditInvoice = (invoice: Invoice) => {
    setEditingInvoice(invoice);
    setClientForInvoice(null);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
      setIsModalOpen(false);
      setEditingInvoice(null);
      if (clientForInvoice) {
          setClientForInvoice(null);
      }
  };

  const handleSaveInvoice = async (invoiceToSave: Invoice, updatedClientData?: Client) => {
    if (updatedClientData) {
        const hasInvoice = invoices.some(inv => inv.clientId === updatedClientData!.id) || invoiceToSave.amount > 0;
        const dataIsComplete = updatedClientData && true; // check complete function
        updatedClientData.isComplete = dataIsComplete && hasInvoice;
        await onSaveClient(updatedClientData);
    }

    if (invoiceToSave.amount > 0 || editingInvoice) {
        await onSaveInvoice(invoiceToSave);
    }

    handleCloseModal();
  };

  const handleRecordPayment = async (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'>) => {
    // Payment logic remains same
    const newTransaction: PaymentTransaction = { ...paymentData, id: `TXN-${Date.now()}`, status: 'Success' };
    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: client.payment.paid + newTransaction.amount,
            balance: client.payment.balance - newTransaction.amount,
        }
    };
    await onSaveClient(updatedClient);
    alert(`Payment and receipt ${paymentData.receiptNumber} saved successfully.`);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Account Management</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">Track invoices, payments, and client account statuses.</p>
        </div>
        <Button onClick={handleCreateInvoice} icon={<DocumentPlusIcon className="w-5 h-5" />}>
            Create Financial Record
        </Button>
      </div>

      <Card className="flex flex-wrap gap-4 justify-between items-center p-4">
        <div className="relative flex-grow sm:flex-grow-0 sm:w-80">
          <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 dark:text-gray-500" />
          <input
              type="text"
              placeholder="Search by invoice ID or client name..."
              className="pl-10 block w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <Button variant="secondary" icon={<FunnelIcon className="w-5 h-5" />}>Filter</Button>
      </Card>

      <TableContainer>
        <table className="w-full text-sm text-left text-gray-500 dark:text-gray-400">
            <Thead>
                <tr>
                    <Th>Invoice ID</Th>
                    <Th>Client</Th>
                    <Th>Amount</Th>
                    <Th>Issue Date</Th>
                    <Th>Due Date</Th>
                    <Th className="text-center">Status</Th>
                    <Th className="text-center">Actions</Th>
                </tr>
            </Thead>
            <Tbody>
                {invoices.map(invoice => (
                    <Tr key={invoice.id}>
                        <Td className="font-medium text-indigo-600 dark:text-indigo-400 whitespace-nowrap">{invoice.id}</Td>
                        <Td className="font-medium text-gray-900 dark:text-white">{invoice.clientName}</Td>
                        <Td className="font-semibold text-gray-700 dark:text-gray-200">{formatCurrency(invoice.amount)}</Td>
                        <Td>{invoice.issueDate}</Td>
                        <Td>{invoice.dueDate}</Td>
                        <Td className="text-center">{getStatusBadge(invoice.status)}</Td>
                        <Td className="text-center">
                            <button onClick={() => handleEditInvoice(invoice)} className="text-gray-500 hover:text-indigo-600 dark:text-gray-400 dark:hover:text-indigo-400 p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700">
                                <PencilIcon className="w-5 h-5" />
                            </button>
                        </Td>
                    </Tr>
                ))}
            </Tbody>
        </table>
        {invoices.length === 0 && (
            <div className="text-center py-10">
                <p className="text-gray-500 dark:text-gray-400">No invoices found.</p>
            </div>
        )}
      </TableContainer>
      <InvoiceFormModal 
        isOpen={isModalOpen}
        onClose={handleCloseModal}
        clients={clients}
        onSave={handleSaveInvoice}
        onRecordPayment={handleRecordPayment}
        editingInvoice={editingInvoice}
        clientForInvoice={clientForInvoice}
      />
    </div>
  );
};

export default AccountManagementPage;

import React, { useState, ChangeEvent, FormEvent } from 'react';
import { Promotion, Property } from '../types';
import { ArrowLeftIcon, PencilIcon, TrashIcon, UploadIcon } from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Select } from '../components/ui/Input';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';

interface PromotionsPageProps {
    promotions: Promotion[];
    onSavePromotion: (promotion: Promotion) => Promise<void>;
    onDeletePromotion: (promotionId: number) => Promise<void>;
    properties: Property[];
    showForm?: boolean;
    onBack?: () => void;
}

const initialFormState: Omit<Promotion, 'id'> = {
    title: '',
    description: '',
    promoType: 'Discount',
    startDate: '',
    endDate: '',
    discountValue: 0,
    applicablePropertyId: 'all',
    status: 'Active',
    bannerImage: undefined,
};

const PromotionsPage: React.FC<PromotionsPageProps> = ({ promotions, onSavePromotion, onDeletePromotion, properties, showForm = false, onBack }) => {
    const [formData, setFormData] = useState<Omit<Promotion, 'id'>>(initialFormState);
    const [editingId, setEditingId] = useState<number | null>(null);
    const [bannerPreview, setBannerPreview] = useState<string | null>(null);

    const handleInputChange = (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        const isNumber = type === 'number';
        setFormData(prev => ({ ...prev, [name]: isNumber ? parseFloat(value) || 0 : value }));
    };

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64String = reader.result as string;
                setFormData(prev => ({ ...prev, bannerImage: base64String }));
                setBannerPreview(base64String);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleStatusToggle = (promo: Promotion) => {
        const updatedPromo: Promotion = { ...promo, status: promo.status === 'Active' ? 'Inactive' : 'Active' };
        onSavePromotion(updatedPromo);
    };

    const handleReset = () => {
        setFormData(initialFormState);
        setEditingId(null);
        setBannerPreview(null);
    };

    const handleSubmit = (e: FormEvent) => {
        e.preventDefault();
        const promoToSave: Promotion = {
            id: editingId !== null ? editingId : Date.now(),
            ...formData,
        };
        onSavePromotion(promoToSave);
        handleReset();
    };

    const handleEdit = (promo: Promotion) => {
        setEditingId(promo.id);
        setFormData({
            title: promo.title,
            description: promo.description,
            promoType: promo.promoType,
            startDate: promo.startDate,
            endDate: promo.endDate,
            discountValue: promo.discountValue,
            applicablePropertyId: promo.applicablePropertyId,
            status: promo.status,
            bannerImage: promo.bannerImage,
        });
        setBannerPreview(promo.bannerImage || null);
        window.scrollTo(0, 0);
    };

    const handleDelete = (id: number) => {
        onDeletePromotion(id);
    };

    return (
        <div className="space-y-6">
            <div>
                 {onBack && (
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" /> Back to CEO Hub
                    </button>
                )}
                <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Promotional Offers Management</h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">Create, manage, and track all marketing promotions.</p>
            </div>

            {/* Promo Creation Form - Conditionally Rendered */}
            {showForm && (
              <Card title={editingId ? 'Edit Promotion' : 'Create New Promotion'}>
                  <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                      <Input label="Promo Title*" name="title" value={formData.title} onChange={handleInputChange} required />
                      <div className="md:col-span-2">
                          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Promo Description*</label>
                          <textarea name="description" value={formData.description} onChange={handleInputChange} required rows={1} className="block w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 sm:text-sm" />
                      </div>
                      <Select label="Promo Type" name="promoType" value={formData.promoType} onChange={handleInputChange}>
                          <option>Discount</option><option>Free Plot</option><option>Referral Bonus</option><option>Seasonal Offer</option><option>Other</option>
                      </Select>
                      <Input label="Start Date" type="date" name="startDate" value={formData.startDate} onChange={handleInputChange} />
                      <Input label="End Date" type="date" name="endDate" value={formData.endDate} onChange={handleInputChange} />
                      <Input label="Discount % or Value" type="number" name="discountValue" value={formData.discountValue} onChange={handleInputChange} />
                      <Select label="Applicable Property" name="applicablePropertyId" value={formData.applicablePropertyId} onChange={handleInputChange}>
                          <option value="all">All Properties</option>
                          {properties.map(p => <option key={p.id} value={p.id}>{p.location}</option>)}
                      </Select>
                      <Select label="Promo Status" name="status" value={formData.status} onChange={handleInputChange}>
                          <option value="Active">Active</option><option value="Inactive">Inactive</option>
                      </Select>
                       <div className="md:col-span-3">
                          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Upload Banner Image</label>
                          <div className="mt-1 flex items-center gap-4">
                             {bannerPreview && <img src={bannerPreview} alt="Banner" className="h-12 w-24 object-cover rounded-md" />}
                             <label htmlFor="banner-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600 flex items-center gap-2">
                                <UploadIcon className="w-5 h-5"/>
                                <span>{bannerPreview ? 'Change Image' : 'Upload Image'}</span>
                                <input id="banner-upload" name="bannerImage" type="file" className="sr-only" onChange={handleFileChange} accept="image/*" />
                             </label>
                          </div>
                      </div>
                      <div className="md:col-span-3 flex justify-end gap-3 mt-4">
                          <Button type="button" variant="secondary" onClick={handleReset}>Cancel</Button>
                          <Button type="submit">{editingId ? 'Update Promotion' : 'Save Promotion'}</Button>
                      </div>
                  </form>
              </Card>
            )}

            {/* Promo List */}
            <TableContainer>
                <table className="w-full text-sm text-left">
                    <Thead>
                        <tr>
                            <Th>Title</Th>
                            <Th>Type</Th>
                            <Th>Duration</Th>
                            <Th>Applicable To</Th>
                            <Th className="text-center">Status</Th>
                            <Th className="text-center">Actions</Th>
                        </tr>
                    </Thead>
                    <Tbody>
                        {promotions.map(promo => (
                            <Tr key={promo.id}>
                                <Td className="font-medium text-gray-900 dark:text-white">{promo.title}</Td>
                                <Td className="text-gray-600 dark:text-gray-300">{promo.promoType}</Td>
                                <Td className="text-gray-600 dark:text-gray-300">{promo.startDate} to {promo.endDate}</Td>
                                <Td className="text-gray-600 dark:text-gray-300">{promo.applicablePropertyId === 'all' ? 'All Properties' : properties.find(p=>p.id === promo.applicablePropertyId)?.location}</Td>
                                <Td className="text-center">
                                    <button onClick={() => handleStatusToggle(promo)}>
                                        <Badge variant={promo.status === 'Active' ? 'success' : 'danger'}>{promo.status}</Badge>
                                    </button>
                                </Td>
                                <Td className="text-center">
                                    <div className="flex items-center justify-center gap-2">
                                        <button onClick={() => handleEdit(promo)} className="text-gray-500 hover:text-blue-600 dark:text-gray-400 dark:hover:text-blue-400 p-1"><PencilIcon className="w-5 h-5"/></button>
