    };

    const formatCurrency = (amount: number) => {
        if (amount >= 1_000_000) {
            return `GH₵${(amount / 1_000_000).toFixed(2)}M`;
        }
        if (amount >= 1_000) {
            return `GH₵${(amount / 1_000).toFixed(1)}K`;
        }
        return `GH₵${amount.toFixed(2)}`;
    };

    const stats = [
