import React, { useState, useEffect, ChangeEvent } from 'react';

interface PhoneInputProps {
    value: string;
    onChange: (value: string) => void;
    label?: string;
    required?: boolean;
    error?: string;
    id?: string;
    name?: string;
    disabled?: boolean;
    className?: string;
}

const COUNTRY_CODES = [
    { code: '+233', country: 'GH', flag: '🇬🇭' },
    { code: '+234', country: 'NG', flag: '🇳🇬' },
    { code: '+1', country: 'US', flag: '🇺🇸' },
    { code: '+44', country: 'UK', flag: '🇬🇧' },
    { code: '+228', country: 'TG', flag: '🇹🇬' }, // Togo
    { code: '+225', country: 'CI', flag: '🇨🇮' }, // Cote d'Ivoire
];

export const PhoneInput: React.FC<PhoneInputProps> = ({ value, onChange, label, required, error, id, name, disabled, className }) => {
    const [selectedCode, setSelectedCode] = useState('+233');
    const [phoneNumber, setPhoneNumber] = useState('');

    useEffect(() => {
        // Attempt to parse existing value
        if (value) {
            const foundCode = COUNTRY_CODES.find(c => value.startsWith(c.code));
            if (foundCode) {
                setSelectedCode(foundCode.code);
                setPhoneNumber(value.slice(foundCode.code.length));
            } else {
                // If no code matches, assumes it might be a local legacy number. 
                // Default to GH code logic: if starts with 0, strip it.
                if (value.startsWith('0')) {
                    setPhoneNumber(value.substring(1));
                } else {
                    setPhoneNumber(value);
                }
                setSelectedCode('+233'); // Default
            }
        } else {
            setPhoneNumber('');
            setSelectedCode('+233');
        }
    }, [value]);

    const handleCodeChange = (e: ChangeEvent<HTMLSelectElement>) => {
        const newCode = e.target.value;
        setSelectedCode(newCode);
        onChange(`${newCode}${phoneNumber}`);
    };

    const handleNumberChange = (e: ChangeEvent<HTMLInputElement>) => {
        const input = e.target.value.replace(/\D/g, ''); // Remove non-digits
        // Restrict to 9 digits
        const truncated = input.slice(0, 9);
        setPhoneNumber(truncated);
        onChange(`${selectedCode}${truncated}`);
    };

    return (
        <div className={`w-full ${className}`}>
            {label && <label htmlFor={id} className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">{label}{required && <span className="text-red-500">*</span>}</label>}
            <div className="flex relative rounded-md shadow-sm">
                <select
                    disabled={disabled}
                    value={selectedCode}
                    onChange={handleCodeChange}
                    className="inset-y-0 left-0 flex items-center pl-2 pr-8 py-2 border border-gray-300 dark:border-gray-700 bg-gray-50 dark:bg-gray-800 text-gray-500 dark:text-gray-200 sm:text-sm rounded-l-md focus:ring-blue-500 focus:border-blue-500 border-r-0"
                    style={{ minWidth: '80px' }}
                >
                    {COUNTRY_CODES.map((country) => (
                        <option key={country.code} value={country.code}>
                            {country.flag} {country.code}
                        </option>
                    ))}
                </select>
                <input
                    type="tel"
                    name={name}
                    id={id}
                    disabled={disabled}
                    className={`block w-full min-w-0 flex-1 rounded-none rounded-r-md border border-gray-300 dark:border-gray-700 px-3 py-2 bg-white dark:bg-gray-900 placeholder-gray-400 dark:placeholder-gray-500 text-gray-900 dark:text-white focus:ring-blue-500 focus:border-blue-500 sm:text-sm ${error ? 'border-red-500' : ''}`}
                    placeholder="xxxxxxxxx"
                    value={phoneNumber}
                    onChange={handleNumberChange}
                />
            </div>
            {error && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{error}</p>}
        </div>
    );
};

import React, { ChangeEvent, useState, useEffect } from 'react';

interface EmailInputProps {
    value: string;
    onChange: (value: string) => void;
    label?: string;
    required?: boolean;
    error?: string;
    id?: string;
    name?: string;
    disabled?: boolean;
    className?: string;
}

export const EmailInput: React.FC<EmailInputProps> = ({ value, onChange, label, required, error: propError, id, name, disabled, className }) => {
    const [localError, setLocalError] = useState('');

    const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        onChange(val);

        // Instant feedback validation (optional, can also rely on propError)
        if (val && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)) {
            setLocalError('Invalid format (e.g. example@example.com)');
        } else {
            setLocalError('');
        }
    };

    // Sync with prop error if provided, otherwise use local logic
    const displayError = propError || (value && localError ? localError : '');

    return (
        <div className={`w-full ${className}`}>
            {label && <label htmlFor={id} className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">{label}{required && <span className="text-red-500">*</span>}</label>}
            <input
                type="email"
                name={name}
                id={id}
                disabled={disabled}
                className={`block w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm placeholder-gray-400 dark:placeholder-gray-500 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 sm:text-sm ${displayError ? 'border-red-500' : ''}`}
                placeholder="example@example.com"
                value={value}
                onChange={handleChange}
            />
            {displayError && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{displayError}</p>}
        </div>
    );
};

import React, { useState, useCallback, ChangeEvent } from 'react';
import { XIcon } from './icons/XIcon';
import { UploadIcon, DocumentTextIcon, ExclamationTriangleIcon, CheckCircleIcon, ChevronLeftIcon, ChevronRightIcon } from './icons/DummyIcons';

interface CSVImportWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (data: any[]) => void;
  requiredHeaders: string[];
  sampleHeaders: string;
  sampleData: string;
  wizardTitle: string;
}

const CSVImportWizard: React.FC<CSVImportWizardProps> = ({ isOpen, onClose, onImport, requiredHeaders, sampleHeaders, sampleData, wizardTitle }) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [parsedData, setParsedData] = useState<any[]>([]);
    const [validationResults, setValidationResults] = useState<{ data: any; errors: string[] }[]>([]);
    const [errors, setErrors] = useState<string[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    const resetWizard = useCallback(() => {
        setStep(1);
        setFile(null);
        setParsedData([]);
        setValidationResults([]);
        setErrors([]);
        setIsLoading(false);
    }, []);

    const handleClose = useCallback(() => {
        resetWizard();
        onClose();
    }, [resetWizard, onClose]);

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const selectedFile = e.target.files[0];
            if (selectedFile.type === 'text/csv' || selectedFile.name.endsWith('.csv')) {
                 setFile(selectedFile);
                 setErrors([]);
            } else {
                setErrors(['Invalid file type. Please upload a .csv file.']);
                setFile(null);
            }
        }
    };

    const processFile = useCallback(() => {
        if (!file) return;

        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
                if (lines.length < 2) {
                    setErrors(['CSV file must have a header row and at least one data row.']);
                    setIsLoading(false);
                    return;
                }
                const header = lines[0].split(',').map(h => h.trim());
                const missingHeaders = requiredHeaders.filter(rh => !header.includes(rh));
                const localErrors: string[] = [];

                if (missingHeaders.length > 0) {
                    localErrors.push(`Warning: Missing required columns in CSV: ${missingHeaders.join(', ')}. These fields will be blank for all rows.`);
                }

                const validatedData = [];
                for (let i = 1; i < lines.length; i++) {
                    const values = lines[i].split(',');
                    const rowErrors: string[] = [];

                    const rowData: { [key: string]: string } = {};
                    header.forEach((h, index) => {
                        rowData[h] = values[index]?.trim() || '';
                    });

                    // Row-level validation
                    requiredHeaders.forEach(rh => {
                        if (!rowData[rh] || rowData[rh].trim() === '') {
                            rowErrors.push(`Missing required field: '${rh}'.`);
                        }
                    });

                    if (rowData.email && !/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(rowData.email)) {
                        rowErrors.push(`Invalid email format for '${rowData.email}'.`);
                    }

                    if (rowData.telephone && !/^\d{9,10}$/.test(rowData.telephone)) {
                        rowErrors.push(`Invalid phone number format for '${rowData.telephone}'. Must be 9-10 digits.`);
                    }

                    validatedData.push({ data: rowData, errors: rowErrors });
                }

                const validData = validatedData.filter(v => v.errors.length === 0).map(v => v.data);
                const invalidRowCount = validatedData.length - validData.length;

                if (invalidRowCount > 0) {
                    localErrors.push(`Found issues in ${invalidRowCount} row(s). These rows will be skipped.`);
                }

                setValidationResults(validatedData);
                setParsedData(validData);
                setErrors(localErrors);
                setStep(3);

            } catch (error) {
                 setErrors(['An unexpected error occurred while parsing the file.']);
            } finally {
                setIsLoading(false);
            }
        };
        reader.onerror = () => {
             setErrors(['Failed to read the file.']);
             setIsLoading(false);
        }
        reader.readAsText(file);
    }, [file, requiredHeaders]);

    const handleNext = () => {
        if (step === 2 && file) {
            processFile();
        } else {
            setStep(s => s + 1);
        }
    };

    const handleBack = () => setStep(s => s - 1);

    const handleConfirmImport = () => {
        setIsLoading(true);
        onImport(parsedData);
        setStep(4);
        setIsLoading(false);
    };

    const downloadSampleCSV = () => {
        const csvContent = `${sampleHeaders}\n${sampleData}`;
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement("a");
        if (link.download !== undefined) {
            const url = URL.createObjectURL(blob);
            link.setAttribute("href", url);
            link.setAttribute("download", "faim_import_sample.csv");
            link.style.visibility = 'hidden';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm" aria-modal="true" role="dialog">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white">{wizardTitle}</h2>
                    <button onClick={handleClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                        <XIcon className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 overflow-y-auto flex-grow bg-gray-50 dark:bg-gray-900">
                   {step === 1 && (
                        <div>
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">Step 1: Download Sample & Prepare Your File</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                To import data, you need a CSV file with specific columns. Download our sample file to see the required format.
                            </p>
                            <div className="mt-6 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
                                <h4 className="font-semibold text-blue-800 dark:text-blue-300">File Columns:</h4>
                                <div className="text-sm text-blue-700 dark:text-blue-200 mt-2 space-y-1 overflow-x-auto">
                                    <code className="font-mono whitespace-nowrap">{sampleHeaders.split(',').join(', ')}</code>
                                </div>
                                <p className="text-xs text-blue-600 dark:text-blue-400 mt-2">* Fields marked as required in the client form must not be empty.</p>
                            </div>
                            <div className="mt-6">
                                <button onClick={downloadSampleCSV} className="bg-green-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-green-700 flex items-center gap-2">
                                    <DocumentTextIcon className="w-5 h-5" />
                                    Download Sample CSV
                                </button>
                            </div>
                        </div>
                   )}
                   {step === 2 && (
                       <div>
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">Step 2: Upload Your CSV File</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                Drag and drop your file below or click to select the file from your computer.
                            </p>
                            <div className="mt-6 flex justify-center px-6 pt-10 pb-10 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-md">
                                <div className="space-y-1 text-center">
                                    <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                                    <div className="flex text-sm text-gray-600 dark:text-gray-400">
                                        <label htmlFor="file-upload" className="relative cursor-pointer bg-white dark:bg-gray-800 rounded-md font-medium text-blue-600 dark:text-blue-400 hover:text-blue-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500">
                                            <span>Upload a file</span>
                                            <input id="file-upload" name="file-upload" type="file" className="sr-only" onChange={handleFileChange} accept=".csv,text/csv" />
                                        </label>
                                        <p className="pl-1">or drag and drop</p>
                                    </div>
                                    <p className="text-xs text-gray-500 dark:text-gray-400">CSV file up to 5MB</p>
                                </div>
                            </div>
                            {file && (
                                <div className="mt-4 p-3 bg-gray-100 dark:bg-gray-700 rounded-md border border-gray-200 dark:border-gray-600 text-sm font-medium text-gray-700 dark:text-gray-200">
                                    Selected file: {file.name}
                                </div>
                            )}
                            {errors.length > 0 && <div className="mt-4 text-sm text-red-600 dark:text-red-400">{errors[0]}</div>}
                        </div>
                   )}
                   {step === 3 && (
                        <div>
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">Step 3: Preview and Confirm Import</h3>
                             <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                Review the data below. We'll import <span className="font-bold text-green-600 dark:text-green-400">{parsedData.length}</span> valid records.
                                <span className="font-bold text-red-600 dark:text-red-400"> {validationResults.length - parsedData.length}</span> records with errors will be skipped.
                            </p>
                            {errors.length > 0 && (
                                <div className="mt-4 p-4 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg">
                                    <h4 className="font-semibold text-yellow-800 dark:text-yellow-300 flex items-center gap-2"><ExclamationTriangleIcon className="w-5 h-5" /> Import Warnings</h4>
                                    <ul className="list-disc list-inside text-sm text-yellow-700 dark:text-yellow-200 mt-2 max-h-24 overflow-y-auto">
                                        {errors.map((err, i) => <li key={i}>{err}</li>)}
                                    </ul>
                                </div>
                            )}
                            <div className="mt-4 border border-gray-200 dark:border-gray-700 rounded-lg overflow-x-auto max-h-80">
                                <table className="w-full text-sm text-left">
                                    <thead className="bg-gray-100 dark:bg-gray-700 sticky top-0 z-10">
                                        <tr>
                                            <th className="px-4 py-2 font-semibold text-gray-600 dark:text-gray-300">Status</th>
                                            {Object.keys(validationResults[0]?.data || {}).map(key => <th key={key} className="px-4 py-2 font-semibold text-gray-600 dark:text-gray-300 whitespace-nowrap">{key}</th>)}
                                        </tr>
                                    </thead>
                                    <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                                        {validationResults.slice(0, 10).map((result, index) => (
                                            <tr key={index} className={result.errors.length > 0 ? 'bg-red-50 dark:bg-red-900/20' : 'bg-green-50 dark:bg-green-900/20'}>
                                                <td className="px-4 py-2">
                                                    {result.errors.length > 0 ? (
                                                        <div className="flex items-center gap-1 text-red-600 dark:text-red-400" title={result.errors.join('\n')}>
                                                            <ExclamationTriangleIcon className="w-4 h-4" />
                                                            <span className="text-xs font-semibold">Error</span>
                                                        </div>
                                                    ) : (
                                                        <div className="flex items-center gap-1 text-green-600 dark:text-green-400">
                                                            <CheckCircleIcon className="w-4 h-4" />
                                                            <span className="text-xs font-semibold">OK</span>
                                                        </div>
                                                    )}
                                                </td>
                                                {Object.values(result.data).map((val: any, i) => <td key={i} className="px-4 py-2 whitespace-nowrap text-gray-700 dark:text-gray-300">{val}</td>)}
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                            {validationResults.length > 10 && <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 text-center">... and {validationResults.length - 10} more rows.</p>}
                        </div>
                   )}
                   {step === 4 && (
                       <div className="text-center py-10">
                            <CheckCircleIcon className="mx-auto h-16 w-16 text-green-500" />
                            <h3 className="mt-4 text-xl font-semibold text-gray-900 dark:text-white">Import Successful!</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-400">
                                We have successfully added <span className="font-bold">{parsedData.length}</span> records. You can now close this window.
                            </p>
                        </div>
                   )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <div>
                        {step > 1 && step < 4 && (
                            <button onClick={handleBack} className="bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-semibold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-600 flex items-center gap-2">
                                <ChevronLeftIcon className="w-5 h-5" /> Back
                            </button>
                        )}
                    </div>
                    <div>
                        {step < 3 && (
                            <button onClick={handleNext} disabled={(step === 2 && !file) || isLoading} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 disabled:bg-blue-300 flex items-center gap-2">
                                {isLoading ? 'Processing...' : `Next`} <ChevronRightIcon className="w-5 h-5" />
                            </button>
                        )}
                        {step === 3 && (
                            <button onClick={handleConfirmImport} disabled={parsedData.length === 0 || isLoading} className="bg-green-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-green-700 disabled:bg-green-300">
                                {isLoading ? 'Importing...' : `Confirm & Import ${parsedData.length} Records`}
                            </button>
                        )}
                        {step === 4 && (
                             <button onClick={handleClose} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700">
                                Finish
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CSVImportWizard;

import React, { useState, ChangeEvent, FormEvent, useEffect, useCallback, useMemo } from 'react';
import { Client, Property } from '../types';
import { XIcon } from './icons/XIcon';
import { UserGroupIcon, BuildingLibraryIcon, BriefcaseIcon, CheckCircleIcon } from './icons/DummyIcons';
import { PhoneInput } from './ui/PhoneInput';
import { EmailInput } from './ui/EmailInput';

export type FormData = {
    // Personal
    surname: string;
    otherNames: string;
    dateOfBirth: string;
    currentAddress: string;
    telephone: string;
    email: string;
    gender: string;
    photo: string; // base64 string
    // Professional
    placeOfWork: string;
    profession: string;
    position: string;
    // Next of Kin
    kinName: string;
    kinAddress: string;
    kinPhone: string;
    kinRelationship: string;
    kinEmail: string;
    // Witness
    witnessName: string;
    witnessAddress: string;
    witnessPhone: string;
    // Property
    paymentDate: string;
// FIX: Added 'Cheque' to the payment method types to align with the data model.
    paymentMethod: 'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other';
    location: string;
    propertyType: 'Residential' | 'Commercial';
    plotNumber: string;
    plannedDevelopmentYear: string;
    filledFormPdf: string | null; // base64 string
    // Indenture
    indentureName: string;
    indentureAddress: string;
    // Office Use
    salesRep: string;
    salesManager: string;
    accountsHead: string;
    clerk: string;
};

interface ClientFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (formData: FormData) => void;
  onSaveAndPay: (formData: FormData) => void;
  properties: Property[];
  editingClient?: Client | null;
}

const getFieldClass = (error?: string): string => {
    const baseClass = "mt-1 block w-full px-3 py-2 bg-white dark:bg-gray-900 border rounded-md shadow-sm placeholder-gray-400 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm text-gray-900 dark:text-white";
    return error ? `${baseClass} border-red-500 dark:border-red-600` : `${baseClass} border-gray-300 dark:border-gray-600`;
};

const SmartInputField: React.FC<{ id: keyof FormData; label: string; value: string | number; onChange: (e: ChangeEvent<HTMLInputElement>) => void; onBlur?: (e: React.FocusEvent<HTMLInputElement>) => void; error?: string; type?: string; required?: boolean; list?: string; isTouched?: boolean; }> = ({ id, label, value, onChange, onBlur, error, type = 'text', required = false, list, isTouched }) => (
    <div className="sm:col-span-1 relative">
        <label htmlFor={id} className="block text-sm font-medium text-gray-700 dark:text-gray-300">{label}{required && <span className="text-red-500">*</span>}</label>
        <input type={type} name={id} id={id} value={value} onChange={onChange} onBlur={onBlur} required={required} list={list} className={getFieldClass(error)} title={error || ''} />
        {isTouched && !error && required && (
            <CheckCircleIcon className="absolute right-3 top-[37px] w-5 h-5 text-green-500 pointer-events-none" />
        )}
        {error && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{error}</p>}
    </div>
);

const SmartSelectField: React.FC<{ id: keyof FormData; label: string; value: string; onChange: (e: ChangeEvent<HTMLSelectElement>) => void; onBlur?: (e: React.FocusEvent<HTMLSelectElement>) => void; children: React.ReactNode; error?: string; required?: boolean; isTouched?: boolean; }> = ({ id, label, value, onChange, onBlur, children, error, required = false, isTouched }) => (
     <div className="sm:col-span-1 relative">
        <label htmlFor={id} className="block text-sm font-medium text-gray-700 dark:text-gray-300">{label}{required && <span className="text-red-500">*</span>}</label>
        <select id={id} name={id} value={value} onChange={onChange} onBlur={onBlur} required={required} className={getFieldClass(error)} title={error || ''}>
            {children}
        </select>
        {isTouched && !error && required && (
            <CheckCircleIcon className="absolute right-8 top-[37px] w-5 h-5 text-green-500 pointer-events-none" />
        )}
        {error && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{error}</p>}
    </div>
);


const FormSection: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
    <div className="mt-6 pt-6 border-t border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-medium leading-6 text-gray-900 dark:text-white">{title}</h3>
        <div className="mt-4 grid grid-cols-1 gap-y-6 gap-x-4 sm:grid-cols-2">
            {children}
        </div>
    </div>
);

const initialFormData: FormData = {
    surname: '',
    otherNames: '',
    dateOfBirth: '',
    currentAddress: '',
    telephone: '',
    email: '',
    gender: 'Other',
    photo: '',
    placeOfWork: '',
    profession: '',
    position: '',
    kinName: '',
    kinAddress: '',
    kinPhone: '',
    kinRelationship: '',
    kinEmail: '',
    witnessName: '',
    witnessAddress: '',
    witnessPhone: '',
    paymentDate: new Date().toISOString().split('T')[0],
    paymentMethod: 'Bank Transfer',
    location: '',
    propertyType: 'Residential',
    plotNumber: '',
    plannedDevelopmentYear: new Date().getFullYear().toString(),
    filledFormPdf: null,
    indentureName: '',
    indentureAddress: '',
    salesRep: '',
    salesManager: '',
    accountsHead: '',
    clerk: '',
};

const ClientForm: React.FC<ClientFormProps> = ({ isOpen, onClose, onSave, onSaveAndPay, properties, editingClient }) => {
    const [step, setStep] = useState(1);
    const [formData, setFormData] = useState<FormData>(initialFormData);
    const [photoPreview, setPhotoPreview] = useState<string | null>(null);
    const [pdfFile, setPdfFile] = useState<File | null>(null);
    const [touched, setTouched] = useState<Partial<Record<keyof FormData, boolean>>>({});

     useEffect(() => {
        if (isOpen && editingClient) {
            setFormData({
                surname: editingClient.surname,
                otherNames: editingClient.otherNames,
                dateOfBirth: '', // Assuming not stored, can be added to type
                currentAddress: editingClient.location, // Best guess
                telephone: editingClient.phone,
                email: editingClient.email,
                gender: 'Other', // Assuming not stored
                photo: editingClient.photo || '',
                placeOfWork: '', // Assuming not stored
                profession: '', // Assuming not stored
                position: '', // Assuming not stored
                kinName: editingClient.nextOfKin.name,
                kinAddress: '', // Assuming not stored
                kinPhone: editingClient.nextOfKin.phone,
                kinRelationship: editingClient.nextOfKin.relationship,
                kinEmail: editingClient.nextOfKin.email || '',
                witnessName: editingClient.witness.name,
                witnessAddress: editingClient.witness.address,
                witnessPhone: editingClient.witness.phone,
                paymentDate: editingClient.regDate,
                paymentMethod: editingClient.payment.paymentHistory[0]?.method || 'Bank Transfer',
                location: editingClient.location,
                propertyType: 'Residential', // Assuming not stored
                plotNumber: editingClient.plot,
                plannedDevelopmentYear: new Date().getFullYear().toString(),
                filledFormPdf: editingClient.filledFormPdf,
                indentureName: editingClient.indenture.name,
                indentureAddress: editingClient.indenture.address,
                salesRep: editingClient.officeUse.salesRep,
                salesManager: editingClient.officeUse.salesManager,
                accountsHead: editingClient.officeUse.accountsHead,
                clerk: editingClient.officeUse.clerk,
            });
            setPhotoPreview(editingClient.photo || null);
            setTouched({});
        } else if (isOpen) {
            resetForm();
        }
    }, [isOpen, editingClient]);

    const validate = useCallback((): Partial<Record<keyof FormData, string>> => {
        const errors: Partial<Record<keyof FormData, string>> = {};
        const requiredFields: (keyof FormData)[] = ['surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk', 'paymentDate'];

        requiredFields.forEach(field => {
            if (!formData[field]) errors[field] = 'This field cannot be left blank.';
        });

        const textFields: (keyof FormData)[] = ['surname', 'otherNames', 'kinName', 'witnessName', 'salesRep', 'salesManager', 'accountsHead', 'clerk'];
        textFields.forEach(field => {
            const value = formData[field];
            if (value) {
                if (!/^[A-Za-z\s'-]+$/.test(value)) errors[field] = 'Only letters, spaces, hyphens, and apostrophes are allowed.';
                if (/(.)\1{3,}/.test(value)) errors[field] = 'Please provide a valid, readable entry.';
                if (value.length < 2) errors[field] = 'Entry must be at least 2 characters.';
            }
        });

        const addressFields: (keyof FormData)[] = ['currentAddress', 'witnessAddress', 'indentureAddress', 'location'];
        addressFields.forEach(field => {
            const value = formData[field];
            if(value && (!/[a-zA-Z]/.test(value) || !/\s/.test(value))){
                errors[field] = 'Address must contain letters and at least one space.';
            }
        });

        if (formData.email && !/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(formData.email)) {
            errors.email = 'Please enter a valid email address format.';
        }

        // Updated Phone validation logic if managed here, but mostly handled by input component now.
        // We ensure it has enough length (country code + 9 digits >= 12 chars usually)
        const phoneFields: (keyof FormData)[] = ['telephone', 'kinPhone', 'witnessPhone'];
        phoneFields.forEach(field => {
            if (formData[field] && formData[field].length < 10) {
                errors[field] = 'Please provide a valid phone number with country code.';
            }
        });

        if (formData.plotNumber && !/^[A-Z]{2,}-\d+/.test(formData.plotNumber)) {
            errors.plotNumber = 'Plot number must follow a format like ELH-101.';
        }

        return errors;
    }, [formData]);

    const errors = useMemo(() => validate(), [validate]);
    const isFormValid = Object.keys(errors).length === 0;

    const handleBlur = (e: React.FocusEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name } = e.target as { name: keyof FormData };
        setTouched(prev => ({ ...prev, [name]: true }));
    };

    const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    // Handler for Reusable Phone Input
    const handlePhoneChange = (fieldName: keyof FormData) => (value: string) => {
        setFormData(prev => ({ ...prev, [fieldName]: value }));
    };

    const handlePhotoChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const allowedTypes = ['image/jpeg', 'image/png', 'image/jpg'];
            if (allowedTypes.includes(file.type)) {
                const reader = new FileReader();
                reader.onloadend = () => {
                    const base64String = reader.result as string;
                    setFormData(prev => ({ ...prev, photo: base64String }));
                    setPhotoPreview(base64String);
                };
                reader.readAsDataURL(file);
            } else {
                 alert('Invalid file type. Please upload a .jpg, .jpeg, or .png file.');
                 e.target.value = '';
            }
        }
    };

    const handlePdfChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            if (file.type === 'application/pdf') {
                setPdfFile(file);
                const reader = new FileReader();
                reader.onloadend = () => {
                    const base64String = reader.result as string;
                    setFormData(prev => ({ ...prev, filledFormPdf: base64String }));
                };
                reader.readAsDataURL(file);
                 setTouched(prev => ({ ...prev, filledFormPdf: true }));
            } else {
                alert('Please upload a PDF file.');
                e.target.value = '';
            }
        }
    };

    const step1Fields: (keyof FormData)[] = ['surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress'];
    const step2Fields: (keyof FormData)[] = ['location', 'plotNumber', 'paymentDate', 'indentureName', 'indentureAddress'];

    const handleNext = () => {
        const currentStepFields = step === 1 ? step1Fields : step2Fields;
        let isStepValid = true;
        const fieldsToTouch: Partial<Record<keyof FormData, boolean>> = {};

        currentStepFields.forEach(field => {
            fieldsToTouch[field] = true;
            if (errors[field]) {
                isStepValid = false;
            }
        });

        if (!isStepValid) {
            setTouched(prev => ({ ...prev, ...fieldsToTouch }));
            alert('Please complete all required fields correctly before continuing.');
            return;
        }
        setStep(prev => Math.min(prev + 1, 3));
    };
    const handleBack = () => setStep(prev => Math.max(prev - 1, 1));

    const handleSubmit = (e: FormEvent) => {
        e.preventDefault();
        if (!isFormValid) {
            const allFields = Object.keys(initialFormData) as (keyof FormData)[];
            const allTouched = allFields.reduce((acc, key) => ({...acc, [key]: true}), {});
            setTouched(allTouched);
            alert("Some fields contain invalid or incomplete data. Please correct them before saving.");
            return;
        }
        onSave(formData);
        resetForm();
    };

    const handleSubmitAndPay = (e: FormEvent) => {
        e.preventDefault();
         if (!isFormValid) {
            const allFields = Object.keys(initialFormData) as (keyof FormData)[];
            const allTouched = allFields.reduce((acc, key) => ({...acc, [key]: true}), {});
            setTouched(allTouched);
            alert("Some fields contain invalid or incomplete data. Please correct them before saving.");
            return;
        }
        onSaveAndPay(formData);
        resetForm();
    };

    const resetForm = () => {
        setFormData(initialFormData);
        setPhotoPreview(null);
        setPdfFile(null);
        setStep(1);
        setTouched({});
    };

    if (!isOpen) return null;

    const steps = [
        { name: 'Client Information', icon: <UserGroupIcon className="w-5 h-5" /> },
        { name: 'Acquisition Details', icon: <BuildingLibraryIcon className="w-5 h-5" /> },
        { name: 'Office Details', icon: <BriefcaseIcon className="w-5 h-5" /> },
    ];

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" aria-modal="true" role="dialog">
            <div className="bg-gray-50 dark:bg-gray-900 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white">{editingClient ? 'Edit Client Details' : 'New Client Registration'}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                        <XIcon className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 border-b border-gray-200 dark:border-gray-700">
                    <nav aria-label="Progress">
                         <ol role="list" className="flex items-center">
                            {steps.map((s, stepIdx) => (
                                <li key={s.name} className={`relative ${stepIdx !== steps.length - 1 ? 'pr-8 sm:pr-20' : ''}`}>
                                    {step > stepIdx + 1 ? (
                                        <>
                                        <div className="absolute inset-0 flex items-center" aria-hidden="true">
                                            <div className="h-0.5 w-full bg-blue-600" />
                                        </div>
                                        <div className="relative w-8 h-8 flex items-center justify-center bg-blue-600 rounded-full text-white">
                                            {s.icon}
                                        </div>
                                        </>
                                    ) : step === stepIdx + 1 ? (
                                        <>
                                        <div className="absolute inset-0 flex items-center" aria-hidden="true">
                                            <div className="h-0.5 w-full bg-gray-200 dark:bg-gray-700" />
                                        </div>
                                        <div className="relative w-8 h-8 flex items-center justify-center bg-white dark:bg-gray-800 border-2 border-blue-600 rounded-full text-blue-600">
                                           {s.icon}
                                        </div>
                                        </>
                                    ) : (
                                        <>
                                        <div className="absolute inset-0 flex items-center" aria-hidden="true">
                                            <div className="h-0.5 w-full bg-gray-200 dark:bg-gray-700" />
                                        </div>
                                        <div className="relative w-8 h-8 flex items-center justify-center bg-white dark:bg-gray-800 border-2 border-gray-300 dark:border-gray-600 rounded-full text-gray-400">
                                            {s.icon}
                                        </div>
                                        </>
                                    )}
                                     <span className="absolute -bottom-6 text-xs font-semibold text-center w-24 -left-8 text-gray-600 dark:text-gray-400">{s.name}</span>
                                </li>
                            ))}
                        </ol>
                    </nav>
                </div>

                <form onSubmit={handleSubmit} className="p-6 overflow-y-auto flex-grow">
                    {step === 1 && (
                        <div>
                           <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                                <div className="sm:col-span-2">
                                    <h3 className="text-lg font-medium leading-6 text-gray-900 dark:text-white">Personal Information</h3>
                                    <div className="mt-4 grid grid-cols-1 gap-y-6 gap-x-4 sm:grid-cols-2">
                                        <SmartInputField id="surname" label="Surname" value={formData.surname} onChange={handleChange} onBlur={handleBlur} required error={touched.surname ? errors.surname : undefined} isTouched={touched.surname} />
                                        <SmartInputField id="otherNames" label="Other Names" value={formData.otherNames} onChange={handleChange} onBlur={handleBlur} required error={touched.otherNames ? errors.otherNames : undefined} isTouched={touched.otherNames}/>
                                        <SmartInputField id="dateOfBirth" label="Date of Birth" type="date" value={formData.dateOfBirth} onChange={handleChange} onBlur={handleBlur} error={touched.dateOfBirth ? errors.dateOfBirth : undefined} isTouched={touched.dateOfBirth} />
                                         <SmartSelectField id="gender" label="Gender" value={formData.gender} onChange={handleChange} onBlur={handleBlur} error={touched.gender ? errors.gender : undefined} isTouched={touched.gender}>
                                            <option>Male</option>
                                            <option>Female</option>
                                            <option>Other</option>
                                        </SmartSelectField>
                                        <div className="sm:col-span-2">
                                            <SmartInputField id="currentAddress" label="Current Address" value={formData.currentAddress} onChange={handleChange} onBlur={handleBlur} required error={touched.currentAddress ? errors.currentAddress : undefined} isTouched={touched.currentAddress} />
                                        </div>
                                        <PhoneInput id="telephone" name="telephone" label="Telephone" value={formData.telephone} onChange={handlePhoneChange('telephone')} required error={touched.telephone ? errors.telephone : undefined} />
                                        <EmailInput id="email" name="email" label="Email Address" value={formData.email} onChange={(val) => setFormData(prev => ({...prev, email: val}))} error={touched.email ? errors.email : undefined} />
                                    </div>
                                </div>
                                <div className="sm:col-span-1">
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Passport-sized Photo</label>
                                    <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-md">
                                        <div className="space-y-1 text-center">
                                            {photoPreview ? (
                                                <img src={photoPreview} alt="Client" className="mx-auto h-24 w-24 object-cover rounded-md" />
                                            ) : (
