                <QuickActionButton icon={<DocumentTextIcon className="w-6 h-6" />} label="Advanced Reports" color="bg-indigo-700" hoverColor="hover:bg-indigo-800" onClick={() => setActivePage('Advanced Reports')} />
            </div>

             {/* Staff Management Panel */}
            <Card 
