                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Input
                            label="Full Name*"
                            id="fullName"
                            name="fullName"
                            value={formData.fullName}
                            onChange={handleChange}
                            required
                        />
                        <Select
                            label="Assign To*"
                            id="assignedRepId"
                            name="assignedRepId"
                            value={formData.assignedRepId}
                            onChange={handleChange}
                            required
                        >
