                <div className="w-6 h-6 rounded-full bg-gray-200 dark:bg-gray-700 text-gray-600 dark:text-gray-300 flex items-center justify-center font-bold text-xs" title={assignedRep?.fullName}>
                    {assignedRep?.initials || '??'}
                </div>
            </div>
        </div>
    );
};

