import { db } from './firebase';
import { collection, getDocs, doc, setDoc, deleteDoc } from 'firebase/firestore';
import { Client, Lead, Staff } from '../types';

const CLIENTS_COLLECTION = 'clients';
const LEADS_COLLECTION = 'leads';
const USERS_COLLECTION = 'user';

// Helper to remove undefined fields which Firestore rejects
const sanitizeData = <T>(data: T): T => {
  return JSON.parse(JSON.stringify(data));
};

// --- Clients ---

export const fetchClients = async (): Promise<Client[]> => {
    try {
        const snapshot = await getDocs(collection(db, CLIENTS_COLLECTION));
        return snapshot.docs.map(doc => doc.data() as Client);
    } catch (error) {
        console.error("Error fetching clients from Firestore:", error);
        return [];
    }
};

export const persistClient = async (client: Client): Promise<void> => {
    try {
        // We use the client.id (number) converted to string as the document ID
        // to maintain consistency with the existing ID system.
        // Sanitize to remove undefined values (e.g. optional fields like promoDetails)
        const dataToSave = sanitizeData(client);
        await setDoc(doc(db, CLIENTS_COLLECTION, String(client.id)), dataToSave);
    } catch (error) {
        console.error("Error saving client to Firestore:", error);
        throw error;
    }
};

export const removeClient = async (id: number): Promise<void> => {
    try {
        await deleteDoc(doc(db, CLIENTS_COLLECTION, String(id)));
    } catch (error) {
        console.error("Error deleting client from Firestore:", error);
        throw error;
    }
};

// --- Leads ---

export const fetchLeads = async (): Promise<Lead[]> => {
    try {
        const snapshot = await getDocs(collection(db, LEADS_COLLECTION));
        return snapshot.docs.map(doc => doc.data() as Lead);
    } catch (error) {
        console.error("Error fetching leads from Firestore:", error);
        return [];
    }
};

export const persistLead = async (lead: Lead): Promise<void> => {
    try {
        const dataToSave = sanitizeData(lead);
        await setDoc(doc(db, LEADS_COLLECTION, String(lead.id)), dataToSave);
    } catch (error) {
        console.error("Error saving lead to Firestore:", error);
        throw error;
    }
};

export const removeLead = async (id: number): Promise<void> => {
    try {
        await deleteDoc(doc(db, LEADS_COLLECTION, String(id)));
    } catch (error) {
        console.error("Error deleting lead from Firestore:", error);
        throw error;
    }
};

// --- Staff / Users ---

export const fetchStaff = async (): Promise<Staff[]> => {
    try {
        const snapshot = await getDocs(collection(db, USERS_COLLECTION));
        return snapshot.docs.map(doc => doc.data() as Staff);
    } catch (error) {
        console.error("Error fetching staff from Firestore:", error);
        return [];
    }
};

export const persistStaff = async (staff: Staff): Promise<void> => {
    try {
        // IMPORTANT: We do NOT save the password to Firestore for security reasons.
        // The password field in the Staff type is primarily for local form handling or 
        // if we were sending it to a secure backend API to create a Firebase Auth user.
        const { password, ...staffDataWithoutPassword } = staff;

        const dataToSave = sanitizeData(staffDataWithoutPassword);
        await setDoc(doc(db, USERS_COLLECTION, String(staff.id)), dataToSave);
    } catch (error) {
        console.error("Error saving staff to Firestore:", error);
        throw error;
    }
};

export const removeStaff = async (id: string): Promise<void> => {
    try {
        await deleteDoc(doc(db, USERS_COLLECTION, String(id)));
    } catch (error) {
        console.error("Error deleting staff from Firestore:", error);
        throw error;
    }
};

