interface LeadsManagementPageProps {
    leads: Lead[];
    onSaveLead: (lead: Lead) => Promise<void>;
    onDeleteLead: (leadId: number) => Promise<void>;
    clients: Client[];
    onSaveClient: (client: Client) => Promise<Client>;
    staffList: Staff[];
    roles: Role[];
    properties: Property[];
    milestones: Milestone[];
    currentStaff: Staff;
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const LeadsManagementPage: React.FC<LeadsManagementPageProps> = ({ leads, onSaveLead, onDeleteLead, clients, onSaveClient, staffList, roles, milestones, currentStaff, addActivityLog }) => {
    const [activeTab, setActiveTab] = useState<'board' | 'list'>('board');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [editingLead, setEditingLead] = useState<Lead | null>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [draggedLeadId, setDraggedLeadId] = useState<number | null>(null);
    const [commentingLead, setCommentingLead] = useState<Lead | null>(null);

    // Delete Modal State
    const [leadToDelete, setLeadToDelete] = useState<Lead | null>(null);

    const salesReps = useMemo(() => staffList.filter(u => ['Head of Sales', 'Sales Representative'].includes(roles.find(r => r.id === u.roleId)?.name || '')), [staffList, roles]);

    const filteredLeads = useMemo(() => {
        if (!searchTerm) return leads;
        const lowercasedTerm = searchTerm.toLowerCase();
        return leads.filter(lead =>
            lead.fullName.toLowerCase().includes(lowercasedTerm) ||
            lead.email.toLowerCase().includes(lowercasedTerm) ||
            lead.phone.includes(lowercasedTerm)
        );
    }, [leads, searchTerm]);

    const handleOpenModal = (lead: Lead | null = null) => {
        setEditingLead(lead);
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setEditingLead(null);
        setIsModalOpen(false);
    };

    const handleSaveLead = (leadData: Omit<Lead, 'id' | 'createdAt' | 'lastContactDate' | 'comments'>) => {
        const currentDate = new Date().toISOString();
        if (editingLead) {
            const leadToSave = { ...editingLead, ...leadData, lastContactDate: currentDate };
            onSaveLead(leadToSave);
            addActivityLog('Update', `Updated lead details for ${leadData.fullName}.`);
        } else {
            const newLead: Lead = {
                id: Date.now(),
                ...leadData,
                status: 'Contacted',
                createdAt: currentDate,
                lastContactDate: currentDate,
                comments: []
            };
            onSaveLead(newLead);
            addActivityLog('Create', `Created new lead: ${newLead.fullName}.`);
        }
        handleCloseModal();
    };

    const handleDeleteClick = (id: number) => {
        const lead = leads.find(l => l.id === id);
        if (lead) {
            setLeadToDelete(lead);
        }
    };

    const confirmDeleteLead = async () => {
        if (leadToDelete) {
            await onDeleteLead(leadToDelete.id);
            addActivityLog('Delete', `Deleted lead: ${leadToDelete.fullName}.`);
            setLeadToDelete(null);
        }
    };

    const handleConvertLead = (lead: Lead) => {
        if (window.confirm(`This lead will now be converted to a client. Continue?`)) {
            const nameParts = lead.fullName.split(' ');
            const surname = nameParts.pop() || '';
            const otherNames = nameParts.join(' ');
            const initials = ((otherNames[0] || '') + (surname[0] || '')).toUpperCase();

            const newClient: Client = {
                id: clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1,
                name: lead.fullName, surname, otherNames, initials,
                regDate: new Date().toISOString().split('T')[0],
                email: lead.email, phone: lead.phone,
                location: 'N/A', plot: 'N/A', status: 'Active Client', stage: milestones[0]?.acronym || 'REG',
                payment: { total: 0, paid: 0, balance: 0, dueDate: 'N/A', planType: 'N/A', paymentHistory: [], installments: [] },
                interactions: lead.comments.map((c, i) => ({ id: i + 1, type: 'Note', date: c.date, agent: staffList.find(u => u.id === c.authorId)?.fullName || 'System', notes: `From Lead Follow-up: ${c.text}` })),
                witness: { name: '', address: '', phone: '' },
                nextOfKin: { name: '', phone: '', relationship: '' },
                indenture: { name: '', address: '' },
                officeUse: { salesRep: staffList.find(u=>u.id === lead.assignedRepId)?.fullName || '', salesManager: '', accountsHead: '', clerk: '', commission: { type: 'Percentage', amount: 0, status: 'Pending' } },
                documentation: { status: 'Pending' },
                isComplete: false,
                filledFormPdf: null,
            };

            onSaveClient(newClient);
            onDeleteLead(lead.id);
            addActivityLog('Update', `Converted lead ${lead.fullName} to a client.`);
        }
    };

    // Drag and Drop Handlers
    const handleDragStart = (e: React.DragEvent<HTMLDivElement>, leadId: number) => {
        setDraggedLeadId(leadId);
        e.dataTransfer.effectAllowed = 'move';
    };

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => e.preventDefault();

    const handleDrop = (e: React.DragEvent<HTMLDivElement>, newStatus: Lead['status']) => {
        e.preventDefault();
        if (draggedLeadId === null) return;

        const droppedLead = leads.find(l => l.id === draggedLeadId);
        if (!droppedLead || droppedLead.status === newStatus) return;

        if (newStatus === 'Converted to Client') {
            handleConvertLead(droppedLead);
        } else {
            const oldStatus = droppedLead.status;
            onSaveLead({ ...droppedLead, status: newStatus, lastContactDate: new Date().toISOString() });
            addActivityLog('Update', `Updated lead status for ${droppedLead.fullName} from "${oldStatus}" to "${newStatus}".`);
            setCommentingLead(leads.find(l => l.id === draggedLeadId)!);
        }
        setDraggedLeadId(null);
    };

    const handleAddComment = (leadId: number, text: string) => {
        const lead = leads.find(l => l.id === leadId);
        if (!lead) return;

        const newComment: LeadComment = {
            id: Date.now(),
            text,
            authorId: currentStaff.id,
            date: new Date().toISOString()
        };
        onSaveLead({ ...lead, comments: [...lead.comments, newComment], lastContactDate: new Date().toISOString() });
        addActivityLog('Update', `Added a comment to lead: ${lead.fullName}.`);
    };

    const handleImportLeads = (importedData: any[]) => {
      const highestId = leads.length > 0 ? Math.max(...leads.map(c => c.id)) : 0;

      const newLeads: Lead[] = importedData.map((data, index) => {
          const currentDate = new Date().toISOString();
          return {
              id: highestId + 1 + index,
              fullName: data.fullName || 'Unnamed Lead',
              email: data.email || '',
              phone: data.phone || '',
              source: data.source || 'Other',
              status: 'Contacted',
              assignedRepId: salesReps[0]?.id || '',
              nextFollowUpDate: '',
              lastContactDate: currentDate,
              notes: 'Imported via CSV.',
              createdAt: currentDate,
              comments: [],
          };
      });

      Promise.all(newLeads.map(lead => onSaveLead(lead)));
      addActivityLog('Import', `Imported ${newLeads.length} new leads from a CSV file.`);
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Lead Management & Follow-Up</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Visually track lead progress and manage conversions.</p>
                </div>
                <div className="flex items-center gap-4">
                    <button onClick={() => setImportWizardOpen(true)} className="bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 font-semibold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 flex items-center gap-2 transition-colors">
                        <UploadIcon className="w-5 h-5" /> Import Leads
                    </button>
                    <button onClick={() => handleOpenModal()} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors">
                        <PlusCircleIcon className="w-5 h-5" /> Add New Lead
                    </button>
                </div>
            </div>

            <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 flex flex-wrap gap-4 justify-between items-center transition-colors">
                <div className="flex border-b border-gray-200 dark:border-gray-700">
                    <button onClick={() => setActiveTab('board')} className={`px-4 py-2 font-semibold transition-colors ${activeTab === 'board' ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400'}`}>Follow-Up Board</button>
                    <button onClick={() => setActiveTab('list')} className={`px-4 py-2 font-semibold transition-colors ${activeTab === 'list' ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400'}`}>Lead List</button>
                </div>
                 <div className="relative flex-grow sm:flex-grow-0 sm:w-80">
                    <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 dark:text-gray-500" />
                    <input type="text" placeholder="Search leads..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-600 rounded-lg pl-10 pr-4 py-2 w-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400" />
                </div>
            </div>

            {activeTab === 'board' && (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4 items-start">
                    {KANBAN_STAGES.map(stage => (
                        <div key={stage} onDragOver={handleDragOver} onDrop={(e) => handleDrop(e, stage)} className="bg-gray-100 dark:bg-gray-900/50 p-3 rounded-lg min-h-[200px] border border-gray-200 dark:border-gray-700">
                            <h3 className={`font-semibold mb-3 pb-2 border-b-2 ${STAGE_COLORS[stage].border} ${STAGE_COLORS[stage].darkBorder} ${STAGE_COLORS[stage].text} ${STAGE_COLORS[stage].darkText}`}>
                                {stage} ({filteredLeads.filter(l => l.status === stage).length})
                            </h3>
                            <div className="space-y-3">
                                {filteredLeads.filter(l => l.status === stage).map(lead => (
                                    <KanbanCard 
                                        key={lead.id} 
                                        lead={lead} 
                                        assignedRep={staffList.find(u => u.id === lead.assignedRepId)}
                                        onDragStart={handleDragStart}
                                        onClick={setCommentingLead}
                                    />
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {activeTab === 'list' && (
                <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 overflow-x-auto transition-colors">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-50 dark:bg-gray-900 text-xs text-gray-700 dark:text-gray-300 uppercase">
                            <tr>
                                <th className="px-6 py-3">Lead Name & Contact</th>
                                <th className="px-6 py-3">Source</th>
                                <th className="px-6 py-3">Assigned To</th>
                                <th className="px-6 py-3">Last Contact</th>
                                <th className="px-6 py-3">Status</th>
                                <th className="px-6 py-3 text-center">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                            {filteredLeads.map(lead => (
                                <tr key={lead.id} className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700/50">
                                    <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">
                                        <div>{lead.fullName}</div>
                                        <div className="text-xs text-gray-500 dark:text-gray-400">{lead.email} | {lead.phone}</div>
                                    </td>
                                    <td className="px-6 py-4 text-gray-600 dark:text-gray-300">{lead.source}</td>
                                    <td className="px-6 py-4 text-gray-600 dark:text-gray-300">{staffList.find(r => r.id === lead.assignedRepId)?.fullName || 'Unassigned'}</td>
                                    <td className="px-6 py-4 text-gray-600 dark:text-gray-300">{new Date(lead.lastContactDate).toLocaleDateString()}</td>
                                    <td className="px-6 py-4"><span className={`px-2 py-1 text-xs font-semibold rounded-full ${STAGE_COLORS[lead.status].bg} ${STAGE_COLORS[lead.status].text} ${STAGE_COLORS[lead.status].darkBg} ${STAGE_COLORS[lead.status].darkText}`}>{lead.status}</span></td>
                                    <td className="px-6 py-4 text-center">
                                        <div className="flex items-center justify-center gap-2">
                                            {lead.status !== 'Converted to Client' && 
                                                <button onClick={() => handleConvertLead(lead)} className="text-green-600 hover:text-green-800 dark:text-green-400 dark:hover:text-green-300 p-1" title="Convert to Client"><ArrowRightOnRectangleIcon className="w-5 h-5"/></button>
                                            }
                                            <button onClick={() => setCommentingLead(lead)} className="text-gray-500 hover:text-indigo-600 dark:text-gray-400 dark:hover:text-indigo-400 p-1" title="View Comments"><ChatBubbleLeftEllipsisIcon className="w-5 h-5"/></button>
                                            <button onClick={() => handleOpenModal(lead)} className="text-gray-500 hover:text-blue-600 dark:text-gray-400 dark:hover:text-blue-400 p-1" title="Edit Lead"><PencilIcon className="w-5 h-5"/></button>
                                            <button onClick={() => handleDeleteClick(lead.id)} className="text-gray-500 hover:text-red-600 dark:text-gray-400 dark:hover:text-red-400 p-1" title="Delete Lead"><TrashIcon className="w-5 h-5"/></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {filteredLeads.length === 0 && <div className="text-center p-8 text-gray-500 dark:text-gray-400">No leads found.</div>}
                </div>
            )}

            <LeadForm isOpen={isModalOpen} onClose={handleCloseModal} onSave={handleSaveLead} salesReps={salesReps} editingLead={editingLead} />
            <CommentModal isOpen={!!commentingLead} onClose={() => setCommentingLead(null)} lead={commentingLead} onAddComment={handleAddComment} staffList={staffList} />
            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={handleImportLeads}
                requiredHeaders={['fullName', 'phone']}
                sampleHeaders="fullName,email,phone,source"
                sampleData="John Doe,john.doe@example.com,0241234567,Referral\nJane Smith,jane.smith@example.com,0559876543,Facebook"
                wizardTitle="Import Leads from CSV"
            />

            <DeleteConfirmationModal 
                isOpen={!!leadToDelete}
                onClose={() => setLeadToDelete(null)}
                onConfirm={confirmDeleteLead}
                itemName={leadToDelete?.fullName || ''}
                itemType="Lead"
            />
        </div>
    );
};

export default LeadsManagementPage;

import React, { useState, useCallback, ChangeEvent } from 'react';
import { XIcon } from './icons/XIcon';
import { UploadIcon, DocumentTextIcon, ExclamationTriangleIcon, CheckCircleIcon, ChevronLeftIcon, ChevronRightIcon } from './icons/DummyIcons';

interface CSVImportWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (data: any[]) => void;
  requiredHeaders: string[];
  sampleHeaders: string;
  sampleData: string;
  wizardTitle: string;
}

const CSVImportWizard: React.FC<CSVImportWizardProps> = ({ isOpen, onClose, onImport, requiredHeaders, sampleHeaders, sampleData, wizardTitle }) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [parsedData, setParsedData] = useState<any[]>([]);
    const [validationResults, setValidationResults] = useState<{ data: any; errors: string[] }[]>([]);
    const [errors, setErrors] = useState<string[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    const resetWizard = useCallback(() => {
        setStep(1);
        setFile(null);
        setParsedData([]);
        setValidationResults([]);
        setErrors([]);
        setIsLoading(false);
    }, []);

    const handleClose = useCallback(() => {
        resetWizard();
        onClose();
    }, [resetWizard, onClose]);

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const selectedFile = e.target.files[0];
            if (selectedFile.type === 'text/csv' || selectedFile.name.endsWith('.csv') || selectedFile.type === 'application/vnd.ms-excel') {
                 setFile(selectedFile);
                 setErrors([]);
            } else {
                setErrors(['Invalid file type. Please upload a .csv file.']);
                setFile(null);
            }
        }
    };

    // Robust CSV Line Parser to handle quoted fields containing commas
    const parseCSVLine = (text: string) => {
        const result = [];
        let cell = '';
        let inQuotes = false;

        for (let i = 0; i < text.length; i++) {
            const char = text[i];

            if (char === '"') {
                // Handle escaped quotes ("") inside a quoted string if needed, 
                // but primarily toggle quote state
                if (inQuotes && text[i + 1] === '"') {
                    cell += '"';
                    i++; // skip next quote
                } else {
                    inQuotes = !inQuotes;
                }
            } else if (char === ',' && !inQuotes) {
                // End of cell
                result.push(cell.trim());
                cell = '';
            } else {
                cell += char;
            }
        }
        // Push the last cell
        result.push(cell.trim());
        return result;
    };

    const processFile = useCallback(() => {
        if (!file) return;

        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                // Split by newline, filter empty lines
                const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');

                if (lines.length < 2) {
                    setErrors(['CSV file must have a header row and at least one data row.']);
                    setIsLoading(false);
                    return;
                }

                // Parse headers (strip BOM if present and quotes)
                const headerLine = lines[0].replace(/^\uFEFF/, ''); 
                const header = parseCSVLine(headerLine).map(h => h.replace(/^"|"$/g, '').trim());

                const missingHeaders = requiredHeaders.filter(rh => !header.includes(rh));
                const localErrors: string[] = [];

                if (missingHeaders.length > 0) {
                    localErrors.push(`Warning: Missing required columns: ${missingHeaders.join(', ')}. These fields will be blank.`);
                }

                const validatedData = [];
                for (let i = 1; i < lines.length; i++) {
                    const values = parseCSVLine(lines[i]);

                    // Skip empty rows that might happen due to trailing newlines
                    if (values.length === 1 && values[0] === '') continue;

                    const rowErrors: string[] = [];
                    const rowData: { [key: string]: string } = {};

                    header.forEach((h, index) => {
                        // Clean up quotes from values if they exist
                        rowData[h] = values[index] ? values[index].replace(/^"|"$/g, '') : '';
                    });

                    // Row-level validation
                    requiredHeaders.forEach(rh => {
                        if (!rowData[rh] || rowData[rh].trim() === '') {
                            rowErrors.push(`Missing required field: '${rh}'.`);
                        }
                    });

                    // Basic format validation
                    if (rowData.email && !/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(rowData.email)) {
                        rowErrors.push(`Invalid email format for '${rowData.email}'.`);
                    }

                    validatedData.push({ data: rowData, errors: rowErrors });
                }

                const validData = validatedData.filter(v => v.errors.length === 0).map(v => v.data);
                const invalidRowCount = validatedData.length - validData.length;

                if (invalidRowCount > 0) {
                    localErrors.push(`Found issues in ${invalidRowCount} row(s). These rows will be skipped.`);
                } else if (validData.length === 0) {
                    localErrors.push("No valid data rows found to import.");
                }

                setValidationResults(validatedData);
                setParsedData(validData);
                setErrors(localErrors);
                setStep(3);

            } catch (error) {
                 console.error(error);
                 setErrors(['An unexpected error occurred while parsing the file. Please check CSV format.']);
            } finally {
                setIsLoading(false);
            }
        };
        reader.onerror = () => {
             setErrors(['Failed to read the file.']);
             setIsLoading(false);
        }
        reader.readAsText(file);
    }, [file, requiredHeaders]);

    const handleNext = () => {
        if (step === 2 && file) {
            processFile();
        } else {
            setStep(s => s + 1);
        }
    };

    const handleBack = () => setStep(s => s - 1);

    const handleConfirmImport = () => {
        setIsLoading(true);
        // Using setTimeout to allow UI to update before heavy processing
        setTimeout(() => {
            onImport(parsedData);
            setStep(4);
            setIsLoading(false);
        }, 100);
    };

    const downloadSampleCSV = () => {
        const csvContent = `${sampleHeaders}\n${sampleData}`;
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement("a");
        if (link.download !== undefined) {
            const url = URL.createObjectURL(blob);
            link.setAttribute("href", url);
            link.setAttribute("download", "faim_import_sample.csv");
            link.style.visibility = 'hidden';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm" aria-modal="true" role="dialog">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white">{wizardTitle}</h2>
                    <button onClick={handleClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                        <XIcon className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 overflow-y-auto flex-grow bg-gray-50 dark:bg-gray-900">
                   {step === 1 && (
                        <div>
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">Step 1: Download Sample & Prepare Your File</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                To import data, you need a CSV file with specific columns. Download our sample file to see the required format.
                            </p>
                            <div className="mt-6 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
                                <h4 className="font-semibold text-blue-800 dark:text-blue-300">File Columns:</h4>
                                <div className="text-sm text-blue-700 dark:text-blue-200 mt-2 space-y-1 overflow-x-auto">
                                    <code className="font-mono whitespace-nowrap">{sampleHeaders.split(',').join(', ')}</code>
                                </div>
                                <p className="text-xs text-blue-600 dark:text-blue-400 mt-2">* Fields marked as required in the client form must not be empty.</p>
                            </div>
                            <div className="mt-6">
                                <button onClick={downloadSampleCSV} className="bg-green-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-green-700 flex items-center gap-2">
                                    <DocumentTextIcon className="w-5 h-5" />
                                    Download Sample CSV
                                </button>
                            </div>
                        </div>
                   )}
                   {step === 2 && (
                       <div>
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">Step 2: Upload Your CSV File</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                Drag and drop your file below or click to select the file from your computer.
                            </p>
                            <div className="mt-6 flex justify-center px-6 pt-10 pb-10 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-md">
                                <div className="space-y-1 text-center">
                                    <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                                    <div className="flex text-sm text-gray-600 dark:text-gray-400">
                                        <label htmlFor="file-upload" className="relative cursor-pointer bg-white dark:bg-gray-800 rounded-md font-medium text-blue-600 dark:text-blue-400 hover:text-blue-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500">
                                            <span>Upload a file</span>
                                            <input id="file-upload" name="file-upload" type="file" className="sr-only" onChange={handleFileChange} accept=".csv,text/csv,application/vnd.ms-excel" />
                                        </label>
                                        <p className="pl-1">or drag and drop</p>
                                    </div>
                                    <p className="text-xs text-gray-500 dark:text-gray-400">CSV file up to 5MB</p>
                                </div>
                            </div>
                            {file && (
                                <div className="mt-4 p-3 bg-gray-100 dark:bg-gray-700 rounded-md border border-gray-200 dark:border-gray-600 text-sm font-medium text-gray-700 dark:text-gray-200">
                                    Selected file: {file.name}
                                </div>
                            )}
                            {errors.length > 0 && <div className="mt-4 text-sm text-red-600 dark:text-red-400">{errors[0]}</div>}
                        </div>
                   )}
                   {step === 3 && (
                        <div>
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">Step 3: Preview and Confirm Import</h3>
                             <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                Review the data below. We'll import <span className="font-bold text-green-600 dark:text-green-400">{parsedData.length}</span> valid records.
                                <span className="font-bold text-red-600 dark:text-red-400"> {validationResults.length - parsedData.length}</span> records with errors will be skipped.
                            </p>
                            {errors.length > 0 && (
                                <div className="mt-4 p-4 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg">
                                    <h4 className="font-semibold text-yellow-800 dark:text-yellow-300 flex items-center gap-2"><ExclamationTriangleIcon className="w-5 h-5" /> Import Warnings</h4>
                                    <ul className="list-disc list-inside text-sm text-yellow-700 dark:text-yellow-200 mt-2 max-h-24 overflow-y-auto">
                                        {errors.map((err, i) => <li key={i}>{err}</li>)}
                                    </ul>
                                </div>
                            )}
                            <div className="mt-4 border border-gray-200 dark:border-gray-700 rounded-lg overflow-x-auto max-h-80">
                                <table className="w-full text-sm text-left">
                                    <thead className="bg-gray-100 dark:bg-gray-700 sticky top-0 z-10">
                                        <tr>
                                            <th className="px-4 py-2 font-semibold text-gray-600 dark:text-gray-300">Status</th>
                                            {Object.keys(validationResults[0]?.data || {}).slice(0, 5).map(key => <th key={key} className="px-4 py-2 font-semibold text-gray-600 dark:text-gray-300 whitespace-nowrap">{key}</th>)}
                                        </tr>
                                    </thead>
                                    <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                                        {validationResults.slice(0, 20).map((result, index) => (
                                            <tr key={index} className={result.errors.length > 0 ? 'bg-red-50 dark:bg-red-900/20' : 'bg-green-50 dark:bg-green-900/20'}>
                                                <td className="px-4 py-2">
                                                    {result.errors.length > 0 ? (
                                                        <div className="flex items-center gap-1 text-red-600 dark:text-red-400" title={result.errors.join('\n')}>
                                                            <ExclamationTriangleIcon className="w-4 h-4" />
                                                            <span className="text-xs font-semibold">Error</span>
                                                        </div>
                                                    ) : (
                                                        <div className="flex items-center gap-1 text-green-600 dark:text-green-400">
                                                            <CheckCircleIcon className="w-4 h-4" />
                                                            <span className="text-xs font-semibold">OK</span>
                                                        </div>
                                                    )}
                                                </td>
                                                {Object.values(result.data).slice(0, 5).map((val: any, i) => <td key={i} className="px-4 py-2 whitespace-nowrap text-gray-700 dark:text-gray-300">{val}</td>)}
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                            {validationResults.length > 20 && <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 text-center">... and {validationResults.length - 20} more rows.</p>}
                        </div>
                   )}
                   {step === 4 && (
                       <div className="text-center py-10">
                            <CheckCircleIcon className="mx-auto h-16 w-16 text-green-500" />
                            <h3 className="mt-4 text-xl font-semibold text-gray-900 dark:text-white">Import Successful!</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-400">
                                We have successfully queued <span className="font-bold">{parsedData.length}</span> records for background import.
                            </p>
                        </div>
                   )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <div>
                        {step > 1 && step < 4 && (
                            <button onClick={handleBack} className="bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-semibold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-600 flex items-center gap-2">
                                <ChevronLeftIcon className="w-5 h-5" /> Back
                            </button>
                        )}
                    </div>
                    <div>
                        {step < 3 && (
                            <button onClick={handleNext} disabled={(step === 2 && !file) || isLoading} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 disabled:bg-blue-300 flex items-center gap-2">
                                {isLoading ? 'Processing...' : `Next`} <ChevronRightIcon className="w-5 h-5" />
                            </button>
                        )}
                        {step === 3 && (
                            <button onClick={handleConfirmImport} disabled={parsedData.length === 0 || isLoading} className="bg-green-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-green-700 disabled:bg-green-300">
                                {isLoading ? 'Importing...' : `Confirm & Import ${parsedData.length} Records`}
                            </button>
                        )}
                        {step === 4 && (
                             <button onClick={handleClose} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700">
                                Finish
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CSVImportWizard;

import React, { useState, ChangeEvent, FormEvent } from 'react';
import { Client, Staff, AmendmentRequest } from '../types';
import { ArrowLeftIcon, CheckCircleIcon, UploadIcon } from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Select } from '../components/ui/Input';
import { PhoneInput } from '../components/ui/PhoneInput';
import { EmailInput } from '../components/ui/EmailInput';

interface AmendmentFormPageProps {
    client: Client;
    onBack: () => void;
    onSave: (amendmentData: AmendmentRequest) => void;
    currentStaff: Staff;
}

const initialFormState: Omit<AmendmentRequest, 'id' | 'clientId' | 'clientFullName' | 'clientPurchaseRef' | 'requestDate' | 'requestingStaffId' | 'scannedForm'> = {
    amendmentTypes: {
        personalDetails: false, nextOfKin: false, propertyReallocation: false,
        paymentPlan: false, indenture: false,
    },
    officeUse: {
        receivedBy: '', dateReceived: new Date().toISOString().split('T')[0], status: 'Pending'
    }
};

const TextArea: React.FC<{ label: string; id: string; value: string; onChange: (e: ChangeEvent<HTMLTextAreaElement>) => void; required?: boolean; rows?: number; name?: string }> = ({ label, id, value, onChange, required, rows = 3, name }) => (
    <div className="w-full">
      <label htmlFor={id} className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">{label}{required && <span className="text-red-500">*</span>}</label>
      <textarea
        id={id}
        name={name || id}
        value={value}
        onChange={onChange}
        required={required}
        rows={rows}
        className="block w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm placeholder-gray-400 dark:placeholder-gray-500 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
      />
    </div>
);

const AmendmentFormPage: React.FC<AmendmentFormPageProps> = ({ client, onBack, onSave, currentStaff }) => {
    const [formData, setFormData] = useState(initialFormState);
    const [scannedForm, setScannedForm] = useState<string | null>(null);
    const [formError, setFormError] = useState('');

    const handleTypeToggle = (type: keyof typeof formData.amendmentTypes) => {
        setFormData(prev => ({
            ...prev,
            amendmentTypes: { ...prev.amendmentTypes, [type]: !prev.amendmentTypes[type] }
        }));
    };

    const handleFormChange = (section: keyof AmendmentRequest, field: string, value: string | number) => {
        setFormData(prev => ({
            ...prev,
            [section]: { ...(prev[section] as object), [field]: value }
        }));
    };

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            if (file.type.startsWith('image/') || file.type === 'application/pdf') {
                const reader = new FileReader();
                reader.onloadend = () => { setScannedForm(reader.result as string); setFormError(''); };
                reader.readAsDataURL(file);
            } else {
                setFormError('Please upload a valid image or PDF file.');
            }
        }
    };

    const handleSubmit = (e: FormEvent) => {
        e.preventDefault();
        if (!scannedForm) {
            setFormError('A scanned copy of the filled amendment form is mandatory for submission.');
            return;
        }
        if (!Object.values(formData.amendmentTypes).some(t => t)) {
            setFormError('Please select at least one amendment type to proceed.');
            return;
        }
        setFormError('');

        const submissionData: AmendmentRequest = {
            ...formData,
            id: `AMD-${Date.now()}`,
            clientId: client.id,
            clientFullName: client.name,
            clientPurchaseRef: `${client.initials}-${client.id}`,
            requestDate: new Date().toISOString().split('T')[0],
            requestingStaffId: currentStaff.id,
            scannedForm: scannedForm,
            officeUse: {
                ...formData.officeUse,
                receivedBy: currentStaff.fullName
            }
        };

        onSave(submissionData);
    };

    return (
        <div className="space-y-6">
            <div>
                <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors">
                    <ArrowLeftIcon className="w-5 h-5" /> Back to Client Details
                </button>
                <h1 className="text-3xl font-bold text-gray-800 dark:text-white mt-2">Client Amendment & Reallocation Request</h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">Updating records for: <span className="font-semibold text-blue-600 dark:text-blue-400">{client.name}</span></p>
            </div>

            <form id="amendment-form" onSubmit={handleSubmit} className="space-y-6">
                <Card title="Amendment Request Type">
                    <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">Please tick relevant sections and complete only those you wish to amend.</p>
                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
                        {Object.keys(formData.amendmentTypes).map(key => (
                            <label key={key} className="flex items-center space-x-2 cursor-pointer p-2 rounded-md hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors">
                                <input 
                                    type="checkbox" 
                                    checked={formData.amendmentTypes[key as keyof typeof formData.amendmentTypes]} 
                                    onChange={() => handleTypeToggle(key as keyof typeof formData.amendmentTypes)} 
                                    className="h-4 w-4 text-blue-600 border-gray-300 dark:border-gray-600 rounded focus:ring-blue-500 bg-white dark:bg-gray-700"
                                />
                                <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())}</span>
                            </label>
                        ))}
                    </div>
                </Card>

                {formData.amendmentTypes.personalDetails && (
                    <Card title="1. Personal Details">
                        <div className="grid grid-cols-1 gap-y-6 gap-x-4 sm:grid-cols-2">
                            <Input 
                                id="dateOfBirth" 
                                name="dateOfBirth"
                                label="Date of Birth" 
                                type="date" 
                                value={formData.personalDetails?.dateOfBirth || ''} 
                                onChange={(e) => handleFormChange('personalDetails', e.target.name, e.target.value)} 
                            />
                            <Input 
                                id="currentAddress" 
                                name="currentAddress"
                                label="Current Address" 
                                value={formData.personalDetails?.currentAddress || ''} 
                                onChange={(e) => handleFormChange('personalDetails', e.target.name, e.target.value)} 
                            />
                            <PhoneInput 
                                id="phone" 
                                name="phone"
                                label="Phone Number" 
                                value={formData.personalDetails?.phone || ''} 
                                onChange={(val) => handleFormChange('personalDetails', 'phone', val)} 
                            />
                            <EmailInput 
                                id="email" 
                                name="email"
                                label="Email" 
                                value={formData.personalDetails?.email || ''} 
                                onChange={(val) => handleFormChange('personalDetails', 'email', val)} 
                            />
                            <div className="sm:col-span-2">
                                <TextArea 
                                    id="newDetailsToUpdate" 
                                    name="newDetailsToUpdate"
                                    label="New Details to be Updated (Summary)" 
                                    value={formData.personalDetails?.newDetailsToUpdate || ''} 
                                    onChange={(e) => handleFormChange('personalDetails', e.target.name, e.target.value)} 
                                />
                            </div>
                        </div>
                    </Card>
                )}

                {formData.amendmentTypes.nextOfKin && (
                    <Card title="2. Next of Kin Details">
                        <div className="grid grid-cols-1 gap-y-6 gap-x-4 sm:grid-cols-2">
                            <Input 
                                id="kinName" 
                                name="name"
                                label="Next of Kin Name" 
                                value={formData.nextOfKinDetails?.name || ''} 
                                onChange={(e) => handleFormChange('nextOfKinDetails', e.target.name, e.target.value)} 
                            />
                            <Input 
                                id="kinAddress" 
                                name="address"
                                label="Address" 
                                value={formData.nextOfKinDetails?.address || ''} 
                                onChange={(e) => handleFormChange('nextOfKinDetails', e.target.name, e.target.value)} 
                            />
                            <PhoneInput 
                                id="kinPhone" 
                                name="phone"
                                label="Phone Number" 
                                value={formData.nextOfKinDetails?.phone || ''} 
                                onChange={(val) => handleFormChange('nextOfKinDetails', 'phone', val)} 
                            />
                            <Input 
                                id="kinRelationship" 
                                name="relationship"
                                label="Relationship" 
                                value={formData.nextOfKinDetails?.relationship || ''} 
                                onChange={(e) => handleFormChange('nextOfKinDetails', e.target.name, e.target.value)} 
                            />
                            <EmailInput 
                                id="kinEmail" 
                                name="email"
                                label="Email" 
                                value={formData.nextOfKinDetails?.email || ''} 
                                onChange={(val) => handleFormChange('nextOfKinDetails', 'email', val)} 
                            />
                            <div className="sm:col-span-2">
                                <TextArea 
                                    id="kinNewDetails" 
                                    name="newDetailsToUpdate"
                                    label="New Details to be Updated (Summary)" 
                                    value={formData.nextOfKinDetails?.newDetailsToUpdate || ''} 
                                    onChange={(e) => handleFormChange('nextOfKinDetails', e.target.name, e.target.value)} 
                                />
                            </div>
                        </div>
                    </Card>
                )}

                <Card title="Upload Filled Form">
                     <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">Please upload a scanned PDF or image of the physically signed amendment form. This is mandatory.</p>
                     <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-dashed rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-900">
                        <div className="space-y-1 text-center">
                            {scannedForm ? <CheckCircleIcon className="mx-auto h-12 w-12 text-green-500" /> : <UploadIcon className="mx-auto h-12 w-12 text-gray-400 dark:text-gray-500" />}
                            <div className="flex text-sm text-gray-600 dark:text-gray-400">
                                <label htmlFor="scanned-form-upload" className="relative cursor-pointer bg-white dark:bg-gray-800 rounded-md font-medium text-blue-600 dark:text-blue-400 hover:text-blue-500 dark:hover:text-blue-300 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500">
                                    <span className="px-2">{scannedForm ? 'Change File' : 'Upload a file'}</span>
                                    <input id="scanned-form-upload" name="scannedForm" type="file" className="sr-only" onChange={handleFileChange} accept="image/*,application/pdf" />
                                </label>
                                <p className="pl-1">or drag and drop</p>
                            </div>
                            <p className="text-xs text-gray-500 dark:text-gray-500">{scannedForm ? 'File ready for submission.' : 'PDF, PNG, JPG up to 10MB'}</p>
                        </div>
                    </div>
                    {formError && <p className="mt-2 text-sm text-red-600 dark:text-red-400">{formError}</p>}
                </Card>

                <Card title="Office Use Only">
                    <div className="grid grid-cols-1 gap-y-6 gap-x-4 sm:grid-cols-2">
                        <Input 
                            id="approvedBy" 
                            name="approvedBy"
                            label="Approved By (Manager)" 
                            value={formData.officeUse.approvedBy || ''} 
                            onChange={e => handleFormChange('officeUse', 'approvedBy', e.target.value)} 
                        />
                        <Input 
                            id="newPlotAllocated" 
                            name="newPlotAllocated"
                            label="New Plot Allocated (if any)" 
                            value={formData.officeUse.newPlotAllocated || ''} 
                            onChange={e => handleFormChange('officeUse', 'newPlotAllocated', e.target.value)} 
                        />
                        <Input 
                            id="additionalFees" 
                            name="additionalFees"
                            label="Additional Fees (GHC)" 
                            type="number" 
                            value={formData.officeUse.additionalFees || ''} 
                            onChange={e => handleFormChange('officeUse', 'additionalFees', Number(e.target.value))} 
                        />
                        <Select 
                            id="status" 
                            name="status"
                            label="Status" 
                            value={formData.officeUse.status} 
                            onChange={e => handleFormChange('officeUse', 'status', e.target.value)}
                        >
                            <option>Pending</option>
                            <option>Approved</option>
                            <option>Rejected</option>
                        </Select>
                        <div className="sm:col-span-2">
                            <TextArea 
                                id="remarks" 
                                name="remarks"
                                label="Remarks / Actions Taken" 
                                value={formData.officeUse.remarks || ''} 
                                onChange={e => handleFormChange('officeUse', 'remarks', e.target.value)} 
                            />
                        </div>
                    </div>
                </Card>

            </form>

            <div className="sticky bottom-0 bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm p-4 border-t border-gray-200 dark:border-gray-700 flex justify-end transition-colors">
                <Button type="submit" form="amendment-form">
                    Submit Amendment Request
                </Button>
            </div>
        </div>
    );
};

