            return;
        }
        if (!receiptNumber.trim()) {
            setError('Receipt number is required before saving payment.');
            return;
        }
        setError('');
        onSave({ date, amount: paidAmount, method, reference, receiptNumber });
    };

    if (!isOpen) return null;

    return (
