     useEffect(() => {
        if (!selectedClient) {
            setCalculatedTotal(null);
            return;
        }

        const P = selectedClient.payment.total;
        const ANNUAL_RATE = 0.10; // 10% annual interest rate
        const r = ANNUAL_RATE / 12;
