        if (n > 0 && !isNaN(n) && r > 0 && P > 0 && paymentOption !== 'Outright') {
            const emi = (P * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1);
            const totalPayable = emi * n;
            setCalculatedTotal(totalPayable);
        } else {
