const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, 
    onSaveClient, 
    onClientSelect, 
    invoices, 
    onSaveInvoice, 
    clientForInvoice, 
    setClientForInvoice, 
    currentStaff 
}) => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

    // Open modal automatically if clientForInvoice is set (navigated from another page)
    useEffect(() => {
        if (clientForInvoice) {
            setIsModalOpen(true);
        }
    }, [clientForInvoice]);

    const handleCloseModal = () => {
        setIsModalOpen(false);
        setEditingInvoice(null);
        setClientForInvoice(null);
    };

    const handleSaveInvoiceData = async (invoice: Invoice, updatedClient?: Client) => {
        await onSaveInvoice(invoice);
        if (updatedClient) {
            await onSaveClient(updatedClient);
        }
        handleCloseModal();
    };

    const handleRecordPayment = async (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'>) => {
        const newPayment: PaymentTransaction = {
            id: `PAY-${Date.now()}`,
            status: 'Success', // Assuming success for manual entry
            ...paymentData
        };

        // Update client payment history and balance
        const updatedClient = { ...client };
        updatedClient.payment.paymentHistory = [newPayment, ...updatedClient.payment.paymentHistory];
        updatedClient.payment.paid += paymentData.amount;
        updatedClient.payment.balance = updatedClient.payment.total - updatedClient.payment.paid;

        // Update installments if any
        if (updatedClient.payment.installments.length > 0) {
             // Logic to distribute payment across installments could go here, 
             // but for now we just update main balance.
             // A simple logic: pay off earliest pending installments
             let amountToDistribute = paymentData.amount;
             updatedClient.payment.installments = updatedClient.payment.installments.map(inst => {
                 if (amountToDistribute <= 0 || inst.status === 'Paid') return inst;
                 const pending = inst.amountDue - inst.amountPaid;
                 const pay = Math.min(pending, amountToDistribute);
                 inst.amountPaid += pay;
                 inst.balance -= pay;
                 if (inst.balance <= 0) inst.status = 'Paid';
                 amountToDistribute -= pay;
                 return inst;
             });
        }

        await onSaveClient(updatedClient);
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Account Management</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Manage invoices, payments, and financial records.</p>
                </div>
                <Button onClick={() => setIsModalOpen(true)} icon={<DocumentPlusIcon className="w-5 h-5" />}>
                    New Record / View Financials
                </Button>
            </div>

            {/* Invoices List */}
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden">
                <div className="p-4 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center">
                    <h2 className="text-lg font-bold text-gray-800 dark:text-white">Recent Invoices</h2>
                </div>
                <TableContainer>
                    <table className="w-full text-sm text-left">
                        <Thead>
                            <tr>
                                <Th>Invoice ID</Th>
                                <Th>Client</Th>
                                <Th>Date</Th>
                                <Th>Due Date</Th>
                                <Th>Amount</Th>
                                <Th className="text-center">Status</Th>
                                <Th className="text-center">Actions</Th>
                            </tr>
                        </Thead>
                        <Tbody>
                            {invoices.length === 0 ? (
                                <tr><Td className="text-center" colSpan={7}>No invoices found.</Td></tr>
                            ) : (
                                invoices.map(invoice => (
                                    <Tr key={invoice.id}>
                                        <Td className="font-mono">{invoice.id}</Td>
                                        <Td>{invoice.clientName}</Td>
                                        <Td>{invoice.issueDate}</Td>
                                        <Td>{invoice.dueDate}</Td>
                                        <Td className="font-semibold">{formatCurrency(invoice.amount)}</Td>
                                        <Td className="text-center">{getStatusBadge(invoice.status)}</Td>
                                        <Td className="text-center">
                                            <button onClick={() => { setEditingInvoice(invoice); setIsModalOpen(true); }} className="text-gray-500 hover:text-blue-600 dark:text-gray-400 dark:hover:text-blue-400">
                                                <PencilIcon className="w-5 h-5" />
                                            </button>
                                        </Td>
                                    </Tr>
                                ))
                            )}
                        </Tbody>
                    </table>
                </TableContainer>
            </div>

            <InvoiceFormModal 
                isOpen={isModalOpen} 
                onClose={handleCloseModal} 
                clients={clients} 
                onSave={handleSaveInvoiceData} 
                onRecordPayment={handleRecordPayment}
                editingInvoice={editingInvoice}
                clientForInvoice={clientForInvoice}
            />
        </div>
    );
};

export default AccountManagementPage;

