import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import * as dataService from '../services/dataService';
import * as dbService from '../services/dbService';
import { registerUser } from '../services/authService';
import { 
    Client, Property, Invoice, Staff, Lead, Promotion, 
    CompanySettings, ActivityLog, Role, AmendmentRequest, RolePermission 
} from '../types';
import { ROLES, AMENDMENT_REQUESTS as MOCK_AMENDMENT_REQUESTS, ROLE_PERMISSIONS } from '../data/mockData';

interface DataContextType {
    clients: Client[];
    properties: Property[];
    invoices: Invoice[];
    staff: Staff[];
    leads: Lead[];
    promotions: Promotion[];
    companySettings: CompanySettings;
    activityLogs: ActivityLog[];
    roles: Role[];
    rolePermissions: RolePermission[];
    amendments: AmendmentRequest[];

    // Actions
    saveClient: (client: Client) => Promise<Client>;
    deleteClient: (id: number) => Promise<void>;
    saveProperty: (property: Property) => Promise<void>;
    saveInvoice: (invoice: Invoice) => Promise<void>;
    saveLead: (lead: Lead) => Promise<void>;
    deleteLead: (id: number) => Promise<void>;
    savePromotion: (promotion: Promotion) => Promise<void>;
    deletePromotion: (id: number) => Promise<void>;
    saveStaff: (staff: Staff) => Promise<void>;
    deleteStaff: (id: string) => Promise<void>;
    updateStaff: (id: string, details: Partial<Staff>) => Promise<void>;
    setStaff: React.Dispatch<React.SetStateAction<Staff[]>>;
    setRoles: React.Dispatch<React.SetStateAction<Role[]>>;
    setRolePermissions: React.Dispatch<React.SetStateAction<RolePermission[]>>;
    setCompanySettings: React.Dispatch<React.SetStateAction<CompanySettings>>;
    addActivityLog: (type: ActivityLog['type'], description: string, userId?: string) => void;
    setAmendmentList: React.Dispatch<React.SetStateAction<AmendmentRequest[]>>;
    setInvoiceList: React.Dispatch<React.SetStateAction<Invoice[]>>;
    setClientList: React.Dispatch<React.SetStateAction<Client[]>>;
    setLeadList: React.Dispatch<React.SetStateAction<Lead[]>>;
    setPromotionList: React.Dispatch<React.SetStateAction<Promotion[]>>;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const queryClient = useQueryClient();
    const appData = dataService.loadAppData();

    // -- React Query: Stale-While-Revalidate Caching for Async Data --
    const { data: dbClients = [] } = useQuery({
        queryKey: ['clients'],
        queryFn: dbService.fetchClients,
        staleTime: 1000 * 60 * 5, // 5 minutes cache
    });

    const { data: dbLeads = [] } = useQuery({
        queryKey: ['leads'],
        queryFn: dbService.fetchLeads,
        staleTime: 1000 * 60 * 5,
    });

    const { data: dbStaff = [] } = useQuery({
        queryKey: ['staff'],
        queryFn: dbService.fetchStaff,
        staleTime: 1000 * 60 * 5,
    });

    // -- Local State for non-DB entities (managed via localStorage currently) --
    const [propertyList, setPropertyList] = useState<Property[]>(appData.properties);
    const [invoiceList, setInvoiceList] = useState<Invoice[]>(appData.invoices);
    const [roleList, setRoleList] = useState<Role[]>(ROLES);
    const [rolePermissions, setRolePermissions] = useState<RolePermission[]>(ROLE_PERMISSIONS);
    const [companySettings, setCompanySettings] = useState<CompanySettings>(appData.settings);
    const [activityLogs, setActivityLogs] = useState<ActivityLog[]>(appData.logs);
    const [promotionList, setPromotionList] = useState<Promotion[]>(appData.promotions);
    const [amendmentList, setAmendmentList] = useState<AmendmentRequest[]>(MOCK_AMENDMENT_REQUESTS);

    // --- Persistence Effect for LocalStorage Data ---
    useEffect(() => {
        dataService.saveAllData({
            clients: [], // Managed by Firestore
            leads: [],   // Managed by Firestore
            staff: [],   // Managed by Firestore
            properties: propertyList,
            invoices: invoiceList,
            promotions: promotionList,
            settings: companySettings,
            logs: activityLogs
        });
    }, [propertyList, invoiceList, promotionList, companySettings, activityLogs]);

    const addActivityLog = useCallback((type: ActivityLog['type'], description: string, userId?: string) => {
        const newLog: ActivityLog = {
            id: Date.now(),
            userId: userId || '0', 
            type,
            description,
            timestamp: new Date().toISOString(),
        };
        setActivityLogs(prev => [newLog, ...prev]);
    }, []);

    // --- Actions with React Query Mutations ---

    const saveClient = async (client: Client) => {
        await dbService.persistClient(client);
        await queryClient.invalidateQueries({ queryKey: ['clients'] });
        return client;
    };

    const deleteClient = async (clientId: number) => {
        await dbService.removeClient(clientId);
        await queryClient.invalidateQueries({ queryKey: ['clients'] });
    };

    const saveLead = async (lead: Lead) => {
        await dbService.persistLead(lead);
        await queryClient.invalidateQueries({ queryKey: ['leads'] });
    };

    const deleteLead = async (leadId: number) => {
        await dbService.removeLead(leadId);
        await queryClient.invalidateQueries({ queryKey: ['leads'] });
    };

    const saveStaff = async (staffMember: Staff) => {
        let finalStaffMember = { ...staffMember };
        const exists = dbStaff.some(s => s.id === staffMember.id);

        // If creating a new staff member (not just updating), create Auth User first
        if (!exists && staffMember.password) {
            const user = await registerUser(staffMember.email, staffMember.password);
            finalStaffMember.id = user.uid; // Use the Firebase Auth UID as the Staff ID
        }

        await dbService.persistStaff(finalStaffMember);
        await queryClient.invalidateQueries({ queryKey: ['staff'] });
    };

    const deleteStaff = async (staffId: string) => {
        await dbService.removeStaff(staffId);
        await queryClient.invalidateQueries({ queryKey: ['staff'] });
    };

    const updateStaff = async (staffId: string, details: Partial<Staff>) => {
        const staffMember = dbStaff.find(s => s.id === staffId);
        if (staffMember) {
            const updatedStaff = { ...staffMember, ...details };
            await dbService.persistStaff(updatedStaff);
            await queryClient.invalidateQueries({ queryKey: ['staff'] });
        }
    };

    // --- Actions for Local Data ---

    const saveProperty = async (property: Property) => {
        let updatedList: Property[];
        const exists = propertyList.some(p => p.id === property.id);
        if (exists) {
            updatedList = propertyList.map(p => p.id === property.id ? property : p);
        } else {
            updatedList = [property, ...propertyList];
        }
        setPropertyList(updatedList);
    };

    const saveInvoice = async (invoice: Invoice) => {
        let updatedList: Invoice[];
        const exists = invoiceList.some(i => i.id === invoice.id);
        if (exists) {
            updatedList = invoiceList.map(i => i.id === invoice.id ? invoice : i);
        } else {
            updatedList = [invoice, ...invoiceList];
        }
        setInvoiceList(updatedList);
    };

    const savePromotion = async (promotion: Promotion) => {
        let updatedList: Promotion[];
        const exists = promotionList.some(p => p.id === promotion.id);
        if (exists) {
            updatedList = promotionList.map(p => p.id === promotion.id ? promotion : p);
        } else {
            updatedList = [promotion, ...promotionList];
        }
        setPromotionList(updatedList);
    };

    const deletePromotion = async (promotionId: number) => {
        setPromotionList(prev => prev.filter(p => p.id !== promotionId));
    };

    // Compatibility Setters (Deprecated in favor of React Query mutations but kept for interface/Admin compatibility)
    const setStaff: React.Dispatch<React.SetStateAction<Staff[]>> = (action) => {
        console.warn("setStaff called but state is managed by React Query. Use saveStaff/updateStaff instead.");
    };
    const setClientList: React.Dispatch<React.SetStateAction<Client[]>> = (action) => {
        console.warn("setClientList called but state is managed by React Query. Use saveClient instead.");
    };
    const setLeadList: React.Dispatch<React.SetStateAction<Lead[]>> = (action) => {
        console.warn("setLeadList called but state is managed by React Query. Use saveLead instead.");
    };

    return (
        <DataContext.Provider value={{
            clients: dbClients,
            properties: propertyList,
            invoices: invoiceList,
            staff: dbStaff,
            leads: dbLeads,
            promotions: promotionList,
            companySettings,
            activityLogs,
            roles: roleList,
            rolePermissions,
            amendments: amendmentList,
            saveClient,
            deleteClient,
            saveProperty,
            saveInvoice,
            saveLead,
            deleteLead,
            savePromotion,
            deletePromotion,
            saveStaff,
            deleteStaff,
            updateStaff,
            setStaff,
            setRoles: setRoleList,
            setRolePermissions,
            setCompanySettings,
            addActivityLog,
            setAmendmentList,
            setInvoiceList,
            setClientList,
            setLeadList,
            setPromotionList
        }}>
            {children}
        </DataContext.Provider>
    );
};

export const useData = () => {
    const context = useContext(DataContext);
    if (context === undefined) {
        throw new Error('useData must be used within a DataProvider');
    }
    return context;
};

import React, { useState, useMemo } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import LeadsManagementPage from './pages/LeadsManagementPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import PlaceholderPage from './pages/PlaceholderPage';
import MappingsPage from './pages/MappingsPage';

import { DataProvider, useData } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { ROLES, GENERATED_REPORTS } from './data/mockData';
import { Client, PermissionSet, AppModuleName } from './types';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

const queryClient = new QueryClient();

const AppContent: React.FC = () => {
    const { 
        clients, properties, invoices, staff, leads, promotions, 
        companySettings, activityLogs, roles, amendments, rolePermissions,
        saveClient, deleteClient, saveProperty, saveInvoice, 
        saveLead, deleteLead, savePromotion, deletePromotion,
        updateStaff, setStaff, setRoles, setCompanySettings,
        addActivityLog, setAmendmentList, setClientList
    } = useData();

    const { currentStaff, login, logout, isAuthenticated } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    // Helper for context-aware logger
    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        setActivePage(page);
        setPageContext(context);
    };

    if (!isAuthenticated || !currentStaff) {
        return <LoginPage onLogin={login} companySettings={companySettings} />;
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard':
                return <Dashboard />;
            case 'Clients':
                return <ClientsPage 
                    clients={clients} 
                    onSaveClient={saveClient}
                    onDeleteClient={deleteClient}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]}
                    onClientSelect={(client) => handleSetPage('Client Details', client)} 
                    setActivePage={handleSetPage}
                    setClientForInvoice={setClientForInvoice}
                    invoices={invoices}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Client Details':
                return <ClientDetailPage 
                    client={pageContext} 
                    properties={properties}
                    onBack={() => handleSetPage('Clients')}
                    currentStaff={currentStaff}
                    roles={roles}
                    setActivePage={handleSetPage}
                />;
            case 'Account Management':
                 return <AccountManagementPage 
                    clients={clients}
                    onSaveClient={saveClient}
                    onClientSelect={(client) => handleSetPage('Client Details', client)}
                    invoices={invoices}
                    onSaveInvoice={saveInvoice}
                    clientForInvoice={clientForInvoice}
                    setClientForInvoice={setClientForInvoice}
                    receiptPattern={null} 
                    setReceiptPattern={() => {}}
                    setReceiptAlerts={() => {}}
                    currentStaff={currentStaff}
                 />;
            case 'Settings':
                return <SettingsPage 
                    currentStaff={currentStaff} 
                    staff={staff}
                    roles={roles}
                    setRoles={setRoles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    companySettings={companySettings}
                    setCompanySettings={setCompanySettings}
                    onUpdateStaff={updateStaff}
                />;
            case 'CEO Hub':
                 return <CEOHub
                    setActivePage={handleSetPage}
                    properties={properties}
                    clients={clients}
                    invoices={invoices}
                    staff={staff}
                    roles={roles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    addActivityLog={handleAddActivityLog}
                />;
             case 'Properties':
                return <PropertiesPage properties={properties} currentStaff={currentStaff} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
             case 'New Land Acquisition':
                return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
             case 'Promotions':
                return <PromotionsPage 
                    promotions={promotions} 
                    onSavePromotion={savePromotion}
                    onDeletePromotion={deletePromotion}
                    properties={properties} 
                    showForm={true} 
                    onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} 
                />;
            case 'Administration':
                return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Lead Management & Follow-Up':
                return <LeadsManagementPage 
                    leads={leads} 
                    onSaveLead={saveLead}
                    onDeleteLead={deleteLead}
                    clients={clients} 
                    onSaveClient={saveClient}
                    staffList={staff} 
                    roles={roles}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }]} 
                    currentStaff={currentStaff} 
                    addActivityLog={handleAddActivityLog} 
                />;
            case 'Human Resources':
                return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} setStaff={setStaff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts':
                return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot':
                return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation':
                return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Mappings':
                return <MappingsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Amendment Form':
                return (
                    <AmendmentFormPage 
                        client={pageContext} 
                        onBack={() => handleSetPage('Client Details', pageContext)} 
                        onSave={async (data, updatedClient) => { 
                            // 1. Save the Amendment Request to local state (or ideally Firestore 'amendments' collection in future)
                            setAmendmentList(prev => [data, ...prev]); 

                            // 2. Update the Client Record in Firestore
                            await saveClient(updatedClient);

                            handleAddActivityLog('Update', `Processed amendment request for client: ${updatedClient.name}`);
                            alert('Amendment processed and client record updated successfully!'); 

                            // 3. Navigate back to Client Details with the UPDATED client data
                            handleSetPage('Client Details', updatedClient);
                        }} 
                        currentStaff={currentStaff} 
                    />
                );
            case 'Analytics & Reports':
                return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports':
                return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity':
                return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Mailing':
            case 'Leave':
            case 'Knowledge Base':
            case 'Event':
            case 'Announcement':
            case 'Support':
                return <PlaceholderPage title={activePage} onBack={() => handleSetPage('Dashboard')} />;
            default:
                return <div>Page not found</div>;
        }
    };

    // Calculate Permissions based on the User's Role ID from the Context
    const staffPermissions = useMemo(() => {
        const userPermissions: { [key: string]: PermissionSet } = {};

        // Find all permissions associated with the current staff's role ID
        const rolePerms = rolePermissions.filter(rp => rp.roleId === currentStaff.roleId);

        rolePerms.forEach(rp => {
            userPermissions[rp.moduleId] = rp.permissions;
        });

        // Fallback/Default if no permissions found (e.g., deleted role) - give minimal access
        if (Object.keys(userPermissions).length === 0) {
             // Defaults to Dashboard view only to prevent lockout
             userPermissions['Dashboard'] = { view: true, create: false, edit: false, delete: false, approve: false };
        }

        return userPermissions;
    }, [currentStaff.roleId, rolePermissions]);

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff} 
            onLogout={logout}
            staffPermissions={staffPermissions}
            companySettings={companySettings}
        >
            {renderPage()}
        </Layout>
    );
};

const App: React.FC = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <DataProvider>
                    <AuthProvider>
                        <AppContent />
                    </AuthProvider>
                </DataProvider>
            </ThemeProvider>
        </QueryClientProvider>
    );
};

export default App;

import React, { useState, useMemo, ChangeEvent } from 'react';
import { Staff, Role, AppModuleName, CompanySettings } from '../types';
import { APP_MODULES } from '../data/mockData';
import { Cog6ToothIcon, ShieldCheckIcon, UsersIcon, PlusCircleIcon, PencilIcon, TrashIcon, EyeIcon, UserCircleIcon, BuildingLibraryIcon } from '../components/icons/DummyIcons';
import UserFormModal from '../components/UserFormModal';
import { PhoneInput } from '../components/ui/PhoneInput';
import { EmailInput } from '../components/ui/EmailInput';
import { useData } from '../context/DataContext';

interface SettingsPageProps {
    currentStaff: Staff;
    staff: Staff[];
    roles: Role[];
    setRoles: React.Dispatch<React.SetStateAction<Role[]>>;
    onViewStaffActivity: (staff: Staff) => void;
    companySettings: CompanySettings;
    setCompanySettings: React.Dispatch<React.SetStateAction<CompanySettings>>;
    onUpdateStaff: (id: string, details: Partial<Staff>) => Promise<void>;
}

const SettingsPage: React.FC<SettingsPageProps> = ({ currentStaff, staff, roles, setRoles, onViewStaffActivity, companySettings, setCompanySettings, onUpdateStaff }) => {
    const { saveStaff, deleteStaff, rolePermissions, setRolePermissions } = useData();
    const [activeTab, setActiveTab] = useState('profile');
    const [selectedRole, setSelectedRole] = useState<Role | null>(roles[0] || null);

    // State for Modals
    const [isStaffModalOpen, setStaffModalOpen] = useState(false);
    const [isRoleModalOpen, setRoleModalOpen] = useState(false);
    const [editingStaff, setEditingStaff] = useState<Staff | null>(null);
    const [editingRole, setEditingRole] = useState<Role | null>(null);
    const [newRoleData, setNewRoleData] = useState({ name: '', description: '' });

    // State for Delete Confirmation
    const [staffToDelete, setStaffToDelete] = useState<Staff | null>(null);

    // State for local forms
    const [profileData, setProfileData] = useState({ fullName: currentStaff.fullName, email: currentStaff.email, phone: currentStaff.phone || '' });
    const [companyData, setCompanyData] = useState({ name: companySettings.name });
    const [profilePhotoPreview, setProfilePhotoPreview] = useState<string | null>(currentStaff.photo || null);
    const [companyLogoPreview, setCompanyLogoPreview] = useState<string | null>(companySettings.logo || null);

    const userRole = useMemo(() => roles.find(r => r.id === currentStaff.roleId), [currentStaff, roles]);
    const canManageStaff = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);
    const canManageCompany = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);

    const handlePermissionChange = (moduleId: AppModuleName, permission: string, value: boolean) => {
        if (!selectedRole) return;
        setRolePermissions(prev =>
            prev.map(rp =>
                rp.roleId === selectedRole.id && rp.moduleId === moduleId
                    ? { ...rp, permissions: { ...rp.permissions, [permission]: value } }
                    : rp
            )
        );
    };

    const handleSaveRole = (e: React.FormEvent) => {
        e.preventDefault();
        const roleData = newRoleData;
        if (editingRole) {
            setRoles(prev => prev.map(r => r.id === editingRole.id ? { ...editingRole, ...roleData } : r));
        } else {
            const newRole: Role = { id: Date.now(), ...roleData };
            setRoles(prev => [...prev, newRole]);
            const newPermissions = APP_MODULES.map(m => ({
                roleId: newRole.id,
                moduleId: m.id as AppModuleName,
                permissions: { view: false, create: false, edit: false, delete: false, approve: false }
            }));
            setRolePermissions(prev => [...prev, ...newPermissions]);
        }
        setRoleModalOpen(false);
        setEditingRole(null);
        setNewRoleData({ name: '', description: '' });
    };

    const handleDeleteRole = (roleId: number) => {
        if (window.confirm("Are you sure you want to delete this role? This cannot be undone.")) {
            if (staff.some(u => u.roleId === roleId)) {
                alert("Cannot delete role. It is currently assigned to one or more staff members.");
                return;
            }
            setRoles(prev => prev.filter(r => r.id !== roleId));
            setRolePermissions(prev => prev.filter(rp => rp.roleId !== roleId));
            if (selectedRole?.id === roleId) setSelectedRole(roles[0] || null);
        }
    };

    const handleSaveStaff = async (staffData: Partial<Staff>) => {
        try {
            if(editingStaff) {
                await onUpdateStaff(editingStaff.id, staffData);
            } else {
                const nameParts = staffData.fullName!.split(' ');
                const initials = (nameParts[0]?.[0] || '' + nameParts[nameParts.length - 1]?.[0] || '').toUpperCase();
                // Note: The roleId is passed from the form and matches the IDs in the ROLES array.
                const newStaff: Staff = { 
                    id: String(Date.now()), 
                    fullName: staffData.fullName!, email: staffData.email!, phone: staffData.phone,
                    password: staffData.password, roleId: staffData.roleId!, status: staffData.status!,
                    lastLogin: 'Never', initials: initials
                };
                await saveStaff(newStaff);
            }
            setStaffModalOpen(false);
            setEditingStaff(null);
        } catch (error: any) {
            alert(`Error saving staff: ${error.message || 'Unknown error'}`);
        }
    }

    // Initiate delete flow
    const handleDeleteClick = (staffMember: Staff) => {
        if (staffMember.id === currentStaff.id) {
            alert("You cannot delete your own account.");
            return;
        }
        setStaffToDelete(staffMember);
    }

    // Execute delete
    const confirmDeleteStaff = async () => {
        if (staffToDelete) {
            await deleteStaff(staffToDelete.id);
            setStaffToDelete(null);
        }
    }

    const handleProfileFormChange = (e: ChangeEvent<HTMLInputElement>) => {
        setProfileData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const handleProfilePhotoChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = reader.result as string;
                setProfilePhotoPreview(base64);
                onUpdateStaff(currentStaff.id, { photo: base64 });
            };
            reader.readAsDataURL(e.target.files[0]);
        }
    };

    const handleCompanyLogoChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = reader.result as string;
                setCompanyLogoPreview(base64);
                setCompanySettings(prev => ({ ...prev, logo: base64 }));
            };
            reader.readAsDataURL(e.target.files[0]);
        }
    };

    const handleSaveCompanySettings = () => {
        setCompanySettings(prev => ({ ...prev, name: companyData.name }));
        alert('Company settings saved.');
    };

    const RolePill: React.FC<{ role: Role }> = ({ role }) => {
        const roleColors: { [key: string]: string } = {
            'CEO': 'bg-yellow-100 text-yellow-800 border-yellow-200 dark:bg-yellow-900/30 dark:text-yellow-300 dark:border-yellow-800',
            'Administrator': 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-800',
            'Chief Accountant': 'bg-green-100 text-green-800 border-green-200 dark:bg-green-900/30 dark:text-green-300 dark:border-green-800',
            'Head of Sales': 'bg-purple-100 text-purple-800 border-purple-200 dark:bg-purple-900/30 dark:text-purple-300 dark:border-purple-800',
        };
        const defaultColor = 'bg-gray-100 text-gray-800 border-gray-200 dark:bg-gray-700 dark:text-gray-300 dark:border-gray-600';
        const color = roleColors[role.name] || defaultColor;
        return <span className={`px-2 py-1 text-xs font-semibold rounded-full border ${color}`}>{role.name}</span>
    }

    const tabs = [
        { id: 'profile', name: 'My Profile', icon: <UserCircleIcon className="w-5 h-5" /> },
        { id: 'company', name: 'Company Settings', icon: <BuildingLibraryIcon className="w-5 h-5" />, disabled: !canManageCompany },
        { id: 'roles', name: 'Roles & Permissions', icon: <ShieldCheckIcon className="w-5 h-5" />, disabled: !canManageStaff },
        { id: 'staff', name: 'Staff Accounts', icon: <UsersIcon className="w-5 h-5" />, disabled: !canManageStaff },
    ];

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">System Settings</h1>

            <div className="flex border-b border-gray-200 dark:border-gray-700">
                {tabs.map(tab => !tab.disabled && (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-2 px-4 py-3 font-semibold transition-colors ${activeTab === tab.id ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400' : 'text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white'}`}>
                        {tab.icon} {tab.name}
                    </button>
                ))}
            </div>

            {activeTab === 'profile' && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4">Edit Your Profile</h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
                        <div className="md:col-span-1 flex flex-col items-center">
                            {profilePhotoPreview ? (
                                <img src={profilePhotoPreview} alt="Profile" className="w-32 h-32 rounded-full object-cover mb-4" />
                            ) : (
                                <div className="w-32 h-32 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center mb-4"><UserCircleIcon className="w-20 h-20 text-gray-400 dark:text-gray-500" /></div>
                            )}
                            <label htmlFor="photo-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600">
                                Change Photo
                                <input id="photo-upload" name="photo" type="file" className="sr-only" onChange={handleProfilePhotoChange} accept="image/*" />
                            </label>
                        </div>
                        <div className="md:col-span-2 space-y-4">
                            <div>
                                <label className="text-gray-700 dark:text-gray-300">Full Name</label>
                                <input type="text" name="fullName" value={profileData.fullName} onChange={handleProfileFormChange} className="w-full mt-1 p-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded" />
                            </div>
                             <div>
                                <EmailInput label="Email" name="email" value={profileData.email} onChange={(val) => setProfileData(prev => ({...prev, email: val}))} />
                            </div>
                             <div>
                                <PhoneInput label="Phone" name="phone" value={profileData.phone} onChange={(val) => setProfileData(prev => ({...prev, phone: val}))} />
                            </div>
                            <div className="flex justify-end">
                                <button onClick={() => onUpdateStaff(currentStaff.id, profileData)} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors">Save Changes</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'company' && canManageCompany && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4">Company Profile</h2>
                    <div className="space-y-4">
                        <div>
                            <label className="text-gray-700 dark:text-gray-300">Company Name</label>
                            <input type="text" value={companyData.name} onChange={e => setCompanyData({name: e.target.value})} className="w-full mt-1 p-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded" />
                        </div>
                        <div>
                            <label className="text-gray-700 dark:text-gray-300">Company Logo</label>
                            <div className="mt-1 flex items-center gap-4">
                                {companyLogoPreview && <img src={companyLogoPreview} alt="Logo" className="h-16 w-auto bg-gray-100 p-1 border rounded" />}
                                <label htmlFor="logo-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600">
                                    Upload Logo
                                    <input id="logo-upload" name="logo" type="file" className="sr-only" onChange={handleCompanyLogoChange} accept="image/*" />
                                </label>
                            </div>
                        </div>
                         <div className="flex justify-end">
                            <button onClick={handleSaveCompanySettings} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors">Save Company Settings</button>
                        </div>
                    </div>
