};

// --- Role Permissions ---
export const fetchRolePermissions = () => fetchCollection<RolePermission>(PERMISSIONS_COL);
export const persistRolePermission = async (permission: RolePermission) => {
    // Composite ID for uniqueness
    const id = `${permission.roleId}_${permission.moduleId}`;
    await setDoc(doc(db, PERMISSIONS_COL, id), sanitizeData(permission));
};
export const removeRolePermission = async (roleId: string, moduleId: string) => {
    await deleteDoc(doc(db, PERMISSIONS_COL, `${roleId}_${moduleId}`));
};

// --- Amendments ---
export const fetchAmendments = () => fetchCollection<AmendmentRequest>(AMENDMENTS_COL);
