// Legacy Persist (Forward compatibility wrapper)
export const persistRolePermission = async (permission: RolePermission) => {
    const roleDocRef = doc(db, PERMISSIONS_COL, permission.roleId);
    await setDoc(roleDocRef, {
        modules: {
            [permission.moduleId]: permission.permissions
        }
    }, { merge: true });
};

export const removeRolePermission = async (roleId: string, moduleId: string) => {
    // Note: Firestore doesn't easily support deleting a map key via updateDoc without FieldValue.delete()
    // For now, we assume permissions are rarely deleted, just toggled to false.
    console.warn("Deleting individual module permissions is not fully supported in this schema version. Consider setting all flags to false.");
};

// --- Amendments ---
export const fetchAmendments = () => fetchCollection<AmendmentRequest>(AMENDMENTS_COL);
export const persistAmendment = async (amendment: AmendmentRequest) => {
    await setDoc(doc(db, AMENDMENTS_COL, String(amendment.id)), sanitizeData(amendment));
};

// --- Company Settings ---
export const fetchCompanySettings = async (): Promise<CompanySettings> => {
    try {
        const docRef = doc(db, SETTINGS_COL, 'main');
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
            return docSnap.data() as CompanySettings;
        } else {
            return COMPANY_SETTINGS;
        }
    } catch (error) {
        console.error("Error fetching company settings:", error);
        return COMPANY_SETTINGS;
    }
};
export const persistCompanySettings = async (settings: CompanySettings) => {
    await setDoc(doc(db, SETTINGS_COL, 'main'), sanitizeData(settings));
};

// --- Seeding ---
export const seedDatabase = async () => {
    const batch = writeBatch(db);

    // Check if main data needs seeding
    const propertiesSnap = await getDocs(collection(db, PROPERTIES_COL));
    const shouldSeedData = propertiesSnap.empty;

    if (shouldSeedData) {
        console.log("Seeding main app data...");
        PROPERTIES.forEach(p => batch.set(doc(db, PROPERTIES_COL, String(p.id)), sanitizeData(p)));
        INVOICES.forEach(i => batch.set(doc(db, INVOICES_COL, String(i.id)), sanitizeData(i)));
        PROMOTIONS.forEach(p => batch.set(doc(db, PROMOTIONS_COL, String(p.id)), sanitizeData(p)));
        ROLES.forEach(r => batch.set(doc(db, ROLES_COL, String(r.id)), sanitizeData(r)));
        AMENDMENT_REQUESTS.forEach(a => batch.set(doc(db, AMENDMENTS_COL, String(a.id)), sanitizeData(a)));
        batch.set(doc(db, SETTINGS_COL, 'main'), sanitizeData(COMPANY_SETTINGS));
    }

    // Check Permissions specifically (Force seed if CEO permissions are missing)
    const ceoPermissionsRef = doc(db, PERMISSIONS_COL, 'CEO');
    const ceoPermissionsSnap = await getDoc(ceoPermissionsRef);

    const shouldSeedPermissions = !ceoPermissionsSnap.exists();

    if (shouldSeedPermissions) {
        console.log("Seeding permissions...");
        const permissionsByRole: Record<string, any> = {};
        ROLE_PERMISSIONS.forEach(rp => {
            if (!permissionsByRole[rp.roleId]) permissionsByRole[rp.roleId] = {};
            permissionsByRole[rp.roleId][rp.moduleId] = rp.permissions;
        });

        Object.entries(permissionsByRole).forEach(([roleId, modules]) => {
            batch.set(doc(db, PERMISSIONS_COL, roleId), { modules });
        });
    }

    if (shouldSeedData || shouldSeedPermissions) {
        await batch.commit();
        console.log("Database seeding complete.");
    } else {
        console.log("Database already seeded and up-to-date.");
    }
};

import React, { useState, useMemo } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import LeadsManagementPage from './pages/LeadsManagementPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import PlaceholderPage from './pages/PlaceholderPage';
import MappingsPage from './pages/MappingsPage';

import { DataProvider, useData } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { GENERATED_REPORTS } from './data/mockData';
import { Client, PermissionSet } from './types';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

const queryClient = new QueryClient();

const AppContent: React.FC = () => {
    const { 
        clients, properties, invoices, staff, leads, promotions, 
        companySettings, activityLogs, roles, amendments, rolePermissions,
        saveClient, deleteClient, saveProperty, saveInvoice, 
        saveLead, deleteLead, savePromotion, deletePromotion,
        updateStaff, setStaff, setRoles, setCompanySettings,
        addActivityLog, setAmendmentList
    } = useData();

    const { currentStaff, login, logout, isAuthenticated } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        setActivePage(page);
        setPageContext(context);
    };

    // Calculate Permissions based on the User's Role ID from the Context.
    // Crucially, this Hook is called BEFORE the early return for login, preventing #310 errors.
    const staffPermissions = useMemo(() => {
        if (!currentStaff) return {};
        const userPermissions: { [key: string]: PermissionSet } = {};

        // Find all permissions associated with the current staff's role ID
        const rolePerms = rolePermissions.filter(rp => rp.roleId === currentStaff.roleId);

        rolePerms.forEach(rp => {
            userPermissions[rp.moduleId] = rp.permissions;
        });

        // Fallback/Default if no permissions found
        if (Object.keys(userPermissions).length === 0) {
             userPermissions['Dashboard'] = { view: true, create: false, edit: false, delete: false, approve: false };
        }

        return userPermissions;
    }, [currentStaff, rolePermissions]);

    if (!isAuthenticated || !currentStaff) {
        return <LoginPage onLogin={login} companySettings={companySettings} />;
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard':
                return <Dashboard />;
            case 'Clients':
                return <ClientsPage 
                    clients={clients} 
                    onSaveClient={saveClient}
                    onDeleteClient={deleteClient}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]}
                    onClientSelect={(client) => handleSetPage('Client Details', client)} 
                    setActivePage={handleSetPage}
                    setClientForInvoice={setClientForInvoice}
                    invoices={invoices}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Client Details':
                return <ClientDetailPage 
                    client={pageContext} 
                    properties={properties}
                    onBack={() => handleSetPage('Clients')}
                    currentStaff={currentStaff}
                    roles={roles}
                    setActivePage={handleSetPage}
                />;
            case 'Account Management':
                 return <AccountManagementPage 
                    clients={clients}
                    onSaveClient={saveClient}
                    onClientSelect={(client) => handleSetPage('Client Details', client)}
                    invoices={invoices}
                    onSaveInvoice={saveInvoice}
                    clientForInvoice={clientForInvoice}
                    setClientForInvoice={setClientForInvoice}
                    receiptPattern={null} 
                    setReceiptPattern={() => {}}
                    setReceiptAlerts={() => {}}
                    currentStaff={currentStaff}
                 />;
            case 'Settings':
                return <SettingsPage 
                    currentStaff={currentStaff} 
                    staff={staff}
                    roles={roles}
                    setRoles={setRoles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    companySettings={companySettings}
                    setCompanySettings={setCompanySettings}
                    onUpdateStaff={updateStaff}
                />;
            case 'CEO Hub':
                 return <CEOHub
                    setActivePage={handleSetPage}
                    properties={properties}
                    clients={clients}
                    invoices={invoices}
                    staff={staff}
                    roles={roles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    addActivityLog={handleAddActivityLog}
                />;
             case 'Properties':
                return <PropertiesPage properties={properties} currentStaff={currentStaff} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
             case 'New Land Acquisition':
                return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
             case 'Promotions':
                return <PromotionsPage 
                    promotions={promotions} 
                    onSavePromotion={savePromotion}
                    onDeletePromotion={deletePromotion}
                    properties={properties} 
                    showForm={true} 
                    onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} 
                />;
            case 'Administration':
                return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Lead Management & Follow-Up':
                return <LeadsManagementPage 
                    leads={leads} 
                    onSaveLead={saveLead}
                    onDeleteLead={deleteLead}
                    clients={clients} 
                    onSaveClient={saveClient}
                    staffList={staff} 
                    roles={roles}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }]} 
                    currentStaff={currentStaff} 
                    addActivityLog={handleAddActivityLog} 
                />;
            case 'Human Resources':
                return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} setStaff={setStaff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts':
                return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot':
                return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation':
                return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Mappings':
                return <MappingsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Amendment Form':
                return (
                    <AmendmentFormPage 
                        client={pageContext} 
                        onBack={() => handleSetPage('Client Details', pageContext)} 
                        onSave={async (data, updatedClient) => { 
                            setAmendmentList(prev => [data, ...prev]); 
                            await saveClient(updatedClient);
                            handleAddActivityLog('Update', `Processed amendment request for client: ${updatedClient.name}`);
                            alert('Amendment processed and client record updated successfully!'); 
                            handleSetPage('Client Details', updatedClient);
                        }} 
                        currentStaff={currentStaff} 
                    />
                );
            case 'Analytics & Reports':
                return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports':
                return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity':
                return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Mailing':
            case 'Leave':
            case 'Knowledge Base':
            case 'Event':
            case 'Announcement':
            case 'Support':
                return <PlaceholderPage title={activePage} onBack={() => handleSetPage('Dashboard')} />;
            default:
                return <div>Page not found</div>;
        }
    };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff} 
            onLogout={logout}
            staffPermissions={staffPermissions}
            companySettings={companySettings}
        >
            {renderPage()}
        </Layout>
    );
};

const App: React.FC = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <DataProvider>
                    <AuthProvider>
                        <AppContent />
                    </AuthProvider>
                </DataProvider>
            </ThemeProvider>
        </QueryClientProvider>
    );
};

export default App;

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- Helper Functions ---

    // Check if the user is authenticated
    function isAuthenticated() {
      return request.auth != null;
    }

    // Fetch the current user's profile document
    function getUserData() {
      return get(/databases/$(database)/documents/user/$(request.auth.uid)).data;
    }

    // Get the Role ID (e.g., 'CEO', 'Sales Representative') from the user profile
    function getUserRole() {
      return getUserData().roleId;
    }

    // Fetch the permissions map for the user's role
    function getRolePermissions() {
      return get(/databases/$(database)/documents/role_permissions/$(getUserRole())).data.modules;
    }

    // Generic Permission Check
    // Verifies if the user's role has the specific 'action' (view, create, edit, delete) 
    // enabled for the given 'module'.
    function can(module, action) {
      // 1. Get User Role
      let role = getUserRole();

      // 2. Fetch Permissions for that Role
      // Note: This costs 1 extra read per request.
      let modules = get(/databases/$(database)/documents/role_permissions/$(role)).data.modules;

      // 3. Check if permission exists and is true
      // We use .get() to safely access nested keys which might be missing in older data
      return modules[module][action] == true;
    }

    // Fail-safe for CEO to prevent lockout if permissions are messed up
    function isCEO() {
      return getUserRole() == 'CEO';
    }

    // --- Collection Rules ---

    // 1. Users (Staff Profiles)
    // Read: All authenticated users (for lists, assignments)
    // Create/Delete: Restricted to Settings managers or CEO
    // Update: Self or Settings managers
    match /user/{userId} {
      allow read: if isAuthenticated();
      allow create: if isAuthenticated() && (can('Settings', 'create') || isCEO());
      allow update: if isAuthenticated() && (request.auth.uid == userId || can('Settings', 'edit') || isCEO());
      allow delete: if isAuthenticated() && (can('Settings', 'delete') || isCEO());
    }

    // 2. Roles & Permissions (Core Security Data)
    match /roles/{roleId} {
      allow read: if isAuthenticated();
      allow write: if isAuthenticated() && (can('Settings', 'edit') || isCEO());
    }

    match /role_permissions/{roleId} {
      allow read: if isAuthenticated();
      allow write: if isAuthenticated() && (can('Settings', 'edit') || isCEO());
    }

    // 3. Clients Module
    match /clients/{clientId} {
      allow read: if isAuthenticated() && can('Clients', 'view');
      allow create: if isAuthenticated() && can('Clients', 'create');
      allow update: if isAuthenticated() && can('Clients', 'edit');
      allow delete: if isAuthenticated() && can('Clients', 'delete');
    }

    // 4. Leads Management Module
    match /leads/{leadId} {
      allow read: if isAuthenticated() && can('Leads Management', 'view');
      allow create: if isAuthenticated() && can('Leads Management', 'create');
      allow update: if isAuthenticated() && can('Leads Management', 'edit');
      allow delete: if isAuthenticated() && can('Leads Management', 'delete');
    }

    // 5. Properties (Managed via CEO Hub)
    match /properties/{propertyId} {
      // Read allowed for all auth users (used in dropdowns everywhere)
      allow read: if isAuthenticated();
      allow create: if isAuthenticated() && can('CEO Hub', 'create');
      allow update: if isAuthenticated() && can('CEO Hub', 'edit');
      allow delete: if isAuthenticated() && can('CEO Hub', 'delete');
    }

    // 6. Invoices (Account Management)
    match /invoices/{invoiceId} {
      allow read: if isAuthenticated() && (can('Account Management', 'view') || can('Clients', 'view'));
      allow create: if isAuthenticated() && can('Account Management', 'create');
      allow update: if isAuthenticated() && can('Account Management', 'edit');
      allow delete: if isAuthenticated() && can('Account Management', 'delete');
    }

    // 7. Promotions
    match /promotions/{promoId} {
      allow read: if isAuthenticated();
      allow create: if isAuthenticated() && can('Promotions', 'create');
      allow update: if isAuthenticated() && can('Promotions', 'edit');
      allow delete: if isAuthenticated() && can('Promotions', 'delete');
    }

    // 8. Company Settings
    match /settings/{docId} {
      allow read: if isAuthenticated();
      allow write: if isAuthenticated() && can('Settings', 'edit');
    }

    // 9. Activity Logs
    match /activity_logs/{logId} {
      // Viewable by Admins/CEO
      allow read: if isAuthenticated() && (can('Settings', 'view') || can('CEO Hub', 'view'));
      // Append-only: Any auth user can create a log (system audit trail)
      allow create: if isAuthenticated();
      allow update, delete: if false;
    }

    // 10. Amendments (Linked to Clients)
    match /amendments/{docId} {
      allow read: if isAuthenticated() && can('Clients', 'view');
      allow create: if isAuthenticated() && can('Clients', 'edit');
      allow update: if isAuthenticated() && can('Clients', 'approve'); 
      allow delete: if isAuthenticated() && can('Clients', 'delete');
    }
  }
}

import { db } from './firebase';
import { collection, getDocs, doc, setDoc, deleteDoc, getDoc, writeBatch, onSnapshot, updateDoc } from 'firebase/firestore';
import { 
    Client, Lead, Staff, Property, Invoice, Promotion, 
    CompanySettings, ActivityLog, Role, AmendmentRequest, RolePermission, AppModuleName, PermissionSet 
} from '../types';
import { 
    PROPERTIES, INVOICES, PROMOTIONS, COMPANY_SETTINGS, 
    ACTIVITY_LOGS, ROLES, ROLE_PERMISSIONS, AMENDMENT_REQUESTS, APP_MODULES 
} from '../data/mockData';

const CLIENTS_COL = 'clients';
const LEADS_COL = 'leads';
const USERS_COL = 'user';
const PROPERTIES_COL = 'properties';
const INVOICES_COL = 'invoices';
const PROMOTIONS_COL = 'promotions';
const SETTINGS_COL = 'settings';
const LOGS_COL = 'activity_logs';
const ROLES_COL = 'roles';
const PERMISSIONS_COL = 'role_permissions';
const AMENDMENTS_COL = 'amendments';

// Helper to remove undefined fields
const sanitizeData = <T>(data: T): T => {
  return JSON.parse(JSON.stringify(data));
};

// --- Generic Fetcher ---
const fetchCollection = async <T>(colName: string): Promise<T[]> => {
    try {
        const snapshot = await getDocs(collection(db, colName));
        return snapshot.docs.map(doc => doc.data() as T);
    } catch (error) {
        console.error(`Error fetching ${colName}:`, error);
        return [];
    }
};

// --- Clients ---
export const fetchClients = () => fetchCollection<Client>(CLIENTS_COL);
export const persistClient = async (client: Client) => {
    await setDoc(doc(db, CLIENTS_COL, String(client.id)), sanitizeData(client));
};
export const removeClient = async (id: number) => {
    await deleteDoc(doc(db, CLIENTS_COL, String(id)));
};

// --- Leads ---
export const fetchLeads = () => fetchCollection<Lead>(LEADS_COL);
export const persistLead = async (lead: Lead) => {
    await setDoc(doc(db, LEADS_COL, String(lead.id)), sanitizeData(lead));
};
export const removeLead = async (id: number) => {
    await deleteDoc(doc(db, LEADS_COL, String(id)));
};

// --- Staff ---
export const fetchStaff = () => fetchCollection<Staff>(USERS_COL);
export const persistStaff = async (staff: Staff) => {
    const { password, ...staffDataWithoutPassword } = staff;
    await setDoc(doc(db, USERS_COL, String(staff.id)), sanitizeData(staffDataWithoutPassword));
};
export const removeStaff = async (id: string) => {
    await deleteDoc(doc(db, USERS_COL, id));
};

// --- Properties ---
export const fetchProperties = () => fetchCollection<Property>(PROPERTIES_COL);
export const persistProperty = async (property: Property) => {
    await setDoc(doc(db, PROPERTIES_COL, String(property.id)), sanitizeData(property));
};
export const removeProperty = async (id: number) => {
    await deleteDoc(doc(db, PROPERTIES_COL, String(id)));
};

// --- Invoices ---
export const fetchInvoices = () => fetchCollection<Invoice>(INVOICES_COL);
export const persistInvoice = async (invoice: Invoice) => {
    await setDoc(doc(db, INVOICES_COL, String(invoice.id)), sanitizeData(invoice));
};
export const removeInvoice = async (id: string) => {
    await deleteDoc(doc(db, INVOICES_COL, id));
};

// --- Promotions ---
export const fetchPromotions = () => fetchCollection<Promotion>(PROMOTIONS_COL);
export const persistPromotion = async (promotion: Promotion) => {
    await setDoc(doc(db, PROMOTIONS_COL, String(promotion.id)), sanitizeData(promotion));
};
export const removePromotion = async (id: number) => {
    await deleteDoc(doc(db, PROMOTIONS_COL, String(id)));
};

// --- Activity Logs ---
export const fetchActivityLogs = () => fetchCollection<ActivityLog>(LOGS_COL);
export const persistActivityLog = async (log: ActivityLog) => {
    await setDoc(doc(db, LOGS_COL, String(log.id)), sanitizeData(log));
};

// --- Roles ---
export const fetchRoles = () => fetchCollection<Role>(ROLES_COL);
export const persistRole = async (role: Role) => {
    await setDoc(doc(db, ROLES_COL, String(role.id)), sanitizeData(role));
};
export const removeRole = async (id: string) => {
    await deleteDoc(doc(db, ROLES_COL, id));
};

// --- Role Permissions (REAL-TIME & STRUCTURED) ---

// Listen to the entire collection and transform Document-per-Role into flat RolePermission[]
export const listenToRolePermissions = (onUpdate: (perms: RolePermission[]) => void) => {
    return onSnapshot(collection(db, PERMISSIONS_COL), (snapshot) => {
        const allPerms: RolePermission[] = [];
        snapshot.docs.forEach(doc => {
            const roleId = doc.id;
            const data = doc.data();

            if (data.modules) {
                Object.entries(data.modules).forEach(([moduleId, permissions]) => {
                    allPerms.push({
                        roleId,
                        moduleId: moduleId as AppModuleName,
                        permissions: permissions as PermissionSet
                    });
                });
            }
        });
        onUpdate(allPerms);
    }, (error) => {
        console.error("Error listening to role permissions:", error);
        // If permission denied or other error, return empty list to avoid breaking UI
        onUpdate([]);
    });
};

// Update a single permission bit (Granular Update)
export const updateRolePermissionInDb = async (roleId: string, moduleId: string, permission: string, value: boolean) => {
    const roleDocRef = doc(db, PERMISSIONS_COL, roleId);
    // Use dot notation to update nested map fields without overwriting the whole document
    await updateDoc(roleDocRef, {
        [`modules.${moduleId}.${permission}`]: value
    });
};

// Initialize permissions for a new role
export const initRolePermissions = async (roleId: string) => {
    const roleDocRef = doc(db, PERMISSIONS_COL, roleId);
    const defaultPermissions: Record<string, PermissionSet> = {};

    APP_MODULES.forEach(module => {
        defaultPermissions[module.id] = { view: false, create: false, edit: false, delete: false, approve: false };
    });

    await setDoc(roleDocRef, { modules: defaultPermissions }, { merge: true });
};

// Legacy Fetch (kept for compatibility, though Listener is preferred)
export const fetchRolePermissions = async () => {
    const snapshot = await getDocs(collection(db, PERMISSIONS_COL));
    const allPerms: RolePermission[] = [];
    snapshot.docs.forEach(doc => {
        const roleId = doc.id;
        const data = doc.data();
        if (data.modules) {
            Object.entries(data.modules).forEach(([moduleId, permissions]) => {
                allPerms.push({
                    roleId,
                    moduleId: moduleId as AppModuleName,
                    permissions: permissions as PermissionSet
                });
            });
        }
    });
    return allPerms;
};

// Legacy Persist (Forward compatibility wrapper)
export const persistRolePermission = async (permission: RolePermission) => {
    const roleDocRef = doc(db, PERMISSIONS_COL, permission.roleId);
    await setDoc(roleDocRef, {
        modules: {
            [permission.moduleId]: permission.permissions
        }
    }, { merge: true });
};

export const removeRolePermission = async (roleId: string, moduleId: string) => {
    // Note: Firestore doesn't easily support deleting a map key via updateDoc without FieldValue.delete()
    // For now, we assume permissions are rarely deleted, just toggled to false.
    console.warn("Deleting individual module permissions is not fully supported in this schema version. Consider setting all flags to false.");
};

// --- Amendments ---
export const fetchAmendments = () => fetchCollection<AmendmentRequest>(AMENDMENTS_COL);
export const persistAmendment = async (amendment: AmendmentRequest) => {
    await setDoc(doc(db, AMENDMENTS_COL, String(amendment.id)), sanitizeData(amendment));
};

// --- Company Settings ---
export const fetchCompanySettings = async (): Promise<CompanySettings> => {
    try {
        const docRef = doc(db, SETTINGS_COL, 'main');
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
            return docSnap.data() as CompanySettings;
        } else {
            return COMPANY_SETTINGS;
        }
    } catch (error) {
        console.error("Error fetching company settings:", error);
        return COMPANY_SETTINGS;
    }
};
export const persistCompanySettings = async (settings: CompanySettings) => {
    await setDoc(doc(db, SETTINGS_COL, 'main'), sanitizeData(settings));
};

// --- Seeding ---
export const seedDatabase = async () => {
    const batch = writeBatch(db);

    // Check if main data needs seeding
    const propertiesSnap = await getDocs(collection(db, PROPERTIES_COL));
    const shouldSeedData = propertiesSnap.empty;

    if (shouldSeedData) {
        console.log("Seeding main app data...");
        PROPERTIES.forEach(p => batch.set(doc(db, PROPERTIES_COL, String(p.id)), sanitizeData(p)));
        INVOICES.forEach(i => batch.set(doc(db, INVOICES_COL, String(i.id)), sanitizeData(i)));
        PROMOTIONS.forEach(p => batch.set(doc(db, PROMOTIONS_COL, String(p.id)), sanitizeData(p)));
        ROLES.forEach(r => batch.set(doc(db, ROLES_COL, String(r.id)), sanitizeData(r)));
        AMENDMENT_REQUESTS.forEach(a => batch.set(doc(db, AMENDMENTS_COL, String(a.id)), sanitizeData(a)));
        batch.set(doc(db, SETTINGS_COL, 'main'), sanitizeData(COMPANY_SETTINGS));
    }

    // Check Permissions specifically (Force seed if CEO permissions are missing)
    const ceoPermissionsRef = doc(db, PERMISSIONS_COL, 'CEO');
    // Using simple getDoc here might fail if rules are already applied and we are not auth'd as admin
    // However, seedDatabase is usually called when App inits with an auth'd user.
    try {
        const ceoPermissionsSnap = await getDoc(ceoPermissionsRef);
        const shouldSeedPermissions = !ceoPermissionsSnap.exists();

        if (shouldSeedPermissions) {
            console.log("Seeding permissions...");
            const permissionsByRole: Record<string, any> = {};
            ROLE_PERMISSIONS.forEach(rp => {
                if (!permissionsByRole[rp.roleId]) permissionsByRole[rp.roleId] = {};
                permissionsByRole[rp.roleId][rp.moduleId] = rp.permissions;
            });

            Object.entries(permissionsByRole).forEach(([roleId, modules]) => {
                batch.set(doc(db, PERMISSIONS_COL, roleId), { modules });
            });
        }

        if (shouldSeedData || shouldSeedPermissions) {
            await batch.commit();
            console.log("Database seeding complete.");
        } else {
            console.log("Database already seeded and up-to-date.");
        }
    } catch (e) {
        console.error("Seeding check failed (possibly permission issue):", e);
    }
};

import React, { useState } from 'react';
import { FaimLogoIcon, EyeIcon, EyeSlashIcon } from '../components/icons/DummyIcons';
