    const { data: properties = [], isLoading } = useQuery({ queryKey: ['properties'], queryFn: dbService.fetchProperties });

    const saveProperty = useMutation({
        mutationFn: dbService.persistProperty,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['properties'] })
