// --- Activity Logs ---
export const useActivityLogs = () => {
    const queryClient = useQueryClient();
    const { data: activityLogs = [] } = useQuery({ queryKey: ['logs'], queryFn: dbService.fetchActivityLogs });

    const addLog = useMutation({
        mutationFn: async ({ type, description, userId }: { type: ActivityLog['type']; description: string; userId: string }) => {
