import React, { createContext, useContext, useEffect, useState } from 'react';
import * as dbService from '../services/dbService';
import { RolePermission, AppModuleName } from '../types';

interface PermissionsContextType {
    rolePermissions: RolePermission[];
    updateRolePermission: (roleId: string, moduleId: AppModuleName, permission: string, value: boolean) => Promise<void>;
    initRolePermissions: (roleId: string) => Promise<void>;
}

const DataContext = createContext<PermissionsContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [rolePermissions, setRolePermissionsState] = useState<RolePermission[]>([]);

    useEffect(() => {
        // Subscribe to real-time changes in role_permissions collection
        const unsubscribe = dbService.listenToRolePermissions((perms) => {
            setRolePermissionsState(perms);
        });
        return () => unsubscribe();
    }, []);

    const updateRolePermission = async (roleId: string, moduleId: AppModuleName, permission: string, value: boolean) => {
        await dbService.updateRolePermissionInDb(roleId, moduleId, permission, value);
    };

    const initRolePermissions = async (roleId: string) => {
        await dbService.initRolePermissions(roleId);
    }

    return (
        <DataContext.Provider value={{
            rolePermissions,
            updateRolePermission,
            initRolePermissions,
        }}>
            {children}
        </DataContext.Provider>
    );
};

// Keeping the name 'useData' momentarily compatible but ideally should be usePermissions
// To avoid breaking every single file immediately, we can expose it as usePermissions 
// and keep a deprecated useData if we wanted, but we are refactoring App.tsx so let's be clean.
export const usePermissions = () => {
    const context = useContext(DataContext);
    if (context === undefined) {
        throw new Error('usePermissions must be used within a DataProvider (PermissionsProvider)');
    }
    return context;
};

/**
 * @deprecated Use specific hooks (useClients, useStaff, etc.) or usePermissions instead.
 */
export const useData = () => {
     // This fallback creates a bridge during refactoring if some component is missed.
     // However, without the data in context, this will return undefined or partial data if we tried to mock it.
     // We will strictly update consumers.
     return usePermissions(); 
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Staff } from '../types';
import { useActivityLogs } from '../hooks/useAppData';
import { auth, db } from '../services/firebase';
// @ts-ignore
import { signInWithEmailAndPassword, signOut, onAuthStateChanged } from 'firebase/auth';
import { collection, query, where, getDocs, limit, setDoc, doc } from 'firebase/firestore';
import { signup } from '../services/authService';

interface AuthContextType {
    currentStaff: Staff | null;
    login: (email: string, password: string) => Promise<{ success: boolean; message: string }>;
    register: (email: string, password: string) => Promise<{ success: boolean; message: string }>;
    logout: () => Promise<void>;
    isAuthenticated: boolean;
    loading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const ROLE_ID_MAP: Record<number, string> = {
    1: 'CEO',
    2: 'Administrator',
    3: 'Front Desk Executive',
    4: 'Chief Accountant',
    5: 'Head of Sales',
    6: 'Sales Representative'
};

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { addActivityLog } = useActivityLogs();

    const [currentStaff, setCurrentStaff] = useState<Staff | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (firebaseUser: any) => {
            if (firebaseUser && firebaseUser.email) {
                try {
                    // Query Firestore 'user' collection directly
                    const q = query(collection(db, "user"), where("email", "==", firebaseUser.email));
                    const querySnapshot = await getDocs(q);

                    if (!querySnapshot.empty) {
                        const userDoc = querySnapshot.docs[0];
                        const userData = userDoc.data();

                        let roleId = userData.roleId || 'Staff';
                        if (typeof roleId === 'number' && ROLE_ID_MAP[roleId]) {
                            roleId = ROLE_ID_MAP[roleId];
                        }

                        const matchedStaff: Staff = {
                            id: String(userData.id || firebaseUser.uid),
                            fullName: userData.fullName || userData.name || 'User',
                            initials: userData.initials || 'U',
                            email: userData.email,
                            phone: userData.phone,
                            roleId: roleId, 
                            status: userData.status || 'Active',
                            lastLogin: new Date().toISOString(),
                            photo: userData.photo,
                        };

                        setCurrentStaff(matchedStaff);
                    } else {
                        // Bootstrap Logic
                        const allUsersQuery = query(collection(db, "user"), limit(1));
                        const allUsersSnapshot = await getDocs(allUsersQuery);

                        if (allUsersSnapshot.empty) {
                            console.log("No users found. Bootstrapping first user as CEO.");
                            const newStaffId = firebaseUser.uid;
                            const newStaff: Staff = {
                                id: newStaffId,
                                fullName: firebaseUser.displayName || 'Admin User',
                                initials: (firebaseUser.displayName || 'AD').substring(0, 2).toUpperCase() || 'AD',
                                email: firebaseUser.email,
                                phone: '',
                                roleId: 'CEO',
                                status: 'Active',
                                lastLogin: new Date().toISOString(),
                                ...(firebaseUser.photoURL ? { photo: firebaseUser.photoURL } : {})
                            };

                            await setDoc(doc(db, "user", newStaffId), newStaff);
                            setCurrentStaff(newStaff);
                            addActivityLog('Create', `Bootstrapped first user ${newStaff.fullName} in Firestore.`, newStaffId);
                        } else {
                            console.warn("User logged in via Firebase but no matching record found.");
                            await signOut(auth);
                            setCurrentStaff(null);
                        }
                    }
                } catch (error) {
                    console.error("Error verifying user against Firestore:", error);
                    setCurrentStaff(null);
                }
            } else {
                setCurrentStaff(null);
            }
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    const login = async (email: string, password: string) => {
        try {
            await signInWithEmailAndPassword(auth, email, password);
            return { success: true, message: 'Login successful' };
        } catch (error: any) {
            console.error("Firebase login error:", error);
            let message = 'Invalid credentials';
            if (error.code === 'auth/user-not-found' || error.code === 'auth/invalid-credential') message = 'Invalid email or password';
            return { success: false, message };
        }
    };

    const register = async (email: string, password: string) => {
        try {
            await signup(email, password);
            return { success: true, message: 'Registration successful' };
        } catch (error: any) {
            console.error("Firebase registration error:", error);
            let message = 'Registration failed';
            if (error.code === 'auth/email-already-in-use') message = 'Email already in use';
            if (error.code === 'auth/weak-password') message = 'Password should be at least 6 characters';
            return { success: false, message };
        }
    };

    const logout = async () => {
        if (currentStaff) {
            addActivityLog('Logout', `User ${currentStaff.fullName} logged out.`, currentStaff.id);
        }
        await signOut(auth);
        setCurrentStaff(null);
    };

    return (
        <AuthContext.Provider value={{
            currentStaff,
            login,
            register,
            logout,
            isAuthenticated: !!currentStaff,
            loading
        }}>
            {!loading && children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

import React, { useState, useMemo } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import LeadsManagementPage from './pages/LeadsManagementPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import PlaceholderPage from './pages/PlaceholderPage';
import MappingsPage from './pages/MappingsPage';

import { DataProvider, usePermissions } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { GENERATED_REPORTS } from './data/mockData';
import { Client, PermissionSet } from './types';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { 
    useClients, useProperties, useInvoices, useStaff, useLeads, 
    usePromotions, useActivityLogs, useRoles, useAmendments, useCompanySettings 
} from './hooks/useAppData';

const queryClient = new QueryClient();

const AppContent: React.FC = () => {
    // --- Data Hooks ---
    const { clients, saveClient, deleteClient } = useClients();
    const { properties, saveProperty } = useProperties();
    const { invoices, saveInvoice } = useInvoices();
    const { staff, updateStaff, setStaff } = useStaff(); // setStaff exposed for legacy prop compat if needed, but preferably used internally
    const { leads, saveLead, deleteLead } = useLeads();
    const { promotions, savePromotion, deletePromotion } = usePromotions();
    const { activityLogs, addActivityLog } = useActivityLogs();
    const { roles, setRoles } = useRoles();
    const { amendments, setAmendmentList } = useAmendments();
    const { companySettings, setCompanySettings } = useCompanySettings();
    const { rolePermissions } = usePermissions();

    const { currentStaff, login, logout, isAuthenticated } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        setActivePage(page);
        setPageContext(context);
    };

    // Calculate Permissions based on the User's Role ID from the Context.
    const staffPermissions = useMemo(() => {
        if (!currentStaff) return {};
        const userPermissions: { [key: string]: PermissionSet } = {};

        // Find all permissions associated with the current staff's role ID
        const rolePerms = rolePermissions.filter(rp => rp.roleId === currentStaff.roleId);

        rolePerms.forEach(rp => {
            userPermissions[rp.moduleId] = rp.permissions;
        });

        // Fallback/Default if no permissions found
        if (Object.keys(userPermissions).length === 0) {
             userPermissions['Dashboard'] = { view: true, create: false, edit: false, delete: false, approve: false };
        }

        return userPermissions;
    }, [currentStaff, rolePermissions]);

    if (!isAuthenticated || !currentStaff) {
        return <LoginPage onLogin={login} companySettings={companySettings} />;
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard':
                return <Dashboard />;
            case 'Clients':
                return <ClientsPage 
                    clients={clients} 
                    onSaveClient={saveClient}
                    onDeleteClient={deleteClient}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]}
                    onClientSelect={(client) => handleSetPage('Client Details', client)} 
                    setActivePage={handleSetPage}
                    setClientForInvoice={setClientForInvoice}
                    invoices={invoices}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Client Details':
                return <ClientDetailPage 
                    client={pageContext} 
                    properties={properties}
                    onBack={() => handleSetPage('Clients')}
                    currentStaff={currentStaff}
                    roles={roles}
                    setActivePage={handleSetPage}
                />;
            case 'Account Management':
                 return <AccountManagementPage 
                    clients={clients}
                    onSaveClient={saveClient}
                    onClientSelect={(client) => handleSetPage('Client Details', client)}
                    invoices={invoices}
                    onSaveInvoice={saveInvoice}
                    clientForInvoice={clientForInvoice}
                    setClientForInvoice={setClientForInvoice}
                    receiptPattern={null} 
                    setReceiptPattern={() => {}}
                    setReceiptAlerts={() => {}}
                    currentStaff={currentStaff}
                 />;
            case 'Settings':
                return <SettingsPage 
                    currentStaff={currentStaff} 
                    staff={staff}
                    roles={roles}
                    setRoles={setRoles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    companySettings={companySettings}
                    setCompanySettings={setCompanySettings}
                    onUpdateStaff={updateStaff}
                />;
            case 'CEO Hub':
                 return <CEOHub
                    setActivePage={handleSetPage}
                    properties={properties}
                    clients={clients}
                    invoices={invoices}
                    staff={staff}
                    roles={roles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    addActivityLog={handleAddActivityLog}
                />;
             case 'Properties':
                return <PropertiesPage properties={properties} currentStaff={currentStaff} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
             case 'New Land Acquisition':
                return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
             case 'Promotions':
                return <PromotionsPage 
                    promotions={promotions} 
                    onSavePromotion={savePromotion}
                    onDeletePromotion={deletePromotion}
                    properties={properties} 
                    showForm={true} 
                    onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} 
                />;
            case 'Administration':
                return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Lead Management & Follow-Up':
                return <LeadsManagementPage 
                    leads={leads} 
                    onSaveLead={saveLead}
                    onDeleteLead={deleteLead}
                    clients={clients} 
                    onSaveClient={saveClient}
                    staffList={staff} 
                    roles={roles}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }]} 
                    currentStaff={currentStaff} 
                    addActivityLog={handleAddActivityLog} 
                />;
            case 'Human Resources':
                return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} setStaff={setStaff as any} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts':
                return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot':
                return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation':
                return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Mappings':
                return <MappingsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Amendment Form':
                return (
                    <AmendmentFormPage 
                        client={pageContext} 
                        onBack={() => handleSetPage('Client Details', pageContext)} 
                        onSave={async (data, updatedClient) => { 
                            setAmendmentList(prev => [data, ...prev]); 
                            await saveClient(updatedClient);
                            handleAddActivityLog('Update', `Processed amendment request for client: ${updatedClient.name}`);
                            alert('Amendment processed and client record updated successfully!'); 
                            handleSetPage('Client Details', updatedClient);
                        }} 
                        currentStaff={currentStaff} 
                    />
                );
            case 'Analytics & Reports':
                return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports':
                return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity':
                return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Mailing':
            case 'Leave':
            case 'Knowledge Base':
            case 'Event':
            case 'Announcement':
            case 'Support':
                return <PlaceholderPage title={activePage} onBack={() => handleSetPage('Dashboard')} />;
            default:
                return <div>Page not found</div>;
        }
    };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff} 
            onLogout={logout}
            staffPermissions={staffPermissions}
            companySettings={companySettings}
        >
            {renderPage()}
        </Layout>
    );
};

const App: React.FC = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <DataProvider>
                    <AuthProvider>
                        <AppContent />
                    </AuthProvider>
                </DataProvider>
            </ThemeProvider>
        </QueryClientProvider>
    );
};

export default App;

