// --- Clients ---
export const useClients = () => {
    const queryClient = useQueryClient();
    const { data: clients = [], isLoading } = useQuery({ queryKey: ['clients'], queryFn: dbService.fetchClients });

    const saveClient = useMutation({
        mutationFn: dbService.persistClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const deleteClient = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    return { 
        clients, 
        isLoading, 
        saveClient: saveClient.mutateAsync, 
        deleteClient: deleteClient.mutateAsync 
    };
};

