// --- Activity Logs ---
export const useActivityLogs = () => {
    const queryClient = useQueryClient();
    const { data: activityLogs = [] } = useQuery({ queryKey: ['logs'], queryFn: dbService.fetchActivityLogs });

    const addLog = useMutation({
        mutationFn: async ({ type, description, userId }: { type: ActivityLog['type']; description: string; userId: string }) => {
            const newLog: ActivityLog = {
                id: Date.now(),
                userId: userId || '0', 
                type,
                description,
                timestamp: new Date().toISOString(),
            };
            await dbService.persistActivityLog(newLog);
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['logs'] })
    });

    return { 
        activityLogs, 
        addActivityLog: (type: ActivityLog['type'], description: string, userId: string = '0') => addLog.mutate({ type, description, userId })
    };
};

// --- Roles ---
export const useRoles = () => {
    const queryClient = useQueryClient();
    const { data: roles = [] } = useQuery({ queryKey: ['roles'], queryFn: dbService.fetchRoles });

    const setRoles = useMutation({
        mutationFn: async (newRoles: Role[]) => {
            // Basic implementation: persist all. Optimized would be diffing.
            await Promise.all(newRoles.map(r => dbService.persistRole(r)));
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['roles'] })
    });

    return { 
        roles, 
        setRoles: (action: React.SetStateAction<Role[]>) => {
            // Handling functional update logic here for compatibility
            const newRoles = typeof action === 'function' ? action(roles) : action;
            setRoles.mutate(newRoles);
        }
    };
};

// --- Amendments ---
export const useAmendments = () => {
    const queryClient = useQueryClient();
    const { data: amendments = [] } = useQuery({ queryKey: ['amendments'], queryFn: dbService.fetchAmendments });

    const setAmendmentList = useMutation({
