             await Promise.all(newAmendments.map(a => dbService.persistAmendment(a)));
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['amendments'] })
    });

    return { 
        amendments, 
        setAmendmentList: (action: React.SetStateAction<AmendmentRequest[]>) => {
             const newA = typeof action === 'function' ? action(amendments) : action;
             setAmendmentList.mutate(newA);
        }
    };
};

