// --- Staff ---
export const useStaff = () => {
    const queryClient = useQueryClient();
    const { data: staff = [], isLoading } = useQuery({ queryKey: ['staff'], queryFn: dbService.fetchStaff });

    const saveStaff = useMutation({
        mutationFn: async (staffMember: Staff) => {
            let finalStaffMember = { ...staffMember };
            const exists = staff.some(s => s.id === staffMember.id);
            // Create Auth User if new
            if (!exists && staffMember.password) {
                try {
                    const user = await registerUser(staffMember.email, staffMember.password);
                    finalStaffMember.id = user.uid; 
                } catch (e) {
                    console.error("Failed to register auth user", e);
                    throw e;
                }
            }
            await dbService.persistStaff(finalStaffMember);
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    const deleteStaff = useMutation({
        mutationFn: dbService.removeStaff,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    const updateStaff = useMutation({
        mutationFn: async ({ id, details }: { id: string; details: Partial<Staff> }) => {
            const staffMember = staff.find(s => s.id === id);
            if (staffMember) {
                const updatedStaff = { ...staffMember, ...details };
                await dbService.persistStaff(updatedStaff);
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    return { 
        staff, 
        isLoading, 
        saveStaff: saveStaff.mutateAsync, 
        deleteStaff: deleteStaff.mutateAsync,
        updateStaff: (id: string, details: Partial<Staff>) => updateStaff.mutateAsync({ id, details })
    };
};

