                                    Save Client
                                </button>
                                {!editingClient && (
                                <button type="button" onClick={handleSubmitAndPay} disabled={!isFormValid} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors disabled:bg-gray-400 disabled:cursor-not-allowed">
                                    Add Payment Information
                                </button>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ClientForm;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
    ChevronDownIcon, 
    DocumentPlusIcon, 
    MagnifyingGlassIcon, 
    UploadIcon 
} from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import ClientListItem from '../components/ClientListItem';
import { Client, Milestone, Property, Invoice, ActivityLog } from '../types';
import ClientForm, { FormData } from '../components/ClientForm';
import CSVImportWizard from '../components/CSVImportWizard';
import DeleteConfirmationModal from '../components/DeleteConfirmationModal';
import { VariableSizeList as List } from 'react-window';
import AutoSizer from 'react-virtualized-auto-sizer';
import { useClients } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';

interface ClientsPageProps {
    onClientSelect: (client: Client) => void;
    // clients prop is removed as we use hook internaly for search
    clients?: Client[]; 
    onSaveClient: (client: Client) => Promise<Client>;
    onDeleteClient: (clientId: number) => Promise<void>;
    properties: Property[];
    milestones: Milestone[];
    setActivePage: (page: string) => void;
    setClientForInvoice: (client: Client) => void;
    invoices: Invoice[];
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const isClientDataComplete = (formData: FormData, existingClient?: Client | null): boolean => {
    const requiredFields: (keyof FormData)[] = [ 'surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
    for (const field of requiredFields) {
        if (!formData[field] || String(formData[field]).trim() === '') return false;
    }
    return true;
};

const ClientsPage: React.FC<ClientsPageProps> = ({ onClientSelect, onSaveClient, onDeleteClient, properties, milestones, setActivePage, setClientForInvoice, invoices, addActivityLog }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');

    // Fetch data via hook using debounced term
    const { clients, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } = useClients(debouncedSearchTerm);

    const [isClientFormOpen, setClientFormOpen] = useState(false);
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [deletedClientInfo, setDeletedClientInfo] = useState<{ name: string; timeoutId: ReturnType<typeof setTimeout> } | null>(null);
    const [clientToDelete, setClientToDelete] = useState<Client | null>(null);

    // Virtualization State
    const listRef = useRef<List>(null);
    const [expandedIds, setExpandedIds] = useState<Record<number, boolean>>({});

    // Debounce Effect
    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 500); // 500ms delay
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const toggleExpand = (id: number, index: number) => {
        setExpandedIds(prev => ({ ...prev, [id]: !prev[id] }));
        if (listRef.current) {
            listRef.current.resetAfterIndex(index);
        }
    };

    const getItemSize = (index: number) => {
        const client = clients[index];
        return expandedIds[client?.id] ? 140 : 100; // Expanded vs Collapsed height approx
    };

    useEffect(() => {
        return () => {
            if (deletedClientInfo) {
                clearTimeout(deletedClientInfo.timeoutId);
            }
        };
    }, [deletedClientInfo]);

    const handleDeleteClick = useCallback((clientId: number) => {
        const client = clients.find(c => c.id === clientId);
        if (client) {
            setClientToDelete(client);
        }
    }, [clients]);

    const confirmDeleteClient = async () => {
        if (clientToDelete) {
            await onDeleteClient(clientToDelete.id);
            addActivityLog('Delete', `Deleted client: ${clientToDelete.name}`);

            // Show toast
            const timeoutId = setTimeout(() => setDeletedClientInfo(null), 3000);
            setDeletedClientInfo({ name: clientToDelete.name, timeoutId });

            setClientToDelete(null);
        }
    };

    const createClientObject = (formData: FormData, id: number, existingClient?: Client | null): Client => {
        const fullName = `${formData.surname} ${formData.otherNames}`;
        const nameParts = fullName.split(' ');
        const initials = (nameParts[0]?.[0] || '' + nameParts[nameParts.length - 1]?.[0] || '').toUpperCase();

        const selectedProperty = properties.find(p => p.location === formData.location);
        let propertyPrice = selectedProperty ? selectedProperty.price : 200000;

        const plotCount = formData.plotNumber.split(',').map(p => p.trim()).filter(Boolean).length || 1;
        let baseTotal = propertyPrice * plotCount;

        let promoDetails: string | undefined = undefined;
        if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
            baseTotal *= (1 - selectedProperty.discount.percentage / 100);
            promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
        }

        const isComplete = isClientDataComplete(formData, existingClient);

        const baseClient = existingClient || {
            id: id,
            status: 'Active Client',
            stage: milestones[0]?.acronym || 'N/A',
            payment: {
                total: baseTotal,
                paid: 0,
                balance: baseTotal,
                dueDate: 'N/A',
                planType: 'N/A',
                promoDetails: promoDetails,
                paymentHistory: [],
                installments: [],
            },
            interactions: [],
            documentation: { status: 'Pending' },
             officeUse: {
                commission: { type: 'Percentage', amount: 0, status: 'Pending' }
            }
        };

        return {
            ...baseClient,
            id: id,
            name: fullName,
            surname: formData.surname,
            otherNames: formData.otherNames,
            initials: initials,
            regDate: formData.paymentDate,
            email: formData.email,
            phone: formData.telephone,
            dateOfBirth: formData.dateOfBirth,
            gender: formData.gender as Client['gender'],
            location: formData.location,
            plot: formData.plotNumber,
            photo: formData.photo,
            propertyType: formData.propertyType,
            plannedDevelopmentYear: formData.plannedDevelopmentYear,
            professionalDetails: {
                placeOfWork: formData.placeOfWork,
                profession: formData.profession,
                position: formData.position,
            },
            witness: {
                name: formData.witnessName,
                address: formData.witnessAddress,
                phone: formData.witnessPhone,
            },
            nextOfKin: {
                name: formData.kinName,
                phone: formData.kinPhone,
                relationship: formData.kinRelationship,
                email: formData.kinEmail,
                address: formData.kinAddress,
            },
            indenture: {
                name: formData.indentureName,
                address: formData.indentureAddress,
            },
            officeUse: {
                ...baseClient.officeUse,
                salesRep: formData.salesRep,
                salesManager: formData.salesManager,
                accountsHead: formData.accountsHead,
                clerk: formData.clerk,
            },
            isComplete: isComplete,
            filledFormPdf: formData.filledFormPdf,
        };
    };

    const handleSaveClient = async (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => {
        try {
            // Determine ID for new client
            const newId = (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);

            // Upload Photo
            let photoUrl = formData.photo;
            if (files?.photo) {
                photoUrl = await uploadFile(files.photo, `clients/${newId}/photos/${files.photo.name}`);
            }

            // Upload PDF
            let pdfUrl = formData.filledFormPdf;
            if (files?.pdf) {
                pdfUrl = await uploadFile(files.pdf, `clients/${newId}/documents/${files.pdf.name}`);
            }

            const updatedFormData = { ...formData, photo: photoUrl, filledFormPdf: pdfUrl };
            const newClient = createClientObject(updatedFormData, newId);

            await onSaveClient(newClient);
            setClientFormOpen(false);
            addActivityLog('Create', `Created new client: ${newClient.name}.`);
            if (!newClient.isComplete) {
                alert('Client record saved with incomplete information. Please complete all required fields to validate record.');
            }
        } catch (error) {
            console.error("Error saving client:", error);
            alert("Failed to save client. Please try again.");
        }
    };

    const handleUpdateClient = async (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => {
        if (!editingClient) return;
        try {
            // Upload Photo
            let photoUrl = formData.photo;
            if (files?.photo) {
                photoUrl = await uploadFile(files.photo, `clients/${editingClient.id}/photos/${files.photo.name}`);
            }

            // Upload PDF
            let pdfUrl = formData.filledFormPdf;
            if (files?.pdf) {
                pdfUrl = await uploadFile(files.pdf, `clients/${editingClient.id}/documents/${files.pdf.name}`);
            }

            const updatedFormData = { ...formData, photo: photoUrl, filledFormPdf: pdfUrl };
            const updatedClient = createClientObject(updatedFormData, editingClient.id, editingClient);
            const savedClient = await onSaveClient(updatedClient);
            setEditingClient(null);
            alert('Client information updated successfully.');
            addActivityLog('Update', `Updated client details for ${savedClient.name}.`);
            setClientForInvoice(savedClient);
            setActivePage('Account Management');
        } catch (error) {
            console.error("Error updating client:", error);
            alert("Failed to update client. Please try again.");
        }
    };

    const handleEditClient = (client: Client) => {
        setEditingClient(client);
        setClientFormOpen(true);
    };

    const handleSaveAndPay = async (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => {
        try {
            const newId = (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);

            let photoUrl = formData.photo;
            if (files?.photo) {
                photoUrl = await uploadFile(files.photo, `clients/${newId}/photos/${files.photo.name}`);
            }

            let pdfUrl = formData.filledFormPdf;
            if (files?.pdf) {
                pdfUrl = await uploadFile(files.pdf, `clients/${newId}/documents/${files.pdf.name}`);
            }

            const updatedFormData = { ...formData, photo: photoUrl, filledFormPdf: pdfUrl };
            const newClient = createClientObject(updatedFormData, newId);

            const savedClient = await onSaveClient(newClient);
            setClientForInvoice(savedClient);
            setActivePage('Account Management');
            setClientFormOpen(false);
            addActivityLog('Create', `Created new client with payment info: ${newClient.name}.`);
            if (!newClient.isComplete) {
                alert('Client record saved with incomplete information. Please complete all required fields to validate record.');
            }
        } catch (error) {
            console.error("Error saving client:", error);
            alert("Failed to save client. Please try again.");
        }
    };

    const handleImportClients = (importedData: any[]) => {
      const highestId = clients.length > 0 ? Math.max(...clients.map(c => c.id)) : 0;

      const newClients: Client[] = importedData.map((data, index) => {
          const fullName = `${data.surname || ''} ${data.otherNames || ''}`.trim();
          const nameParts = fullName.split(' ');
          const initials = (nameParts[0]?.[0] || '' + (nameParts.length > 1 ? nameParts[nameParts.length - 1]?.[0] : '') || '').toUpperCase();
          const selectedProperty = properties.find(p => p.location.toLowerCase() === (data.location || '').toLowerCase());
          let propertyPrice = selectedProperty ? selectedProperty.price : 200000;
          const plotCount = (data.plotNumber || '').split(',').map(p => p.trim()).filter(Boolean).length || 1;
          let baseTotal = propertyPrice * plotCount;

          let promoDetails: string | undefined = undefined;
          if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
              baseTotal *= (1 - selectedProperty.discount.percentage / 100);
              promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
          }

          const requiredCsvFields = [ 'surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
          const isRecordComplete = requiredCsvFields.every(field => data[field] && data[field].trim() !== '');

          return {
              id: highestId + 1 + index,
              name: fullName,
              surname: data.surname || '',
              otherNames: data.otherNames || '',
              initials: initials,
              regDate: data.paymentDate || new Date().toISOString().split('T')[0],
              email: data.email || '',
              phone: data.telephone || '',
              dateOfBirth: data.dateOfBirth || '',
              gender: (data.gender as Client['gender']) || undefined,
              location: data.location || '',
              plot: data.plotNumber || '',
              photo: undefined,
              propertyType: (data.propertyType as Client['propertyType']) || undefined,
              plannedDevelopmentYear: data.plannedDevelopmentYear || undefined,
              professionalDetails: {
                  placeOfWork: data.placeOfWork || '',
                  profession: data.profession || '',
                  position: data.position || '',
              },
              status: 'Active Client',
              stage: milestones[0]?.acronym || 'N/A',
              payment: {
                  total: baseTotal,
                  paid: 0,
                  balance: baseTotal,
                  dueDate: 'N/A',
                  planType: 'N/A',
                  paymentHistory: [],
                  installments: [],
                  promoDetails: promoDetails,
              },
              interactions: [],
              witness: { name: data.witnessName || '', address: data.witnessAddress || '', phone: data.witnessPhone || '' },
              nextOfKin: { 
                  name: data.kinName || '', 
                  phone: data.kinPhone || '', 
                  relationship: data.kinRelationship || '',
                  email: data.kinEmail || '',
                  address: data.kinAddress || '',
                },
              indenture: { name: data.indentureName || '', address: data.indentureAddress || '' },
              officeUse: { 
                  salesRep: data.salesRep || 'Imported', 
                  salesManager: data.salesManager || 'N/A', 
                  accountsHead: data.accountsHead || 'N/A', 
                  clerk: data.clerk || 'N/A', 
                  commission: { type: 'Percentage', amount: 0, status: 'Pending' } 
                },
              documentation: { status: 'Pending' },
              isComplete: isRecordComplete, // Based on CSV fields only
              filledFormPdf: null, // PDF cannot be imported
          };
      });

      Promise.all(newClients.map(c => onSaveClient(c))).then(() => {
          addActivityLog('Import', `Imported ${newClients.length} new clients from a CSV file.`);
      });
    };

    const handleCloseForm = () => {
        setClientFormOpen(false);
        setEditingClient(null);
    }

    const requiredCsvHeaders = [ 'surname', 'otherNames', 'dateOfBirth', 'currentAddress', 'telephone', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinName', 'kinAddress', 'kinPhone', 'kinRelationship', 'kinEmail', 'witnessName', 'witnessAddress', 'witnessPhone', 'paymentDate', 'paymentMethod', 'location', 'plotNumber', 'propertyType', 'plannedDevelopmentYear', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
    const sampleHeaders = requiredCsvHeaders.join(',');
    const sampleData = `"Doe","John","1990-01-15","123 Main St, Accra","0241234567","john.doe@example.com","Male","Tech Corp","Engineer","Senior","Doe,Jane","123 Main St, Accra","0247654321","Spouse","jane.doe@example.com","Smith,Adam","456 Oak Ave, Accra","0559876543","2024-08-01","Bank Transfer","East Legon Hills","ELH-205","Residential","2025","John K. Doe","P.O. Box 123, Accra","Sales Rep A","Manager B","Accountant C","Clerk D"`;

    // Render Row for Virtual List
    const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => {
        const client = clients[index];
        if (!client) return null;
        return (
            <ClientListItem 
                key={client.id} 
                client={client} 
                onViewDetails={onClientSelect} 
                onEdit={handleEditClient} 
                onDelete={handleDeleteClick} 
                milestones={milestones}
                style={style}
                isExpanded={!!expandedIds[client.id]}
                onToggleExpand={() => toggleExpand(client.id, index)}
            />
        );
    };

    return (
        <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">
            {/* Header */}
            <div className="flex flex-wrap items-center justify-between gap-4 flex-shrink-0">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Clients ({clients.length}{hasNextPage && '+'})</h1>
                </div>
                 <div className="flex items-center gap-4">
                    <button 
                        onClick={() => setImportWizardOpen(true)}
                        className="bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 font-semibold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors flex items-center gap-2"
                    >
                        <UploadIcon className="w-5 h-5" />
                        Import
                    </button>
                    <button 
                        onClick={() => { setEditingClient(null); setClientFormOpen(true); }}
                        className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2"
                    >
                        <DocumentPlusIcon className="w-5 h-5" />
                        Add New Client
                    </button>
                 </div>
            </div>

            {/* Filter and Search Bar */}
            <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 flex-shrink-0">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                    <div className="relative md:col-span-1">
                        <div className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 dark:text-gray-500">
                            {isLoading ? <LoaderIcon className="animate-spin" /> : <MagnifyingGlassIcon />}
                        </div>
                        <input
                            type="text"
                            placeholder="Search clients..."
                            className="bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-lg pl-10 pr-4 py-2 w-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    {/* Simplified Filters for now as they require server side implementation too */}
                    <div className="relative md:col-span-1">
                         <select className="appearance-none w-full bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-700 text-gray-900 dark:text-white py-2 px-4 pr-8 rounded-lg leading-tight focus:outline-none focus:bg-white dark:focus:bg-gray-800 focus:border-blue-500">
                            <option>All Status</option>
                            <option>Active Client</option>
                            <option>Refunded</option>
                            <option>Reallocated</option>
                        </select>
                        <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700 dark:text-gray-300">
                           <ChevronDownIcon className="w-4 h-4" />
                        </div>
                    </div>
                     <div className="relative md:col-span-1">
                         <select className="appearance-none w-full bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-700 text-gray-900 dark:text-white py-2 px-4 pr-8 rounded-lg leading-tight focus:outline-none focus:bg-white dark:focus:bg-gray-800 focus:border-blue-500">
                            <option>All Locations</option>
                            {properties.map(p => <option key={p.id}>{p.location}</option>)}
                        </select>
                        <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700 dark:text-gray-300">
                           <ChevronDownIcon className="w-4 h-4" />
                        </div>
                    </div>
                </div>
            </div>

            {/* Client List Header */}
             <div className="hidden md:grid grid-cols-12 gap-4 px-4 py-2 text-left text-sm font-semibold text-gray-500 dark:text-gray-400 flex-shrink-0">
                <div className="col-span-4">Client</div>
                <div className="col-span-2">Contact</div>
                <div className="col-span-2">Location & Plot</div>
                <div className="col-span-1 text-center">Status</div>
                <div className="col-span-2">Payment Info</div>
                <div className="col-span-1">Actions</div>
            </div>

            {/* Virtualized List */}
            <div className="flex-grow flex flex-col">
                <div className="flex-grow">
                    <AutoSizer>
                        {({ height, width }) => (
                            <List
                                ref={listRef}
                                height={height}
                                itemCount={clients.length}
                                itemSize={getItemSize}
                                width={width}
                            >
                                {Row}
                            </List>
                        )}
                    </AutoSizer>
                </div>

                {/* Pagination Controls */}
                <div className="py-2 text-center border-t border-gray-200 dark:border-gray-700">
                    {isLoading ? (
                        <span className="text-gray-500 dark:text-gray-400 text-sm">Loading data...</span>
                    ) : hasNextPage ? (
                        <button 
                            onClick={() => fetchNextPage()} 
                            disabled={isFetchingNextPage}
                            className="bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 px-4 py-2 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors text-sm font-semibold disabled:opacity-50"
                        >
                            {isFetchingNextPage ? 'Loading more...' : 'Load More Clients'}
                        </button>
                    ) : clients.length > 0 ? (
                        <span className="text-gray-400 text-sm">All clients loaded</span>
                    ) : (
                        <span className="text-gray-500 dark:text-gray-400">No clients found matching your criteria.</span>
                    )}
                </div>
            </div>

            {deletedClientInfo && (
                <div className="fixed bottom-5 right-5 bg-gray-800 text-white p-4 rounded-lg shadow-lg flex items-center gap-4 z-50 animate-fade-in">
                    <span>Client "{deletedClientInfo.name}" deleted.</span>
                </div>
            )}

            <ClientForm
                isOpen={isClientFormOpen}
                onClose={handleCloseForm}
                onSave={editingClient ? handleUpdateClient : handleSaveClient}
                onSaveAndPay={handleSaveAndPay}
                properties={properties}
                editingClient={editingClient}
            />

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={handleImportClients}
                requiredHeaders={requiredCsvHeaders.filter(h => !['dateOfBirth', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinAddress', 'kinEmail', 'propertyType', 'plannedDevelopmentYear', 'paymentMethod'].includes(h))}
                sampleHeaders={sampleHeaders}
                sampleData={sampleData}
                wizardTitle="Import Clients from CSV"
            />

            <DeleteConfirmationModal
                isOpen={!!clientToDelete}
                onClose={() => setClientToDelete(null)}
                onConfirm={confirmDeleteClient}
                itemName={clientToDelete?.name || ''}
                itemType="Client"
            />

            <style>
                {`
                    @keyframes fade-in {
                        from { opacity: 0; transform: translateY(10px); }
                        to { opacity: 1; transform: translateY(0); }
                    }
                    .animate-fade-in {
                        animation: fade-in 0.3s ease-out forwards;
                    }
                `}
            </style>
        </div>
    );
};

export default ClientsPage;

import React, { useState, useMemo, ChangeEvent } from 'react';
import { Staff, Role, AppModuleName, CompanySettings } from '../types';
import { APP_MODULES } from '../data/mockData';
import { ShieldCheckIcon, UsersIcon, PlusCircleIcon, PencilIcon, TrashIcon, EyeIcon, UserCircleIcon, BuildingLibraryIcon } from '../components/icons/DummyIcons';
import UserFormModal from '../components/UserFormModal';
import { PhoneInput } from '../components/ui/PhoneInput';
import { EmailInput } from '../components/ui/EmailInput';
import { usePermissions } from '../context/DataContext';
import { useStaff, useRoles, useCompanySettings } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';

interface SettingsPageProps {
    currentStaff: Staff;
    staff: Staff[];
    roles: Role[];
    setRoles: React.Dispatch<React.SetStateAction<Role[]>>;
    onViewStaffActivity: (staff: Staff) => void;
    companySettings: CompanySettings;
    setCompanySettings: React.Dispatch<React.SetStateAction<CompanySettings>>;
    onUpdateStaff: (id: string, details: Partial<Staff>) => Promise<void>;
}

const SettingsPage: React.FC<SettingsPageProps> = ({ currentStaff, staff, roles, setRoles, onViewStaffActivity, companySettings, setCompanySettings, onUpdateStaff }) => {
    // Use hooks directly inside component to ensure access to actions
    const { saveStaff, deleteStaff } = useStaff();
    const { rolePermissions, updateRolePermission, initRolePermissions } = usePermissions();

    const [activeTab, setActiveTab] = useState('profile');
    const [selectedRole, setSelectedRole] = useState<Role | null>(roles[0] || null);

    // State for Modals
    const [isStaffModalOpen, setStaffModalOpen] = useState(false);
    const [isRoleModalOpen, setRoleModalOpen] = useState(false);
    const [editingStaff, setEditingStaff] = useState<Staff | null>(null);
    const [editingRole, setEditingRole] = useState<Role | null>(null);
    const [newRoleData, setNewRoleData] = useState({ name: '', description: '' });

    // State for Delete Confirmation
    const [staffToDelete, setStaffToDelete] = useState<Staff | null>(null);

    // State for local forms
    const [profileData, setProfileData] = useState({ fullName: currentStaff.fullName, email: currentStaff.email, phone: currentStaff.phone || '' });
    const [companyData, setCompanyData] = useState({ name: companySettings.name });
    const [profilePhotoPreview, setProfilePhotoPreview] = useState<string | null>(currentStaff.photo || null);
    const [companyLogoPreview, setCompanyLogoPreview] = useState<string | null>(companySettings.logo || null);

    const userRole = useMemo(() => roles.find(r => r.id === currentStaff.roleId), [currentStaff, roles]);
    const canManageStaff = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);
    const canManageCompany = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);

    const handlePermissionChange = async (moduleId: AppModuleName, permission: string, value: boolean) => {
        if (!selectedRole) return;
        await updateRolePermission(selectedRole.id, moduleId, permission, value);
    };

    const handleSaveRole = async (e: React.FormEvent) => {
        e.preventDefault();
        const roleData = newRoleData;
        if (editingRole) {
            setRoles(prev => prev.map(r => r.id === editingRole.id ? { ...editingRole, ...roleData } : r));
        } else {
            const newRoleId = roleData.name;
            const newRole: Role = { id: newRoleId, ...roleData };
            setRoles(prev => [...prev, newRole]); 
            await initRolePermissions(newRoleId);
        }
        setRoleModalOpen(false);
        setEditingRole(null);
        setNewRoleData({ name: '', description: '' });
    };

    const handleDeleteRole = (roleId: string) => {
        if (window.confirm("Are you sure you want to delete this role? This cannot be undone.")) {
            if (staff.some(u => u.roleId === roleId)) {
                alert("Cannot delete role. It is currently assigned to one or more staff members.");
                return;
            }
            setRoles(prev => prev.filter(r => r.id !== roleId));
            if (selectedRole?.id === roleId) setSelectedRole(roles[0] || null);
        }
    };

    const handleSaveStaff = async (staffData: Partial<Staff>) => {
        try {
            if(editingStaff) {
                await onUpdateStaff(editingStaff.id, staffData);
            } else {
                const nameParts = staffData.fullName!.split(' ');
                const initials = (nameParts[0]?.[0] || '' + nameParts[nameParts.length - 1]?.[0] || '').toUpperCase();

                const newStaff: Staff = { 
                    id: String(Date.now()), 
                    fullName: staffData.fullName!, email: staffData.email!, phone: staffData.phone,
                    password: staffData.password, roleId: staffData.roleId!, status: staffData.status!,
                    lastLogin: 'Never', initials: initials
                };
                await saveStaff(newStaff);
            }
            setStaffModalOpen(false);
            setEditingStaff(null);
        } catch (error: any) {
            alert(`Error saving staff: ${error.message || 'Unknown error'}`);
        }
    }

    // Initiate delete flow
    const handleDeleteClick = (staffMember: Staff) => {
        if (staffMember.id === currentStaff.id) {
            alert("You cannot delete your own account.");
            return;
        }
        setStaffToDelete(staffMember);
    }

    // Execute delete
    const confirmDeleteStaff = async () => {
        if (staffToDelete) {
            await deleteStaff(staffToDelete.id);
            setStaffToDelete(null);
        }
    }

    const handleProfileFormChange = (e: ChangeEvent<HTMLInputElement>) => {
        setProfileData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const handleProfilePhotoChange = async (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            try {
                // Optimistic UI update
                const reader = new FileReader();
                reader.onloadend = () => {
                    setProfilePhotoPreview(reader.result as string);
                };
                reader.readAsDataURL(file);

                const url = await uploadFile(file, `staff/${currentStaff.id}/profile/${file.name}`);
                await onUpdateStaff(currentStaff.id, { photo: url });
            } catch (error) {
                console.error("Profile photo upload failed:", error);
                alert("Failed to upload profile photo.");
            }
        }
    };

    const handleCompanyLogoChange = async (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            try {
                const reader = new FileReader();
                reader.onloadend = () => {
                    setCompanyLogoPreview(reader.result as string);
                };
                reader.readAsDataURL(file);

                const url = await uploadFile(file, `system/branding/${file.name}`);
                setCompanySettings(prev => ({ ...prev, logo: url }));
            } catch (error) {
                console.error("Company logo upload failed:", error);
                alert("Failed to upload company logo.");
            }
        }
    };

    const handleSaveCompanySettings = () => {
        setCompanySettings(prev => ({ ...prev, name: companyData.name }));
        alert('Company settings saved.');
    };

    const RolePill: React.FC<{ role: Role }> = ({ role }) => {
        const roleColors: { [key: string]: string } = {
            'CEO': 'bg-yellow-100 text-yellow-800 border-yellow-200 dark:bg-yellow-900/30 dark:text-yellow-300 dark:border-yellow-800',
            'Administrator': 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-800',
            'Chief Accountant': 'bg-green-100 text-green-800 border-green-200 dark:bg-green-900/30 dark:text-green-300 dark:border-green-800',
            'Head of Sales': 'bg-purple-100 text-purple-800 border-purple-200 dark:bg-purple-900/30 dark:text-purple-300 dark:border-purple-800',
        };
        const defaultColor = 'bg-gray-100 text-gray-800 border-gray-200 dark:bg-gray-700 dark:text-gray-300 dark:border-gray-600';
        const color = role ? (roleColors[role.name] || defaultColor) : defaultColor;
        return <span className={`px-2 py-1 text-xs font-semibold rounded-full border ${color}`}>{role ? role.name : 'Unknown Role'}</span>
    }

    const tabs = [
        { id: 'profile', name: 'My Profile', icon: <UserCircleIcon className="w-5 h-5" /> },
        { id: 'company', name: 'Company Settings', icon: <BuildingLibraryIcon className="w-5 h-5" />, disabled: !canManageCompany },
        { id: 'roles', name: 'Roles & Permissions', icon: <ShieldCheckIcon className="w-5 h-5" />, disabled: !canManageStaff },
        { id: 'staff', name: 'Staff Accounts', icon: <UsersIcon className="w-5 h-5" />, disabled: !canManageStaff },
    ];

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">System Settings</h1>

            <div className="flex border-b border-gray-200 dark:border-gray-700">
                {tabs.map(tab => !tab.disabled && (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-2 px-4 py-3 font-semibold transition-colors ${activeTab === tab.id ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400' : 'text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white'}`}>
                        {tab.icon} {tab.name}
                    </button>
                ))}
            </div>

            {/* Profile Tab */}
            {activeTab === 'profile' && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4">Edit Your Profile</h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
                        <div className="md:col-span-1 flex flex-col items-center">
                            {profilePhotoPreview ? (
                                <img src={profilePhotoPreview} alt="Profile" className="w-32 h-32 rounded-full object-cover mb-4" />
                            ) : (
                                <div className="w-32 h-32 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center mb-4"><UserCircleIcon className="w-20 h-20 text-gray-400 dark:text-gray-500" /></div>
                            )}
                            <label htmlFor="photo-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600">
                                Change Photo
                                <input id="photo-upload" name="photo" type="file" className="sr-only" onChange={handleProfilePhotoChange} accept="image/*" />
                            </label>
                        </div>
                        <div className="md:col-span-2 space-y-4">
                            <div>
                                <label className="text-gray-700 dark:text-gray-300">Full Name</label>
                                <input type="text" name="fullName" value={profileData.fullName} onChange={handleProfileFormChange} className="w-full mt-1 p-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded" />
                            </div>
                             <div>
                                <EmailInput label="Email" name="email" value={profileData.email} onChange={(val) => setProfileData(prev => ({...prev, email: val}))} />
                            </div>
                             <div>
                                <PhoneInput label="Phone" name="phone" value={profileData.phone} onChange={(val) => setProfileData(prev => ({...prev, phone: val}))} />
                            </div>
                            <div className="flex justify-end">
                                <button onClick={() => onUpdateStaff(currentStaff.id, profileData)} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors">Save Changes</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Company Tab */}
            {activeTab === 'company' && canManageCompany && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4">Company Profile</h2>
                    <div className="space-y-4">
                        <div>
                            <label className="text-gray-700 dark:text-gray-300">Company Name</label>
                            <input type="text" value={companyData.name} onChange={e => setCompanyData({name: e.target.value})} className="w-full mt-1 p-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded" />
                        </div>
                        <div>
                            <label className="text-gray-700 dark:text-gray-300">Company Logo</label>
                            <div className="mt-1 flex items-center gap-4">
                                {companyLogoPreview && <img src={companyLogoPreview} alt="Logo" className="h-16 w-auto bg-gray-100 p-1 border rounded" />}
                                <label htmlFor="logo-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600">
                                    Upload Logo
                                    <input id="logo-upload" name="logo" type="file" className="sr-only" onChange={handleCompanyLogoChange} accept="image/*" />
                                </label>
                            </div>
                        </div>
                         <div className="flex justify-end">
                            <button onClick={handleSaveCompanySettings} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors">Save Company Settings</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Roles Tab */}
            {activeTab === 'roles' && canManageStaff && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-1 bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="font-bold text-lg text-gray-800 dark:text-white">Roles</h2>
                            <button onClick={() => { setEditingRole(null); setNewRoleData({name: '', description: ''}); setRoleModalOpen(true); }} className="flex items-center gap-1 text-sm font-semibold text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300">
                                <PlusCircleIcon className="w-5 h-5" /> New Role
                            </button>
                        </div>
                        <div className="space-y-2">
                            {roles.map(role => (
                                <button key={role.id} onClick={() => setSelectedRole(role)} className={`w-full text-left p-3 rounded-md transition-colors ${selectedRole?.id === role.id ? 'bg-blue-100 dark:bg-blue-900/30' : 'hover:bg-gray-100 dark:hover:bg-gray-700'}`}>
                                    <h3 className="font-semibold text-gray-900 dark:text-white">{role.name}</h3>
                                    <p className="text-sm text-gray-500 dark:text-gray-400">{role.description}</p>
                                </button>
                            ))}
                        </div>
                    </div>
                    <div className="lg:col-span-2 bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                        {selectedRole ? (
                            <div>
                                <div className="flex justify-between items-start mb-4 pb-4 border-b border-gray-200 dark:border-gray-700">
                                    <div>
                                        <h2 className="font-bold text-xl text-gray-800 dark:text-white" style={{color: ''}}>{selectedRole.name} Permissions</h2>
                                        <p className="text-sm text-gray-500 dark:text-gray-400">Manage access for the {selectedRole.name} role.</p>
                                    </div>
                                    <div>
                                        <button onClick={() => {setEditingRole(selectedRole); setNewRoleData({name: selectedRole.name, description: selectedRole.description}); setRoleModalOpen(true)}} className="p-2 text-gray-500 dark:text-gray-400 hover:text-blue-600 dark:hover:text-blue-400"><PencilIcon className="w-5 h-5" /></button>
                                        {!selectedRole.isDefault && <button onClick={() => handleDeleteRole(selectedRole.id)} className="p-2 text-gray-500 dark:text-gray-400 hover:text-red-600 dark:hover:text-red-400"><TrashIcon className="w-5 h-5" /></button>}
                                    </div>
                                </div>
                                <table className="w-full text-sm">
                                    <thead>
                                        <tr className="text-left text-gray-500 dark:text-gray-400 font-semibold">
                                            <th className="py-2">Module</th>
                                            <th className="text-center py-2">View</th><th className="text-center py-2">Create</th>
                                            <th className="text-center py-2">Edit</th><th className="text-center py-2">Delete</th>
                                            <th className="text-center py-2">Approve</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                                        {APP_MODULES.map(module => {
                                            const permissions = rolePermissions.find(rp => rp.roleId === selectedRole.id && rp.moduleId === module.id)?.permissions;
                                            const effectivePermissions = permissions || { view: false, create: false, edit: false, delete: false, approve: false };

                                            return (
                                                <tr key={module.id} className="">
                                                    <td className="py-3 font-semibold text-gray-700 dark:text-gray-200">{module.name}</td>
                                                    {['view', 'create', 'edit', 'delete', 'approve'].map((key) => (
                                                        <td key={key} className="text-center py-2">
                                                            <input type="checkbox" className="form-checkbox h-5 w-5 rounded text-blue-600 focus:ring-blue-500 bg-gray-100 dark:bg-gray-700 border-gray-300 dark:border-gray-600"
                                                                checked={effectivePermissions[key as keyof typeof effectivePermissions]}
                                                                onChange={(e) => handlePermissionChange(module.id as AppModuleName, key, e.target.checked)} />
                                                        </td>
                                                    ))}
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        ) : (
                            <div className="text-center py-20"><p className="text-gray-500 dark:text-gray-400">Select a role to manage permissions.</p></div>
                        )}
                    </div>
                </div>
            )}

            {/* Staff Tab */}
            {activeTab === 'staff' && canManageStaff && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="font-bold text-xl text-gray-800 dark:text-white" style={{color: ''}}>Manage Staff Accounts</h2>
                        <button onClick={() => {setEditingStaff(null); setStaffModalOpen(true);}} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors">
                            <PlusCircleIcon className="w-5 h-5" /> Create New Staff
                        </button>
                    </div>
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-50 dark:bg-gray-900 text-gray-600 dark:text-gray-300">
                            <tr><th className="px-4 py-2">Name</th><th className="px-4 py-2">Role</th><th className="px-4 py-2">Status</th><th className="px-4 py-2">Last Login</th><th className="px-4 py-2">Actions</th></tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                            {staff.map(member => (
                                <tr key={member.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50">
                                    <td className="px-4 py-3 flex items-center gap-3">
                                        {member.photo ? <img src={member.photo} alt="P" className="w-8 h-8 rounded-full object-cover"/> : <div className="w-8 h-8 rounded-full bg-gray-200 dark:bg-gray-600 flex items-center justify-center font-bold text-xs text-gray-600 dark:text-gray-200">{member.initials}</div>}
                                        <div>
                                            <div className="font-semibold text-gray-900 dark:text-white">{member.fullName}</div>
                                            <div className="text-gray-500 dark:text-gray-400">{member.email}</div>
                                        </div>
                                    </td>
                                    <td className="px-4 py-3"><RolePill role={roles.find(r => r.id === member.roleId)!} /></td>
                                    <td className="px-4 py-3"><span className={`px-2 py-1 text-xs font-semibold rounded-full ${member.status === 'Active' ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300' : 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300'}`}>{member.status}</span></td>
                                    <td className="px-4 py-3 text-gray-500 dark:text-gray-400">{member.lastLogin}</td>
                                    <td className="px-4 py-3 flex items-center gap-1">
                                        <button onClick={() => onViewStaffActivity(member)} className="p-1 text-gray-500 hover:text-green-600 dark:text-gray-400 dark:hover:text-green-400" title="View Activity"><EyeIcon className="w-5 h-5" /></button>
                                        <button onClick={() => { setEditingStaff(member); setStaffModalOpen(true); }} className="p-1 text-gray-500 hover:text-blue-600 dark:text-gray-400 dark:hover:text-blue-400" title="Edit Staff"><PencilIcon className="w-5 h-5" /></button>
                                        <button onClick={() => handleDeleteClick(member)} className="p-1 text-gray-500 hover:text-red-600 dark:text-gray-400 dark:hover:text-red-400" title="Delete Staff"><TrashIcon className="w-5 h-5" /></button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            <UserFormModal 
                isOpen={isStaffModalOpen}
                onClose={() => { setStaffModalOpen(false); setEditingStaff(null); }}
                onSave={handleSaveStaff}
                editingUser={editingStaff}
                roles={roles}
            />

            {/* Custom Delete Confirmation Modal */}
            {staffToDelete && (
                <div className="fixed inset-0 bg-black bg-opacity-60 z-[60] flex justify-center items-center p-4 backdrop-blur-sm">
                    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl max-w-sm w-full p-6 border border-gray-200 dark:border-gray-700 animate-in fade-in zoom-in duration-200">
                        <div className="flex items-center justify-center w-12 h-12 mx-auto bg-red-100 dark:bg-red-900/30 rounded-full mb-4">
                            <TrashIcon className="w-6 h-6 text-red-600 dark:text-red-400" />
                        </div>
                        <h3 className="text-lg font-bold text-center text-gray-900 dark:text-white mb-2">Delete Staff Account?</h3>
                        <p className="text-center text-gray-600 dark:text-gray-300 mb-6 text-sm">
                            Are you sure you want to delete <strong>{staffToDelete.fullName}</strong>? This action cannot be undone and will immediately revoke their access to the system.
                        </p>
                        <div className="flex justify-center gap-3">
                            <button 
                                onClick={() => setStaffToDelete(null)}
                                className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-semibold rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                            >
                                Cancel
                            </button>
                            <button 
                                onClick={confirmDeleteStaff}
                                className="px-4 py-2 bg-red-600 text-white font-semibold rounded-lg hover:bg-red-700 transition-colors"
                            >
                                Delete Account
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {isRoleModalOpen && (
                <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
                    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-md border border-gray-200 dark:border-gray-700">
                        <form onSubmit={handleSaveRole}>
                            <div className="flex justify-between items-center p-4 border-b border-gray-200 dark:border-gray-700"><h3 className="text-lg font-bold text-gray-800 dark:text-white">{editingRole ? 'Edit Role' : 'Create New Role'}</h3><button type="button" onClick={() => setRoleModalOpen(false)} className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200">&times;</button></div>
                            <div className="p-6 space-y-4">
                                <div><label className="text-gray-700 dark:text-gray-300">Role Name</label><input type="text" value={newRoleData.name} onChange={e => setNewRoleData({...newRoleData, name: e.target.value})} className="w-full mt-1 p-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded" required /></div>
                                <div><label className="text-gray-700 dark:text-gray-300">Description</label><textarea value={newRoleData.description} onChange={e => setNewRoleData({...newRoleData, description: e.target.value})} className="w-full mt-1 p-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded" required /></div>
                            </div>
                            <div className="p-4 bg-gray-50 dark:bg-gray-900 flex justify-end gap-2 rounded-b-lg"><button type="button" onClick={() => setRoleModalOpen(false)} className="text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 px-4 py-2 rounded">Cancel</button><button type="submit" className="bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700">{editingRole ? 'Save Changes' : 'Create Role'}</button></div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

import React, { useState, useEffect, ChangeEvent, FormEvent } from 'react';
import { Property, VendorLandPurchase, Payee, PlotInventory, PlotSize } from '../types';
import { ArrowLeftIcon, CheckCircleIcon, PlusCircleIcon, TrashIcon, UploadIcon } from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Input, Select, Textarea } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { uploadFile } from '../services/storageService';

interface LandPurchaseFormPageProps {
  onBack: () => void;
  properties: Property[];
  onSaveProperty: (property: Property) => Promise<void>;
}

const PLOT_SIZE_SQFT: Record<PlotSize, number> = {
    '70x100 ft': 7000,
    '70x50 ft': 3500,
    '60x80 ft': 4800,
};
const ACRE_SQFT = 43560;

const FileUploadField: React.FC<{ id: string; label: string; file: File | null | undefined; onChange: (e: ChangeEvent<HTMLInputElement>) => void; accept: string; }> = ({ id, label, file, onChange, accept }) => (
    <div className="sm:col-span-1">
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">{label}</label>
        <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-gray-300 dark:border-gray-700 border-dashed rounded-md hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
            <div className="space-y-1 text-center">
                <UploadIcon className="mx-auto h-12 w-12 text-gray-400 dark:text-gray-500" />
                <div className="flex text-sm text-gray-600 dark:text-gray-400">
                    <label htmlFor={id} className="relative cursor-pointer rounded-md font-medium text-blue-600 hover:text-blue-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500">
                        <span>Upload a file</span>
                        <input id={id} name={id} type="file" className="sr-only" onChange={onChange} accept={accept} />
                    </label>
                    <p className="pl-1">or drag and drop</p>
                </div>
                <p className="text-xs text-gray-500 dark:text-gray-500">{file ? file.name : "PDF, PNG, JPG up to 10MB"}</p>
            </div>
        </div>
    </div>
);

const initialFormData: VendorLandPurchase = {
    ownerNames: '',
    location: '',
    registrationStatus: '',
    purchaseAgreementDate: '',
    totalSizeAcres: '',
    pricePerAcre: '',
    totalPrice: '',
    familyName: '',
    nameOnSearch: '',
    officialSearchDoc: null,
    sitePlanDoc: null,
    leadNegotiators: '',
    familyContactPerson: '',
    phoneNumbers: ['', '', ''],
    additionalNotes: '',
    paymentAmountPerMonth: '',
    paymentPeriodMonths: '',
    recurringPaymentTime: '',
    payees: [],
    plotInventory: [{ size: '70x100 ft', count: '' }],
    signingDate: new Date().toISOString().split('T')[0],
    familyRepSignature: { name: '', date: ''},
    ceoSignature: { name: '', date: '' },
    managingDirectorSignature: { name: '', date: '' },
    accountsHeadSignature: { name: '', date: '' },
};


const LandPurchaseFormPage: React.FC<LandPurchaseFormPageProps> = ({ onBack, properties, onSaveProperty }) => {
    const [formData, setFormData] = useState<VendorLandPurchase>(initialFormData);
    const [isSaved, setIsSaved] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        const totalSqFt = formData.plotInventory.reduce((sum, item) => {
            const count = parseInt(item.count) || 0;
            return sum + (PLOT_SIZE_SQFT[item.size] * count);
        }, 0);

        const totalAcres = totalSqFt > 0 ? (totalSqFt / ACRE_SQFT).toFixed(4) : '';
        setFormData(prev => ({...prev, totalSizeAcres: totalAcres}));

        const price = parseFloat(formData.pricePerAcre);
        if (!isNaN(parseFloat(totalAcres)) && !isNaN(price) && parseFloat(totalAcres) > 0 && price > 0) {
            setFormData(prev => ({ ...prev, totalPrice: (parseFloat(totalAcres) * price).toFixed(2) }));
        } else {
            setFormData(prev => ({ ...prev, totalPrice: '' }));
        }
    }, [formData.plotInventory, formData.pricePerAcre]);

    const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handlePhoneChange = (index: number, value: string) => {
        const newPhones = [...formData.phoneNumbers];
        newPhones[index] = value;
        setFormData(prev => ({...prev, phoneNumbers: newPhones}));
    };

    const handleSignatureChange = (signatory: keyof VendorLandPurchase, field: 'name' | 'date', value: string) => {
        setFormData(prev => ({
            ...prev,
            [signatory]: { ...(prev[signatory] as object), [field]: value }
        }));
    };

    const addPayee = () => {
        if (formData.payees.length < 10) {
            setFormData(prev => ({
                ...prev,
                payees: [...prev.payees, { id: Date.now().toString(), name: '', acres: '', amount: '' }]
            }));
        }
    };

    const handlePayeeChange = (index: number, field: keyof Omit<Payee, 'id'>, value: string) => {
        const newPayees = [...formData.payees];
        newPayees[index] = { ...newPayees[index], [field]: value };
        setFormData(prev => ({ ...prev, payees: newPayees }));
    };

    const removePayee = (id: string) => {
        setFormData(prev => ({ ...prev, payees: prev.payees.filter(p => p.id !== id) }));
    };

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        const { name, files } = e.target;
        setFormData(prev => ({ ...prev, [name]: (files && files.length > 0) ? files[0] : null }));
    };

    const handleInventoryChange = (index: number, field: 'size' | 'count', value: string) => {
        const newInventory = [...formData.plotInventory];
        newInventory[index] = {...newInventory[index], [field]: value as PlotSize};
        setFormData(prev => ({...prev, plotInventory: newInventory}));
    };

    const addInventoryRow = () => {
        setFormData(prev => ({...prev, plotInventory: [...prev.plotInventory, {size: '70x100 ft', count: ''}]}));
    };

    const removeInventoryRow = (index: number) => {
        if (formData.plotInventory.length > 1) {
            setFormData(prev => ({...prev, plotInventory: prev.plotInventory.filter((_, i) => i !== index)}));
        }
    };

    const handleSubmit = async (e: FormEvent) => {
        e.preventDefault();
        setIsSaving(true);

        try {
            const regStatusMap: Record<string, Property['registrationStatus']> = {
                'LRD': 'Titled', 'PVLMD': 'Indenture', 'SMD': 'Plotted', 'LVD': 'Indenture'
            };

            const totalSizeAcres = parseFloat(formData.totalSizeAcres) || 0;

            const finalInventory: PlotInventory[] = formData.plotInventory
                .filter(item => parseInt(item.count) > 0)
                .map(item => ({
                    size: item.size,
                    count: parseInt(item.count),
                    sold: 0
                }));

            const totalPlots = finalInventory.reduce((sum, item) => sum + item.count, 0);
            const propertyId = Date.now();

            let officialSearchDocUrl = '';
            if (formData.officialSearchDoc) {
                officialSearchDocUrl = await uploadFile(formData.officialSearchDoc, `properties/${propertyId}/legal/${formData.officialSearchDoc.name}`);
            }

            let sitePlanDocUrl = '';
            if (formData.sitePlanDoc) {
                sitePlanDocUrl = await uploadFile(formData.sitePlanDoc, `properties/${propertyId}/legal/${formData.sitePlanDoc.name}`);
            }

            const newProperty: Property = {
                id: propertyId,
                location: formData.location,
                description: `Land acquired from ${formData.ownerNames}`,
                size: totalSizeAcres,
                price: totalPlots > 0 ? (parseFloat(formData.totalPrice) / totalPlots) : 0,
                inventory: finalInventory,
                registrationStatus: regStatusMap[formData.registrationStatus] || 'Plotted',
                // Assuming we add these fields to Property type or handle them separately
                // For now, storing them implicitly if needed, or if Property type allows extensions.
                // The provided Property type doesn't have these fields explicitly, so we just log/store what we can.
            };

            // To properly persist the document URLs, we should technically extend the Property type.
            // For now, we proceed with saving the property as defined.

            await onSaveProperty(newProperty);

            setIsSaved(true);
            window.scrollTo(0, 0);
            setTimeout(() => {
                setIsSaved(false);
                setFormData(initialFormData);
            }, 4000);
        } catch (error) {
            console.error("Error saving property:", error);
            alert("Failed to save property.");
        } finally {
            setIsSaving(false);
        }
    };

    const signatureFields: {key: 'familyRepSignature' | 'ceoSignature' | 'managingDirectorSignature' | 'accountsHeadSignature', label: string}[] = [
        {key: 'familyRepSignature', label: 'Family Representative'},
        {key: 'ceoSignature', label: 'CEO'},
        {key: 'managingDirectorSignature', label: 'Managing Director/Administrator'},
        {key: 'accountsHeadSignature', label: 'Accounts Head of Department'}
    ];

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                 <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" />
                        Back to CEO Hub
                    </button>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white mt-2">New Land Acquisition</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Record details for newly purchased land.</p>
                </div>
            </div>

            {isSaved && (
                <div className="bg-green-100 dark:bg-green-900/30 border-l-4 border-green-500 text-green-700 dark:text-green-300 p-4 rounded-lg shadow-md" role="alert">
                    <div className="flex items-center">
                        <CheckCircleIcon className="w-6 h-6 mr-3"/>
                        <div>
                            <p className="font-bold">Success!</p>
                            <p>Land Purchase Details Successfully Recorded and Added to Property Listings.</p>
                        </div>
                    </div>
                </div>
            )}

            <form id="land-purchase-form" onSubmit={handleSubmit} className="space-y-6">
                <Card title="Section 1: Land, Inventory & Ownership Details">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <Input id="ownerNames" name="ownerNames" label="Name of Owner(s)" value={formData.ownerNames} onChange={handleChange} required containerClassName="md:col-span-2" />
                        <Input id="location" name="location" label="Location of Property" value={formData.location} onChange={handleChange} required />
                    </div>
                    <div className="mt-6 pt-4 border-t border-gray-200 dark:border-gray-700">
                        <h4 className="text-lg font-medium text-gray-800 dark:text-white">Plot Inventory</h4>
                        <p className="text-sm text-gray-500 dark:text-gray-400 mb-2">Specify the number of plots for each available size. Total acreage will be calculated automatically.</p>
                        <div className="space-y-2">
                           {formData.plotInventory.map((item, index) => (
                               <div key={index} className="grid grid-cols-12 gap-2 items-end">
                                   <div className="col-span-5">
                                       <Select id={`plot-size-${index}`} label={index === 0 ? "Plot Size" : ""} value={item.size} onChange={(e) => handleInventoryChange(index, 'size', e.target.value)}>
                                            <option>70x100 ft</option><option>70x50 ft</option><option>60x80 ft</option>
                                       </Select>
                                   </div>
                                   <div className="col-span-5">
                                        <Input id={`plot-count-${index}`} label={index === 0 ? "Number of Plots" : ""} type="number" value={item.count} onChange={(e) => handleInventoryChange(index, 'count', e.target.value)} />
                                   </div>
                                    <div className="col-span-2 pb-2">
                                        <button type="button" onClick={() => removeInventoryRow(index)} className="text-red-500 p-2 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full"><TrashIcon className="w-5 h-5"/></button>
                                   </div>
                               </div>
                           ))}
                        </div>
                        <button type="button" onClick={addInventoryRow} className="mt-2 flex items-center gap-2 text-sm font-semibold text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300">
                            <PlusCircleIcon className="w-5 h-5"/> Add Another Plot Size
                        </button>
                    </div>
                     <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-6 pt-4 border-t border-gray-200 dark:border-gray-700">
                        <Select id="registrationStatus" name="registrationStatus" label="Registration Status of Land" value={formData.registrationStatus} onChange={handleChange} required>
                            <option value="">Select division...</option>
                            <option value="LRD">LRD</option>
                            <option value="PVLMD">PVLMD</option>
                            <option value="SMD">SMD</option>
                            <option value="LVD">LVD</option>
                        </Select>
                        <Input id="purchaseAgreementDate" name="purchaseAgreementDate" label="Date of final signing" type="date" value={formData.purchaseAgreementDate} onChange={handleChange} required />
                        <Input id="pricePerAcre" name="pricePerAcre" label="Price Per acre (GHC)" type="number" value={formData.pricePerAcre} onChange={handleChange} placeholder="e.g., 50000.00" />
                        <Input id="totalSizeAcres" name="totalSizeAcres" label="Total Size (acres)" type="number" value={formData.totalSizeAcres} onChange={()=>{}} readOnly />
                        <Input id="totalPrice" name="totalPrice" label="Total Price (GHC)" type="number" value={formData.totalPrice} onChange={() => {}} readOnly containerClassName="md:col-span-1" />
                    </div>
                </Card>

                <Card title="Section 2: Official & Legal Details">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <Input id="familyName" name="familyName" label="Official Name of Family" value={formData.familyName} onChange={handleChange} />
                        <Input id="nameOnSearch" name="nameOnSearch" label="Name on Official search at Time of Acquisition" value={formData.nameOnSearch} onChange={handleChange} />
                        <FileUploadField id="officialSearchDoc" label="Official Search Document" file={formData.officialSearchDoc} onChange={handleFileChange} accept=".pdf,image/*" />
                        <FileUploadField id="sitePlanDoc" label="Site Plan" file={formData.sitePlanDoc} onChange={handleFileChange} accept=".pdf,image/*" />
                    </div>
                </Card>

                <Card title="Section 3: Negotiators & Family Contacts">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        <Textarea id="leadNegotiators" name="leadNegotiators" label="Name(s) of lead Negotiators/Contact Persons" value={formData.leadNegotiators} onChange={handleChange} placeholder="1. John Doe&#10;2. Jane Smith" containerClassName="lg:col-span-3"/>
                        <Input id="familyContactPerson" name="familyContactPerson" label="Name of family contact person" value={formData.familyContactPerson} onChange={handleChange} />
                        <Input id="phone1" name="phone1" label="Telephone No. 1" type="tel" value={formData.phoneNumbers[0]} onChange={(e) => handlePhoneChange(0, e.target.value)} />
                        <Input id="phone2" name="phone2" label="Telephone No. 2" type="tel" value={formData.phoneNumbers[1]} onChange={(e) => handlePhoneChange(1, e.target.value)} />
