                                            <UploadIcon className="w-4 h-4"/> Upload
                                            <input type="file" className="sr-only" onChange={(e) => e.target.files?.[0] && handleLogoUpload(e.target.files[0], 'companyLogoDark', setCompanyLogoDarkPreview)} accept="image/*" />
