// --- Clients ---
export const useClients = (searchTerm: string = '') => {
    const queryClient = useQueryClient();

    // Infinite Query for Pagination (Default view)
    const { 
        data: infiniteData, 
        fetchNextPage, 
        hasNextPage, 
        isFetchingNextPage,
        isLoading: isPaginationLoading 
    } = useInfiniteQuery({
        queryKey: ['clients', 'paginated'],
        queryFn: ({ pageParam }) => dbService.fetchClientsPaginated(pageParam as any),
        initialPageParam: null,
        getNextPageParam: (lastPage) => lastPage.lastDoc || undefined,
        enabled: !searchTerm, // Only pagination when NOT searching
    });

    // Simple Query for Search (Active when searching)
    const { 
        data: searchData, 
        isLoading: isSearchLoading 
    } = useQuery({
        queryKey: ['clients', 'search', searchTerm],
        queryFn: () => dbService.searchClients(searchTerm),
        enabled: !!searchTerm,
    });

    // Combine logic: If searching, use searchData; else flatten infinite pages
    const clients = searchTerm 
        ? (searchData || []) 
        : (infiniteData?.pages.flatMap(page => page.data) || []);

    const isLoading = searchTerm ? isSearchLoading : isPaginationLoading;

    const saveClient = useMutation({
        mutationFn: dbService.persistClient,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['clients'] });
        }
    });

    const deleteClient = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['clients'] });
        }
    });

    return { 
        clients, 
        isLoading, 
        saveClient: saveClient.mutateAsync, 
        deleteClient: deleteClient.mutateAsync,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage
    };
};

