service firebase.storage {
  match /b/{bucket}/o {

    // Helper function to check auth
    function isAuthenticated() {
      return request.auth != null;
    }

    // --- System Branding (Logos, Favicons) ---
    // CRITICAL: These must be publicly readable so they show up on the Login Page 
    // before the user signs in.
    match /system/branding/{allPaths=**} {
      allow read: if true; 
      allow write: if isAuthenticated(); // Only logged-in staff can update settings
    }

    // --- Staff Profile Photos ---
    match /staff/{userId}/{allPaths=**} {
      allow read: if isAuthenticated();
      allow write: if isAuthenticated();
    }

    // --- Client Files (Photos, Documents) ---
    match /clients/{clientId}/{allPaths=**} {
      allow read, write: if isAuthenticated();
    }

    // --- Property Documents (Legal, Plans) ---
    match /properties/{propertyId}/{allPaths=**} {
      allow read, write: if isAuthenticated();
    }

    // --- Promotion Banners ---
    match /promotions/{allPaths=**} {
      allow read, write: if isAuthenticated();
    }

    // --- Amendment Request Scans ---
    match /amendments/{allPaths=**} {
      allow read, write: if isAuthenticated();
    }
  }
}

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- Helper Functions ---

    // Check if the user is authenticated
    function isAuthenticated() {
      return request.auth != null;
    }

    // Fail-safe check for CEO role. 
    // Uses exists() to prevent errors if the user document is missing during sign-up/bootstrap.
    function isCEO() {
      return isAuthenticated() && 
             exists(/databases/$(database)/documents/user/$(request.auth.uid)) && 
             get(/databases/$(database)/documents/user/$(request.auth.uid)).data.roleId == 'CEO';
    }

    // Generic Permission Check with Existence Verification
    function can(module, action) {
      // 1. Get User Document safely
      let userDocPath = /databases/$(database)/documents/user/$(request.auth.uid);

      // 2. If user doc exists, get the role
      let role = exists(userDocPath) ? get(userDocPath).data.roleId : null;

      // 3. If role exists, get permissions document
      let permDocPath = /databases/$(database)/documents/role_permissions/$(role);

      // 4. Check if permission allows action. 
      // Returns false if any document is missing to be safe (fail-closed).
      return role != null && 
             exists(permDocPath) && 
             get(permDocPath).data.modules[module][action] == true;
    }

    // --- Collection Rules ---

    // 1. Company Settings (Public Read for Login Page Branding)
    match /settings/{docId} {
      allow read: if true; 
      allow write: if isAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    // 2. Users (Staff Profiles)
    match /user/{userId} {
      // Allow reading any user profile if authenticated (needed for lists, assigning tasks)
      allow read: if isAuthenticated();

      // Allow creation if:
      // a) It's the user creating their own profile (Bootstrapping)
      // b) It's a CEO
      // c) It's a user with 'Settings' create permission
      allow create: if isAuthenticated() && (request.auth.uid == userId || isCEO() || can('Settings', 'create'));

      // Allow updates if self or admin
      allow update: if isAuthenticated() && (request.auth.uid == userId || isCEO() || can('Settings', 'edit'));

      // Delete restricted to admins
      allow delete: if isAuthenticated() && (isCEO() || can('Settings', 'delete'));
    }

    // 3. Roles & Permissions 
    // Must be readable by all authenticated users so the frontend can determine UI visibility
    match /roles/{roleId} {
      allow read: if isAuthenticated();
      allow write: if isAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    match /role_permissions/{roleId} {
      allow read: if isAuthenticated();
      allow write: if isAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    // 4. Activity Logs
    match /activity_logs/{logId} {
      allow read: if isAuthenticated(); // Allow users to see history
      allow create: if isAuthenticated(); // Any auth user can log an action
      allow update, delete: if false; // Audit trail is immutable
    }

    // 5. Clients Module
    match /clients/{clientId} {
      allow read: if isAuthenticated() && (isCEO() || can('Clients', 'view'));
      allow create: if isAuthenticated() && (isCEO() || can('Clients', 'create'));
      allow update: if isAuthenticated() && (isCEO() || can('Clients', 'edit'));
      allow delete: if isAuthenticated() && (isCEO() || can('Clients', 'delete'));
    }

    // 6. Leads Management Module
    match /leads/{leadId} {
      allow read: if isAuthenticated() && (isCEO() || can('Leads Management', 'view'));
      allow create: if isAuthenticated() && (isCEO() || can('Leads Management', 'create'));
      allow update: if isAuthenticated() && (isCEO() || can('Leads Management', 'edit'));
      allow delete: if isAuthenticated() && (isCEO() || can('Leads Management', 'delete'));
    }

    // 7. Properties (CEO Hub / Admin)
    match /properties/{propertyId} {
      // Read allowed for all auth users (used in dropdowns, forms)
      allow read: if isAuthenticated(); 
      allow create: if isAuthenticated() && (isCEO() || can('CEO Hub', 'create'));
      allow update: if isAuthenticated() && (isCEO() || can('CEO Hub', 'edit'));
      allow delete: if isAuthenticated() && (isCEO() || can('CEO Hub', 'delete'));
    }

    // 8. Invoices (Account Management)
    match /invoices/{invoiceId} {
      allow read: if isAuthenticated() && (isCEO() || can('Account Management', 'view') || can('Clients', 'view'));
      allow create: if isAuthenticated() && (isCEO() || can('Account Management', 'create'));
      allow update: if isAuthenticated() && (isCEO() || can('Account Management', 'edit'));
      allow delete: if isAuthenticated() && (isCEO() || can('Account Management', 'delete'));
    }

    // 9. Promotions
    match /promotions/{promoId} {
      allow read: if isAuthenticated(); // Visible to all staff
      allow create: if isAuthenticated() && (isCEO() || can('Promotions', 'create'));
      allow update: if isAuthenticated() && (isCEO() || can('Promotions', 'edit'));
      allow delete: if isAuthenticated() && (isCEO() || can('Promotions', 'delete'));
    }

    // 10. Amendments
    match /amendments/{docId} {
      allow read: if isAuthenticated() && (isCEO() || can('Clients', 'view'));
      allow create: if isAuthenticated() && (isCEO() || can('Clients', 'edit'));
      allow update: if isAuthenticated() && (isCEO() || can('Clients', 'approve')); 
      allow delete: if isAuthenticated() && (isCEO() || can('Clients', 'delete'));
    }
  }
}

import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import LeadsManagementPage from './pages/LeadsManagementPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import PlaceholderPage from './pages/PlaceholderPage';
import MappingsPage from './pages/MappingsPage';

import { DataProvider, usePermissions } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { GENERATED_REPORTS } from './data/mockData';
import { Client, PermissionSet } from './types';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { 
    useClients, useProperties, useInvoices, useStaff, useLeads, 
    usePromotions, useActivityLogs, useRoles, useAmendments, useCompanySettings 
} from './hooks/useAppData';

const queryClient = new QueryClient();

const AppContent: React.FC = () => {
    // --- Data Hooks ---
    const { clients, saveClient, deleteClient } = useClients();
    const { properties, saveProperty } = useProperties();
    const { invoices, saveInvoice } = useInvoices();
    const { staff, updateStaff } = useStaff(); 
    const { leads, saveLead, deleteLead } = useLeads();
    const { promotions, savePromotion, deletePromotion } = usePromotions();
    const { activityLogs, addActivityLog } = useActivityLogs();
    const { roles, setRoles } = useRoles();
    const { amendments, setAmendmentList } = useAmendments();
    const { companySettings, setCompanySettings } = useCompanySettings();
    const { rolePermissions } = usePermissions();

    const { currentStaff, login, logout, isAuthenticated } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    // Dynamic Favicon Update
    useEffect(() => {
        if (companySettings.favicon) {
            let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
            if (!link) {
                link = document.createElement('link');
                link.rel = 'icon';
                document.head.appendChild(link);
            }
            link.href = companySettings.favicon;
        }
    }, [companySettings.favicon]);

    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        setActivePage(page);
        setPageContext(context);
    };

    // Calculate Permissions based on the User's Role ID from the Context.
    const staffPermissions = useMemo(() => {
        if (!currentStaff) return {};
        const userPermissions: { [key: string]: PermissionSet } = {};

        // Find all permissions associated with the current staff's role ID
        const rolePerms = rolePermissions.filter(rp => rp.roleId === currentStaff.roleId);

        rolePerms.forEach(rp => {
            userPermissions[rp.moduleId] = rp.permissions;
        });

        // Fallback/Default if no permissions found
        if (Object.keys(userPermissions).length === 0) {
             userPermissions['Dashboard'] = { view: true, create: false, edit: false, delete: false, approve: false };
        }

        return userPermissions;
    }, [currentStaff, rolePermissions]);

    if (!isAuthenticated || !currentStaff) {
        return <LoginPage onLogin={login} companySettings={companySettings} />;
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard':
                return <Dashboard />;
            case 'Clients':
                return <ClientsPage 
                    clients={clients} 
                    onSaveClient={saveClient}
                    onDeleteClient={deleteClient}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]}
                    onClientSelect={(client) => handleSetPage('Client Details', client)} 
                    setActivePage={handleSetPage}
                    setClientForInvoice={setClientForInvoice}
                    invoices={invoices}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Client Details':
                return <ClientDetailPage 
                    client={pageContext} 
                    properties={properties}
                    onBack={() => handleSetPage('Clients')}
                    currentStaff={currentStaff}
                    roles={roles}
                    setActivePage={handleSetPage}
                />;
            case 'Account Management':
                 return <AccountManagementPage 
                    clients={clients}
                    onSaveClient={saveClient}
                    onClientSelect={(client) => handleSetPage('Client Details', client)}
                    invoices={invoices}
                    onSaveInvoice={saveInvoice}
                    clientForInvoice={clientForInvoice}
                    setClientForInvoice={setClientForInvoice}
                    receiptPattern={null} 
                    setReceiptPattern={() => {}}
                    setReceiptAlerts={() => {}}
                    currentStaff={currentStaff}
                 />;
            case 'Settings':
                return <SettingsPage 
                    currentStaff={currentStaff} 
                    staff={staff}
                    roles={roles}
                    setRoles={setRoles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    companySettings={companySettings}
                    setCompanySettings={setCompanySettings}
                    onUpdateStaff={updateStaff}
                />;
            case 'CEO Hub':
                 return <CEOHub
                    setActivePage={handleSetPage}
                    properties={properties}
                    clients={clients}
                    invoices={invoices}
                    staff={staff}
                    roles={roles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    addActivityLog={handleAddActivityLog}
                />;
             case 'Properties':
                return <PropertiesPage properties={properties} currentStaff={currentStaff} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
             case 'New Land Acquisition':
                return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
             case 'Promotions':
                return <PromotionsPage 
                    promotions={promotions} 
                    onSavePromotion={savePromotion}
                    onDeletePromotion={deletePromotion}
                    properties={properties} 
                    showForm={true} 
                    onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} 
                />;
            case 'Administration':
                return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Lead Management & Follow-Up':
                return <LeadsManagementPage 
                    leads={leads} 
                    onSaveLead={saveLead}
                    onDeleteLead={deleteLead}
                    clients={clients} 
                    onSaveClient={saveClient}
                    staffList={staff} 
                    roles={roles}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }]} 
                    currentStaff={currentStaff} 
                    addActivityLog={handleAddActivityLog} 
                />;
            case 'Human Resources':
                return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts':
                return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot':
                return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation':
                return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Mappings':
                return <MappingsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Amendment Form':
                return (
                    <AmendmentFormPage 
                        client={pageContext} 
                        onBack={() => handleSetPage('Client Details', pageContext)} 
                        onSave={async (data, updatedClient) => { 
                            setAmendmentList(prev => [data, ...prev]); 
                            await saveClient(updatedClient);
                            handleAddActivityLog('Update', `Processed amendment request for client: ${updatedClient.name}`);
                            alert('Amendment processed and client record updated successfully!'); 
                            handleSetPage('Client Details', updatedClient);
                        }} 
                        currentStaff={currentStaff} 
                    />
                );
            case 'Analytics & Reports':
                return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports':
                return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity':
                return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Mailing':
            case 'Leave':
            case 'Knowledge Base':
            case 'Event':
            case 'Announcement':
            case 'Support':
                return <PlaceholderPage title={activePage} onBack={() => handleSetPage('Dashboard')} />;
            default:
                return <div>Page not found</div>;
        }
    };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff} 
            onLogout={logout}
            staffPermissions={staffPermissions}
            companySettings={companySettings}
        >
            {renderPage()}
        </Layout>
    );
};

const App: React.FC = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <AuthProvider>
                    <DataProvider>
                        <AppContent />
                    </DataProvider>
                </AuthProvider>
            </ThemeProvider>
        </QueryClientProvider>
    );
};

export default App;

import React, { createContext, useContext, useEffect, useState } from 'react';
import * as dbService from '../services/dbService';
import { RolePermission, AppModuleName } from '../types';
import { useAuth } from './AuthContext';

interface PermissionsContextType {
    rolePermissions: RolePermission[];
    updateRolePermission: (roleId: string, moduleId: AppModuleName, permission: string, value: boolean) => Promise<void>;
    initRolePermissions: (roleId: string) => Promise<void>;
}

const DataContext = createContext<PermissionsContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { isAuthenticated } = useAuth();
    const [rolePermissions, setRolePermissionsState] = useState<RolePermission[]>([]);

    useEffect(() => {
        let unsubscribe = () => {};

        if (isAuthenticated) {
            // Subscribe to real-time changes in role_permissions collection only when authenticated
            unsubscribe = dbService.listenToRolePermissions((perms) => {
                setRolePermissionsState(perms);
            });
        } else {
            setRolePermissionsState([]);
        }

        return () => unsubscribe();
    }, [isAuthenticated]);

    const updateRolePermission = async (roleId: string, moduleId: AppModuleName, permission: string, value: boolean) => {
        await dbService.updateRolePermissionInDb(roleId, moduleId, permission, value);
    };

    const initRolePermissions = async (roleId: string) => {
        await dbService.initRolePermissions(roleId);
    }

    return (
        <DataContext.Provider value={{
            rolePermissions,
            updateRolePermission,
            initRolePermissions,
        }}>
            {children}
        </DataContext.Provider>
    );
};

export const usePermissions = () => {
    const context = useContext(DataContext);
    if (context === undefined) {
        throw new Error('usePermissions must be used within a DataProvider (PermissionsProvider)');
    }
    return context;
};

/**
 * @deprecated Use specific hooks (useClients, useStaff, etc.) or usePermissions instead.
 */
export const useData = () => {
     return usePermissions(); 
};

import React from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import * as dbService from '../services/dbService';
import { auth } from '../services/firebase';
import { COMPANY_SETTINGS } from '../data/mockData';
import { 
    Client, Property, Invoice, Staff, Lead, Promotion, 
    ActivityLog, Role, AmendmentRequest, CompanySettings 
} from '../types';

// --- Clients ---
export const useClients = (searchTerm: string = '') => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: clients = [], isLoading } = useQuery({
        queryKey: ['clients', searchTerm],
        queryFn: () => searchTerm ? dbService.searchClients(searchTerm) : dbService.fetchClients(),
        staleTime: 1000 * 60 * 5, 
        enabled: isAuthenticated,
    });

    const saveClientMutation = useMutation({
        mutationFn: dbService.persistClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const deleteClientMutation = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    return {
        clients,
        isLoading,
        saveClient: async (client: Client) => { 
            await saveClientMutation.mutateAsync(client); 
            return client; 
        },
        deleteClient: async (id: number) => { 
            await deleteClientMutation.mutateAsync(id); 
        },
        hasNextPage: false,
        fetchNextPage: () => {},
        isFetchingNextPage: false
    };
};

// --- Properties ---
export const useProperties = () => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: properties = [] } = useQuery({
        queryKey: ['properties'],
        queryFn: dbService.fetchProperties,
        staleTime: 1000 * 60 * 10,
        enabled: isAuthenticated,
    });

    const savePropertyMutation = useMutation({
        mutationFn: dbService.persistProperty,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['properties'] })
    });

    return {
        properties,
        saveProperty: async (property: Property) => { 
            await savePropertyMutation.mutateAsync(property); 
        }
    };
};

// --- Invoices ---
export const useInvoices = () => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: invoices = [] } = useQuery({
        queryKey: ['invoices'],
        queryFn: dbService.fetchInvoices,
        staleTime: 1000 * 60 * 5,
        enabled: isAuthenticated,
    });

    const saveInvoiceMutation = useMutation({
        mutationFn: dbService.persistInvoice,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['invoices'] })
    });

    return {
        invoices,
        saveInvoice: async (invoice: Invoice) => { 
            await saveInvoiceMutation.mutateAsync(invoice); 
        }
    };
};

// --- Staff ---
export const useStaff = () => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: staff = [] } = useQuery({
        queryKey: ['staff'],
        queryFn: dbService.fetchStaff,
        staleTime: 1000 * 60 * 5,
        enabled: isAuthenticated,
    });

    const saveStaffMutation = useMutation({
        mutationFn: dbService.persistStaff,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    const deleteStaffMutation = useMutation({
        mutationFn: dbService.removeStaff,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    return {
        staff,
        saveStaff: async (staffMember: Staff) => { 
            await saveStaffMutation.mutateAsync(staffMember); 
        },
        deleteStaff: async (id: string) => { 
            await deleteStaffMutation.mutateAsync(id); 
        },
