                    if (txn.date && (txn.status === 'Success' || !txn.status)) {
                        // Extract YYYY-MM
                        const month = txn.date.substring(0, 7); 
                        // Validate format loosely (e.g., 2024-05)
                        if (month.length === 7 && month.includes('-')) {
                             monthlyRevenue[month] = (monthlyRevenue[month] || 0) + (txn.amount || 0);
                        }
                    }
                });
            } 
            // Scenario B: Fallback - Client has paid amount but no history (e.g. imported data)
            else if ((client.payment?.paid || 0) > 0 && client.regDate) {
                const month = client.regDate.substring(0, 7);
                if (month.length === 7 && month.includes('-')) {
                    monthlyRevenue[month] = (monthlyRevenue[month] || 0) + client.payment.paid;
